COLLDATA("shuabimanur","ur",[[1565,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے ان کو داؤد بن محمد بن عباس نے کوفے میں ان کو ابو الحریش احمد بن عیسیٰ نے ان کو مؤمل بن اھاب نے ان کو عبد اللہ بن موسیٰ نے ان کو ابن ابی لیلیٰ نے ان کو عدی بن ثابت نے ان کو سیدنا براء نے فرماتے ہیں کہ رسول اللہ نے فرمایا اہل عرب کی محبت ایمان کا حصہ ہے اور ان کے ساتھ بغض نفاق ہے اسی طرح اس کو لائے ہیں اور شعبہ سے عدی بن ثابت سے براء سے یہی مفہوم انصار کے بارے میں مروی ہے۔ (1)","",{"k":"(1) كلمة غير واضحة۔"}],[1566,"بے شک یہی متن یحییٰ بن حماد سے حضرت ثابت سے اور انس رضی اللہ تعالیٰ عنہ معروف ہے۔ (1)","",{"k":"(1) أخرجه الحاكم (۸۷/۴) من طريق ثابت عن أنس بن مالک۔ ی"}],[1567,"ہمیں خبر دی ہے ابو نصر بن قتادہ نے ان کو خبر دی ابو الحسن بن اسماعیل سراج نے ان کو مطین نے ان کو علاء بن عمرو حنفی نے ان کو یحییٰ بن یزید شعری نے ان کو ابن جریج سے ان کو عطاء نے ان کو ابن عباس نے وہ کہتے ہیں رسول اللہ نے فرمایا تین باتوں کی وجہ سے عرب سے محبت کرو: ❶ اس لئے کہ میں عربی ہوں۔ ❷ اور قرآن عربی میں ہے۔ ❸ اور اہل جنت کا کلام عربی ہے۔\nاس روایت میں علاء بن عمرو کا یحییٰ بن یزید سے تفرد ہے۔ (1)","",{"k":"(1) سبق برقم (۱۴۳۲)۔"}],[1568,"ہمیں خبر دی ہے ابو علی روذباری نے اور ابو عبد اللہ بن برہان نے اور ابو الحسین بن فضل نے اور ابو محمد سکری نے انہوں نے کہا کہ ہمیں خبر دی ہے اسماعیل بن محمد صفار نے ان کو حسین بن عرفہ نے ان کو عیسیٰ بن مرحوم قطان نے ان کو عبد المھیمن بن عباس بن سہل بن سعد ساعدی نے ان کے والد سے اس نے ان کے دادا سے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا قریش کے ساتھ محبت کرو جو شخص ان سے محبت کرے گا اللہ اس سے محبت کرے گا۔ (1)","",{"k":"(1) أخرجه ابن أبي عاصم (۶۴۱/۲) عن يعقوب بن حميد عن عبد المهيمن بن عباس۔ به۔ وأخرجه الطبراني في الكبير (۱۵۰/۶) وقال الهيثمي في المجمع (۲۷/۱۰) عن المهيمن ضعيف۔"}],[1569,"ہمیں خبر دی ہے ابو سہل محمد بن نصرویہ مروزی نے ان کو ابو الحسن علی بن ابراہیم طغامی نے ان کو ابو شہاب معمر بن محمد صوفی نے ان کو یحییٰ بن ابراہیم نے ان کو مطرف بن معقل نے ان کو ثابت بنانی نے ان کو انس بن مالک نے ان کو عمر بن خطاب رضی اللہ تعالیٰ عنہ نے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا جو شخص اہل عرب کو گالی دے وہی لوگ مشرک ہیں۔ اس روایت میں مطرف کا تفرد ہے اور یہ روایت اسی اسناد کے ساتھ منکر ہے۔ (1)","",{"k":"(1) الطغامی نسبة إلى طغامی من سواد بخاری والمشهور منها أبو الحسن علي بن إبراهيم بن أحمد بن عثمان الطغامی صاحب الأوقاف (اللباب ۲۸۲/۲)۔"}],[1570,"ہمیں خبر دی ہے ابو علی حسن بن احمد بن ابراہیم بن شاذان نے ان کو عبد اللہ بن جعفر نحوی نے ان کو یعقوب بن سفیان نے ان کو ابو شیبہ نے ان کو ابو بکر بن ابو شیبہ نے ان کو حسن بن بشر نے ان کو مروان بن معاویہ نے ان کو ثابت بن عمارہ حنفی نے غنیم بن قیس سے انہوں نے ابو موسیٰ اشعری سے انہوں نے کہا کہ رسول اللہ نے فرمایا کہ میں نے اہل عرب کے لئے دعا کی ہے میں نے کہا اے اللہ جو شخص ان میں تجھ سے اس حال میں ملاقات کرے کہ تیرے ساتھ یقین رکھے اور تیری تصدیق کرے اسے اس کے ایام حساب میں معاف کر دینا اور یہی دعا تھی ابراہیم علیہ السلام اور اسماعیل علیہ السلام کی۔\nبے شک مرد ان کی طرف سے ہے۔ اور بے شک حمد والا جھنڈا قیامت کے دن میرے ہاتھ میں ہوگا اور مخلوقات میں میرے جھنڈے کے قریب تر لوگ اس دن اہل عرب ہوں گے۔ (1)","",{"k":"(1) قال الهيثمي (۵۲/۱۰) أخرجه الطبراني، وروى البزار منه اللهم من لقيك منهم مصدقا بک وموقنا فاغفر له فقط۔ ورجالهما ثقات۔ أخرجه ابن عدی (۱۰۵۹/۳ و ۱۰۶۰) في ترجمة زيد بن جبير المدني أبو جبيرة۔ ثنا علي بن العباس ثنا عباد بن يعقوب عن إسماعيل بن عياش۔ به۔ وقال ابن عدی: عامة ما يرويه زيد بن جبير عن من روى عنهم لا يتابعه عليه أحد۔"}],[1571,"ہمیں خبر دی ہے ابو سعید مالینی نے ان کو ابو احمد بن عدی حافظ نے ان کو عمر بن سنان نے ان کو ہشام بن عمار نے ان کو اسماعیل بن عیاش نے ان کو زید بن جبیر نے ان کو داؤد بن حصین نے ان کو ابن ابو رافع نے ان کو علی نے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا فرماتے تھے جو شخص میری عقیدت کا حق نہ پہچانے اور انصار کا اور عرب کا تو وہ تین میں سے ایک ہے یا منافق ہے یا مزینہ ہے یا بوجہ غیر ہے یا رائی ہے اسے اس کی ماں نے غیر پاکیزگی میں حمل اٹھایا ہے۔ زید بن جبیر اس روایت میں غیر قوی ہے۔\nعرب کی فضیلت\nاور احادیث عرب کی فضیلت میں اور قریش کی فضیلت میں کثیر ہیں یہ موضوع ان سب کے لانے کا متحمل نہیں ہے اور وہ قول جس کی طرف بعض لوگ مائل ہوئے ہیں عجمیوں کی عربوں پر فضیلت کے بارے میں وہ اس حقیقت کے خلاف ہے جس پر اس امت کا اولین طبقہ تھا۔ اور وہ احادیث جو اس بارے میں آئی ہیں ان میں سے اکثر باطل ہیں۔ اہل علم کے لئے مناسب نہیں ہے کہ ایسے شخص کے مذہب کے ساتھ اشتعال رکھے۔ اور فضیلت عرب کی بابت جو روایات آئی ہیں ان میں ہے کہ اللہ تعالیٰ نے اپنے اہل رسالت عرب سے بھیجے اور آخری کتاب عرب کی زبان میں اتاری لہذا لوگوں پر فرض ہو چکا ہے کہ وہ عرب کی زبان سیکھیں اگرچہ یہ بات فرائض کفایہ میں سے ہے تا کہ اللہ تعالیٰ کی طرف سے اس کے امر کو اور اس کی نہی کو اور اس کے وعد کو اور وعید کو سمجھیں اللہ کے رسول کی طرف سے اس کے بیان کو اس کی تبلیغ کو اور آپ نے حکم فرمایا کہ امام اور خلفاء قریش سے ہوں گے شیخ حلیمی رحمۃ اللہ علیہ نے اس بارے میں ایک طویل فصل ذکر کی ہے جو شخص چاہے اس میں نظر ڈالے۔"],[1572,"ہمیں خبر دی ابو محمد عبد اللہ بن یحییٰ سکری نے بغداد میں ان کو ابو بکر شافعی نے ان کو جعفر بن محمد بن ازہر نے ان کو علاء نے ان کو یحییٰ بن معین نے ان کو ہشام بن یوسف نے ان کو عبد اللہ بن سلیمان نوفلی نے زہری سے ان کو عروہ نے ان کو سیدہ عائشہ رضی اللہ تعالیٰ عنہ نے اس آیت کے بارے میں فرماتی ہیں۔\n﴿لقد من اللہ علی المؤمنین اذ بعث فیھم رسولاً﴾\n’’البتہ تحقیق اللہ نے مؤمنوں پر احسان فرمایا جب ان میں رسول بھیج دیا ہے۔‘‘\nسیدہ نے فرمایا یہ عرب کے لئے خاص ہے۔"],[1573,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو عمرو بن سماک نے ان کو حمرون بن احمد سمسار نے ان کو اذرق بن علی نے ان کو حبان بن ابراہیم نے ان کو سفیان ثوری نے ان کو موسیٰ بن عائشہ نے ان کو سلیمان نے ان کو سیدنا عباس رضی اللہ عنہ نے اللہ تعالیٰ کے اس قول کے بارے میں ﴿وانہ لذکر لک و لقومک﴾، یہ قرآن نصیحت ہے تیرے لئے اور تیری قوم کے لئے۔ فرمایا کہ اس کا مطلب کہ یہ قرآن شرف و فضیلت ہے تیرے لئے اور تیری قوم کے لئے اور اللہ تعالیٰ کا یہ فرمان ﴿لقد انزلنا الیکم کتاباً فیہ ذکرکم﴾۔ ہم نے تمہاری طرف کتاب اتاری ہے۔ اس میں تمہاری نصیحت ہے۔ مراد ہے کہ اس میں تمہارا شرف ہے۔"],[1574,"ہمیں خبر دی ہے محمد بن عبد اللہ حافظ نے ان کو حسین بن حسن بن ایوب نے ان کو ابو یحییٰ بن ابو میسرہ نے ان کو ابراہیم بن منذر نے ان کو عبد العزیز بن عمران نے ان کو اسماعیل بن ابراہیم بن ابو حبیبہ نے ان کو داؤد بن حصین نے ان کو عکرمہ نے ان کو ابن عباس رضی اللہ عنہ نے وہ فرماتے ہیں کہ پہلا شخص جس نے عربی زبان بولی تھی اور اس کے بعد اس نے اپنے تلفظ اور اپنی بولی کو تحریر کی شکل دی اس کے بعد اس نے اسے ایک کتاب اور ایک تحریر بنایا جیسے۔ بسم اللہ الرحمن الرحیم۔ ملا کر لکھا یہاں تک کہ ان کے مابین فرق کیا علامات سے؟ وہ شخص اسماعیل بن ابراہیم علیہ السلام تھے۔ (1)","",{"k":"(1) أخرجه الحاكم (۵۵۲/۲۔ ۵۵۳) بنفس الإسناد وصححه الحاكم وقال الذهبي: عبد العزيز واه۔ في المستدرک (بينه)۔"}],[1575,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے وہ کہتے ہیں کہ مجھے حدیث بیان کی ابو الحسن اسماعیل بن محمد بن فضل شعرانی نے ان کو ان کے دادا ثابت محمد بن عبید اللہ مدنی نے ان کو ابراہیم بن سعد نے سفیان ثوری سے انہوں نے جعفر بن محمد سے انہوں نے اپنے والد سے انہوں نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے کہ آپ نے فرمایا اللہ تعالیٰ نے ابراہیم علیہ السلام کو الہام فرمایا اور الہام کی ابتدا عربی زبان کے الہام سے فرمائی۔ (1)","",{"k":"(1) أخرجه المصنف من طريق الحاكم (۳۴۳/۲۔ ۳۴۴) وقال الحاكم: هذا حديث غريب صحيح على شرط الشيخين إن كان الفضل بن محمد حفظه متصلاً عن ابن ثابت۔"}],[1576,"ہمیں خبر دی ابو عبد اللہ نے ان کو ابو علی حافظ نے ان کو ابو عبد الرحمن نسائی نے انہوں نے عبید اللہ بن سعد زہری سے انہوں نے اپنے چچا سے انہوں نے اپنے والد سے انہوں نے سفیان سے انہوں نے جعفر بن محمد سے انہوں نے اپنے والد سے انہوں نے رسول اللہ سے مذکور کی مثل بطور مرسل حدیث روایت کی اور وہی محفوظ ہے۔ (1)","",{"k":"(1) المستدرک (۳۴۴/۲) بنفس الإسناد۔"}],[1577,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو الحسن احمد بن خضر شافعی نے ان کو ابو اسحاق ابراہیم بن الحق عسیلی نے ان کو عبید اللہ بن سعد بن ابراہیم زہری نے ان کو ان کے چچا نے انہوں نے کہا کہ مجھے حدیث بیان کی ہے میرے والد نے ان کو سفیان ثوری نے ان کو جعفر بن محمد نے اپنے والد سے اس نے سیدنا جابر رضی اللہ عنہ سے کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ آیت تلاوت فرمائی۔\n﴿قرانا عربياً لقوم يعلمون﴾\n’’یہ قرآن عربی ہے اس قوم کے لئے جو جانتے ہیں۔‘‘\nاس کے بعد رسول اللہ نے فرمایا کہ اسماعیل علیہ السلام کو اس زبان کا الہام کیا گیا تھا۔ (1)","",{"k":"(1) أخرجه الحاكم (۴۳۹/۲) بنفس الإسناد وقال الذهبي: مدار الحديث على إبراهيم بن إسحاق العسيلي وكان ممن يسرق الحديث۔"}],[1578,"§حضرت اسماعیل علیہ السلام کو عربی زبان الہام کی گئی\nاس حدیث میں آیا ہے جو ثابت سے معمر سے کثیر بن مطلب سے اور ایوب یزید ہے دونوں میں سے ہر ایک نے دوسرے کو بیان کی سعید بن جبیر سے اسماعیل علیہ السلام کے قصہ کے بارے میں اور زم زم کے بارے میں اور قوم جرھم کے وادی مکہ میں نزول کے بارے میں۔ ابن عباس نے فرمایا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا تھا۔ ام اسماعیل کو اس زبان کا القاء کیا گیا تھا۔ یعنی یہ زبان ان کے دل میں ڈالی گئی تھی اور (اکیلی ہونے کی وجہ سے) انس چاہتی تھیں۔ لہذا جرھم کے لوگ اس کے پاس اتر پڑے یہاں تک کہ ان میں اہل بیان پیدا ہو گیا اور لڑکا جوان ہو گیا۔ یعنی حضرت اسماعیل علیہ السلام اور اس نے ان میں سے عربی کے ساتھ کلام کیا اور بڑا نفیس کلام کیا اور عجیب کلام کیا جب وہ جوان ہو گیا تو ان لوگوں نے اپنے قبیلے کی ایک عورت سے اس کی شادی کر دی۔ (1)","",{"k":"(1) أخرجه أحمد (۳۴۷/۱) عن عبد الرزاق عن معمر۔ به۔"}],[1579,"ہمیں خبر دی ہے ابو عبد اللہ نے ان کو علی بن حسین قاضی نے بخارا میں ان کو عبد اللہ بن محمود نے ان کو محمد بن علی بن شقیق نے ان کو ابو تحمیلہ نے ان کو حسین بن واقد نے ان کو عبد اللہ بن بریدہ نے ان کو ان کے والد نے کہ (اس آیت کا مطلب) ﴿لسان عربی مبین﴾۔ یہ زبان واضح عربی ہے کہتے ہیں کہ قوم جرھم کی زبان مراد ہے۔ (1)","",{"k":"(1) أخرجه المصنف من طريق الحاكم (۴۳۹/۲) وفي المستدرک (عبد اللہ بن محمود ابن شقيق) بدلاً من (عبد اللہ بن محمود عن محمد بن علي بن شقيق)۔ في الأصل (وهيب بن وهيب) وما اثبتناه من مختصر الشعب۔"}],[1580,"§ایمان کا سولہواں شعبہ\nوہ یہ ہے کہ انسان اپنے دین کے معاملے میں حساس ہو چکا ہو (تیزی نفس کا شکار ہو) یہاں تک کہ اس کے نزدیک کفر کی طرف لوٹ جانے سے آگ میں گر جانا زیادہ محبوب ہو اس مقام پر مصنف رحمۃ اللہ علیہ نے شح المرء بدینہ کا جملہ استعمال فرمایا ہے الشح لغت میں بخل اور حرص طمع وغیرہ کو کہتے ہیں۔ اور رسول اللہ صلی اللہ علیہ وسلم کے اصحاب کی ہجرت دیار کفار سے اسی طرز کی تھی تا کہ وہ حضور صلی اللہ علیہ وسلم سے مل جائیں اور آپ کی صحبت اختیار کر لیں اور آپ کے ساتھ ہجرت کریں۔ پھر یہ ہجرت کا حکم اس شخص کے حق میں باقی ہے آج بھی جس کے لئے اپنی جگہ رہ کر دین کا اظہار ممکن نہ ہو اور ہم نے اس مسئلہ میں کتاب السیر میں کتاب السنن سے کلام کیا ہے۔ اور ہم نے اپنی کتاب دلائل النبوۃ میں وہ روایت کی ہے اصحاب رسول کو جو شدائد اور مشکلات درپیش تھے کفار کے مقابلے کے لئے یہاں تک کہ وہ ارض حبشہ کی طرف ہجرت کرنے کا حکم دیئے گئے اس کے بعد مدینہ کی طرف ہجرت کا اللہ تعالیٰ ہمیں اپنے اسلاف سے عملی نسبت عطا فرمائے ہمارے اسلاف بہترین اسلاف تھے اللہ ان سے راضی ہو۔\nیہ اس لئے کہ نبی کریم صلی اللہ علیہ وسلم سے حدیث وارد ہوئی ہے۔\nالشح بخل اور حرص یا لالچ کو کہتے ہیں۔\nقد شحت شح شیخ تم نے بخل کیا۔ طمع کیا محاورہ ہے۔\nالرجل شح بخیل شخص۔\nقوم شحاح واشحہ بخیل لوگ۔\n§تشاح الرجلان على الاقر لايريد ان يفويتهما\nدو آدمیوں نے ایک دوسرے پر کسی معاملے پر بخل کیا ان میں سے کوئی بھی نہیں چاہتا تھا کہ فائدہ اٹھایا یا اس سے رہ جائے یا اس کا موقع وہ ضائع کر دے مختار الصحاح ص ۴۶۷۔\nشح المرء بدینہ۔ آدمی کا اپنے دین کے ساتھ بخل کرنا یہ ہے کہ وہ اپنے دین کے معاملے میں پکا ہو ہوشیار ہو حساس ہو دین کو ہاتھ سے نہ جانے دے جان جائے مگر ایمان نہ جانے کا مصداق ہو میں نے اپنی سمجھ کے مطابق لفظ بخل کو اس موقع پر ترک کر دیا ہے جس میں ایک گونہ کراہت طمع کا سامان ہے میں نے اس جگہ دین کے معاملے میں تیز ہونا پکا ہونا۔ ہوشیار ہونا اور حساس ہونا تجویز کیا ہے۔ کہ انسان اپنے دین کو بچانے کے لئے پکا ہو تیز ہو۔ ہوشیار ہو حساس ہو۔ اس قدر کہ کفر کی طرف پلٹنے سے آگ میں گرا دیا جانا اس کو زیادہ محبوب ہو۔\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو العباس محمد بن یعقوب نے ان کو ابراہیم بن مرزوق نے ان کو وھب بن جریر نے اور بشر بن عمر نے دونوں کہتے ہیں ہمیں حدیث بیان کی ہے شعبہ نے قتادہ سے انہوں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے فرماتے ہیں کہ رسول اللہ نے فرمایا۔ تین صفات ہیں جس شخص میں موجود ہوں وہ ایمان کی حلاوت اور مٹھاس پالیتا ہے۔ جس کے نزدیک اللہ اور اللہ کا رسول ان کے ماسوا سے زیادہ محبوب ہوں۔ اور وہ شخص جو کسی سے محبت محض اللہ تعالیٰ کے لئے کرتا ہو، اور جو شخص آگ میں جل جانا زیادہ محبوب رکھے کفر کی طرف لوٹ جانے سے اس کے بعد کہ جب اللہ نے اسے اس آگ سے بچالیا ہے۔ بخاری مسلم نے اس کو صحیح میں نقل کیا ہے شعبہ بن حجاج کی حدیث سے۔ (1)","",{"k":"(1) سبق برقم (۱۳۷۷)۔"}],[1581,"§ایمان کی حلاوۃ کا نصیب ہونا\nہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو بکر محمد بن احمد بالویہ نے (ح) اور ہمیں خبر دی ہے ابو الحسین بن فضل قطان نے ان کو ابو سہل بن زیاد نے دونوں کو اسحاق بن حسن حربی نے ان کو حماد بن سلمہ نے ان کو ثابت بنانی نے ان کو انس بن مالک رضی اللہ تعالیٰ عنہ نے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تین خصلتیں ایسی ہیں کہ وہ جس شخص میں پیدا ہو جائیں وہ ایمان کی لذت اور مٹھاس کو پالیتا ہے۔ جس شخص کے دل میں اللہ اور رسول کی محبت ان کے تمام ماسوا سے زیادہ ہو۔ وہ شخص جو کسی سے صرف اللہ واسطے کی محبت کرتا ہو وہ شخص جو اسلام سے پھر کر یہودی اور عیسائی بن جانے کو اتنا برا سمجھے کہ اگر اسے آگ میں پھینک دیا جائے تو یہ اس کو زیادہ محبوب ہو مگر اسلام کو چھوڑنا پسند نہ ہو۔ اس کو بخاری مسلم نے دوسرے طریق سے حماد سے نقل کیا ہے۔\nامام بیہقی رحمۃ اللہ علیہ کا قول\nامام بیہقی رحمۃ اللہ علیہ نے فرمایا کہ نبی کریم صلی اللہ علیہ وسلم نے اس حدیث کے ذریعے واضح فرما دیا ہے کہ دین کے معاملے میں پکا ہونا تیز اور حساس ہونا ایمان میں سے ہے اس لئے کہ حلاوۃ کا ذکر ایمان کی مثال ہے، اور آپ کی مراد یہ ہے کہ اپنے دین کے ساتھ تیزی کرنے اور ہوشیار رہنے والا میٹھی چیز کھانے اور اس کا مزہ لینے والے کی مانند ہے جیسے کہ ایمان میں رغبت رکھنے والا اس کا مقصود اس سے پورا نہیں ہوتا مگر یہ کہ اس کے ساتھ تیزی اور ہوشیاری رکھنے والا ہو اس لئے کہ اگر وہ ایمان کے ساتھ تیزی اور ہوشیاری رکھے گا تو اور اس پر پکا ہو گا تو ایسی چیز کا ارتکاب نہیں کرے گا جو اس کے ایمان کو فاسد کر دے اور خراب کر دے جیسے وہ شخص جو میٹھی چیز کی مٹھاس پالیتا ہے تو وہ ایسا کام نہیں کرتا جس سے اس کا وہ میٹھا سا باطل ہو جائے۔ واللہ اعلم۔\nاسی باب میں وہ قصہ بھی داخل ہے جسے اللہ تعالیٰ نے ہم لوگوں پر حضرت شعیب علیہ السلام کی خبر بیان فرمائی ہے جب ان کی قوم نے ان سے کہا تھا:\n﴿لنخرجنك يا شعيب والذين امنوا معك من قريتنا او لتعودن في ملتنا﴾\n’’اے شعیب ہم تمہیں اپنے اپنی بستی سے نکال دیں گے اور ان کو بھی جو تجھے مان چکے ہیں۔ ورنہ تم لوگ ہمارے دین پر واپس آ جاؤ۔‘‘\nچنانچہ حضرت شعیب علیہ السلام نے انہیں جواب دیا تھا۔\n﴿اولو كنا كارهين قد افترينا على الله كذباً ان عدنا في ملتكم بعد اذنجانا منها۔ الخ۔﴾\n’’کیا اگر چہ ہم اس کو ناپسند بھی کرنے والے ہوں، اگر ہم تمہارے دین پر واپس آجائیں تو اس وقت ہم اللہ پر بہت بڑا جھوٹ اور افتراء باندھیں گے اس کے بعد کہ اللہ نے ہمیں اس سے نجات دی ہے۔‘‘\nبے شک اس باب میں متعدد مفہوم ہیں ان سب کا مرجع دین کے ساتھ تیز اور ہوشیار ہونا اور پکا ہونا ہے۔ اول:...... یہ کہ شعیب علیہ السلام نے اپنی قوم کے متکبرین کی تحقیر و تذلیل کو نجات قرار دیا جب کہ یہ حقیقت معلوم ہے کہ نجات کی مقابل چیز ہلاکت ہے جس انسان کے نزدیک کفر ہلاکت ہو اور ایمان نجات ہو وہ انسان اپنے دین کے معاملے میں ہوشیار اور حساس ہی ہوتا ہے اور دین پر انتہائی پکا بھی۔ دوم: اللہ تعالیٰ نے اپنے ارشاد میں اشارہ فرما دیا ہے کہ شعیب علیہ السلام نے کہا تھا علی اللہ توکلنا یہ بتانے کے مقابلہ مکمل اللہ کے سپرد کر دیا تھا پس اگر اس نے اسے ان کی طرف سے ہونے والی جلاوطنی سے بچالیا تو یہ محض اس کا فضل تھا۔ اور وہ ان کو جلاوطن کر ڈالتے جو کچھ ان کا انہیں نکالنے کا ارادہ تھا تو بھی یہ بات انہیں دین کی مفارقت اور دین کی جدائی سے زیادہ محبوب ہے چیز شح بالدین ہے کیونکہ اللہ تعالیٰ نے جلاوطنی کو بمنزلہ قتل کے قرار دیا ہے گویا کہ انہوں نے جلاوطن ہونا پسند کیا مگر دین کو چھوڑنا پسند نہ کیا۔ سوم یہ کہ شعیب علیہ السلام مکمل اللہ کی طرف فارغ ہو گئے تھے اور اللہ سے مدد مانگی تھی اور اللہ کو پکارا تھا جیسے دیگر شدائد میں وہ اللہ ہی کو پکارتے تھے جب انہیں کوئی سخت امور پیش آجائے چنانچہ آپ نے دعا فرمائی تھی۔\nحضرت شعیب علیہ السلام کی دعا\n﴿ربنا افتح بيننا وبين قومنا بالحق﴾\n’’اے ہمارے رب ہمارے اور ہماری قوم کے مابین حق اور انصاف کا فیصلہ فرما۔‘‘\nیہ حضرت شعیب علیہ السلام کی طرف سے اللہ تعالیٰ کی کمال تعظیم ہے جس کی وجہ سے وہ ان الفاظ میں اللہ تعالیٰ سے التجا کر رہے تھے اور یہ توقع کر رہے تھے کہ اللہ تعالیٰ اس سے کفار کی اذیت کو دفع کریں گے وہ ایسے اس کے دین کے معاملے میں کوئی ایسی بات نہ کر سکے گی جو اس پر شاق گذرے یہ ساری باتیں حضرت شعیب علیہ السلام کی طرف سے شح بالدین ہیں دین پر پکا رہنے کی ہیں، اور یہ بھی معلوم ہے کہ یہ ہمارے اوپر اللہ تعالیٰ نے مقرر فرمایا ہے (یعنی دین پر پکا رہنا) یہ اور اس طرح کی دیگر سیرتیں اور زندگیاں جو ہمارے سامنے اس لئے بیان کی گئی ہیں تا کہ ان سے ہم تادیب حاصل کریں اور ایسے لوگوں کے مذاہب کا بیان ہے جن کے طریقے ہمارے لئے بیان ہوئے ہیں۔ اس کے بعد ان میں سے بھی احسن وجہ کی اتباع کا حکم ہے اقبح سے اجتناب کا۔ چنانچہ قرآن نے یہ ہدایت دی ہے۔\n﴿فبشر عباد الذين يستمعون القول فيتبعون احسنه﴾\n’’ان بندوں کو بشارت دے دیجئے جو بات کو توجہ سے سنتے ہیں پھر اس میں سے زیادہ خوبصورت بات کی اتباع کرتے ہیں۔‘‘\nیہ بات صحیح ہوئی کہ دین پر پکا رہنا (شح بالدین) دین کے ارکان میں سے ہے جو شخص کے دل میں دین پر پکا رہنے اور دین کے معاملے میں تیز ہونے اور حساس ہونے کی صفت نہیں پائی جاتی وہ شخص دین کی حلاوت دین مٹھاس دین کی لذت سے آشنا نہیں ہو سکتا۔ یہ وہ امر ہے جس کی صحت کے بارے میں عقل بھی شہادت دیتا ہے اس لئے کہ جو شخص دین کا اعتقاد رکھے پھر اس کے معاملے میں وہ انتہائی پکا نہ ہو اور اس کے ضیاع کے بارے میں ڈرتا نہ ہو تو یہ بات دلالت کرتی ہے اس امر پر کہ اس نے دین کی قدر نہیں پہچانی اور اپنے نفس کے لئے انس میں لذت آشنائی کا مقام بھی نہیں بنایا جس شخص کے نزدیک کوئی حق حقیر ہو وہ حق اس کے سکون قلب کا سامان نہیں کر سکتا۔ اور بچاؤ اللہ کے ہاتھ میں ہے پھر شح بالدین یعنی دین پر پکا ہونا دو قسم کچھ ہے۔\nاول:...... شح اور پکا ہونا تیز ہونا اور حساس ہونا دین کی اصل کے بارے میں تا کہ وہ چلا نہ جائے۔ دوم شح اور پکا ہونا تیز اور حساس ہونا دین کے کامل ہونے کے بارے میں تا کہ وہ ناقص نہ ہو جائے۔ کیا آپ دیکھتے نہیں کہ اللہ تعالیٰ نے جیسے شعیب علیہ السلام کی مدح اور تعریف فرمائی ہے اس بات پر کہ وہ اپنے دین پر پکے رہے اور ڈٹے رہے اسے چھوڑا نہیں اس کے باوجود کہ ان کی قوم نے انہیں اسے چھوڑنے پر مجبور کیا تھا، اسی طرح اللہ تعالیٰ نے یوسف علیہ السلام کی بھی مدح فرمائی ہے بایں طور کہ انہوں نے اللہ سے گناہ سے بچنے کی دعا کی تھی اور عصمت طلب کی تھی جب عزیز مصر کی عورت نے انہیں اپنے نفس کی بابت بہکایا تھا۔ چنانچہ انہوں نے یہ دعا کی تھی:\n﴿رب السجن احب الى مما يدعو ننى اليه﴾\n’’اے میرے رب میرے نزدیک قید زیادہ محبوب ہے اس گندے کام سے جس کی طرف وہ مجھے دعوت دیتی ہیں۔‘‘\nتو گویا واضح ہو گیا کہ یہاں شح اور تیز ہونا حساس ہونا اور بچانا ایمان کے شعبوں کی بابت تھا تا کہ ایمان کم نہ ہو ناقص نہ ہو اور تیزی ایسے ہے جب اصل دین کی بابت ہے تو گویا ثابت ہوا کہ ایمان کے شعبوں پر پکا رہنا ان کی حفاظت کرنا ایسے ضروری ہے جیسے اس کی اصل کی حفاظت لازم اور ضروری ہے تا کہ دین ضائع نہ ہو جائے۔ اور یہی طریقہ ہوتا ہے ہر اس آدمی کا جو فتنے سے ڈرتا ہو۔ اس کی مثال ایسی ہے جیسی کہ بخیل بالمال جیسے اپنے پورے مال کے بارے میں بخیل ہوتا ہے وہ اس کے تھوڑے تھوڑے حصے کے بارے میں بھی بخیل ہوتا ہے یعنی جیسے وہ ایک ہزار کو ضائع کرنے میں بخل سے کام لیتا ہے اسی طرح ایک روپے کے لئے بھی بخل کرتا ہے۔ تا کہ بخل کر کے اس کی حفاظت کر سکے۔ اپنے پورے جسم کے بارے میں بخل کرنے والا اپنے اعضاء کے بارے میں بھی بخل کرتا ہے اسی طرح ایک دیندار انسان بھی اپنے دین کو ضائع کرنے سے بخل کرتا ہے جیسے بخیل انسان کوئی روپیہ پیسہ جانے نہیں دیتا۔ اس کے ایک ایک پیسے کے بارے میں شدت بخل سے کام لیتا ہے اسی طرح ایک دیندار انسان بھی دین کی چھوٹی چھوٹی بات کو ضائع کرنے میں بخل سے کام لیتا ہے تا کہ دین کا کچھ حصہ بھی ضائع نہ ہونے پائے بلکہ وہ اس کی خوب حفاظت کرتا ہے۔ اور دین پر پکا رہنے اور دین کی حفاظت میں سے ہے کہ جب کوئی آدمی ایسے لوگوں میں گھرا ہوا ہو جہاں دین کے حقوق اور تقاضے پورے نہ کر کے بلکہ اسے اندیشہ ہو کہ وہ اسے مزید فتنے میں واقع کردیں گے اور جب ان سے دور ہو جائے گا تو اپنے لئے امن کی جگہ پالے گا اور وہاں اس سے بہتر حال میں ہوگا تو وہ ایسے لوگوں میں نہ رہے بلکہ وہ ایسی جگہ ہجرت کر جائے جہاں سمجھتا ہے کہ وہاں اس کے لئے خیر ہوگی اور وہ زیادہ موافق جگہ ہوگی چنانچہ ارشاد باری تعالیٰ ہے:\n﴿ومن يخرج من بيته مهاجرا الى الله ورسوله ثم يوركه الموت فقد وقع اجره على الله﴾\n’’جو شخص اپنے گھر سے اللہ اور اس کے رسول کی طرف ہجرت کرنے والا نکل جائے۔ پھر اس کو اسی اثنا میں موت آ دبوچے تو اس کا اجر اللہ کے ذمے پکا ہو جاتا ہے۔‘‘ (1)","",{"k":"(1) أخرجه مسلم (۶۷/۱) من طريق النضر بن سهيل عن حماد۔ به۔"}],[1582,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو عبد اللہ محمد بن یعقوب نے ان کو محمد بن عبد الوہاب نے ان کو یعلیٰ بن عبید نے ان کو اعمش نے ان کو ابو مسلم نے ان کو ابو الضحیٰ نے ان کو مسروق نے ان کو خباب نے وہ کہتے ہیں کہ میں ایک لوہار آدمی تھا میرا عاص بن وائل پر قرض تھا میں اس کے پاس اس کا تقاضا کرنے کے لئے گیا اس نے کہا اللہ کی قسم میں تجھے کچھ بھی نہیں دوں گا جب تک کہ آپ محمد صلی اللہ علیہ وسلم کے ساتھ کفر نہیں کریں گے کہتے ہیں میں نے کہا اللہ کی قسم میں کبھی بھی محمد صلی اللہ علیہ وسلم کے ساتھ کفر نہیں کروں گا حتیٰ کہ تم مر جاؤ پھر زندہ ہو جاؤ۔ اس نے کہا جب میں مر جاؤں گا پھر اٹھایا جاؤں گا تم اس وقت میرے پاس آنا میرے پاس وہاں مال بھی ہوگا اور اولاد بھی ہوگی اس وقت میں تیرا قرضہ دے دوں گا اس پر اللہ تعالیٰ نے یہ آیت نازل فرمائی۔\n﴿افرائيت الذى كفر بأياتنا وقال لأوتين مالا وولدا﴾\n’’کیا دیکھا تو نے اس شخص کو جس نے ہماری آیات کے ساتھ کفر کیا اور کہتا ہے مجھے مال بھی دیا جائے گا اور اولاد بھی۔‘‘\nاس کو بخاری مسلم نے دوسرے طریق سے اعمش سے روایت کیا ہے۔ (1)","",{"k":"(1) أخرجه البخارى (۳۱۷/۴۔ فتح) من طريق شعبة عن الأعمش۔"}],[1583,"§سیدنا بلال رضی اللہ عنہ کی دین پر استقامت\nہمیں خبر دی ہے ابو الحسین بن بشران نے ان کو اسماعیل بن محمد صفار نے ان کو احمد بن منصور نے ان کو عبد الرزاق نے ان کو معمر نے ان کو عطاء خراسانی نے وہ کہتے ہیں کہ میں حضرت سعید بن مسیب کے پاس تھا میں نے سیدنا بلال کا تذکرہ کیا کہ وہ اپنے دین پر پکے تھے اور اللہ کے دین کی بابت عذاب دیئے جاتے رہے اور اللہ کی محبت پر عذاب جھیلتے رہے جس وقت مشرک انہیں اذیت پہنچاتے تھے تو وہ کہتے تھے اللہ اللہ۔"],[1584,"§سیدنا خباب رضی اللہ عنہ کی دین کے لئے قربانی دینا\nہمیں خبر دی ابو عبد الرحمن سلمی نے ان کو ابو منصور محمد بن قاسم صبھی نے ان کو اسماعیل بن قتیبہ نے ان کو ابو بکر بن ابو شیبہ نے ان کو ابن عیینہ نے ان کو مسعر نے ان کو قیس بن مسلم نے ان کو صادق بن شہاب نے کہ سیدنا خباب مہاجرین میں سے تھے اور ان لوگوں میں سے تھے جنہیں اللہ پر ایمان کی وجہ سے عذاب دیا جاتا تھا۔"],[1585,"اور اس کی بھی انہوں نے خبر دی ان کو ابو بکر نے ان کو جریر نے ان کو مغیرہ نے ان کو شعبی نے فرمایا کہ دو ان کو جو مانگیں (یعنی ہر سوال کا جواب دو) مگر خباب لوگ رگڑتے تھے اپنی پیٹھوں کو کنکریوں کے ساتھ یہاں تک کہ وہ چلے گئے جو کچھ اس کو منع کرتا ہے۔ (نوٹ: محشی نے ابو ہاجر سعید نے لکھا ہے کہ اس کی مراد واضح نہیں ہے۔)"],[1586,"§سیدنا بلال رضی اللہ عنہ کی احد احد کی صدا لگانا\nہمیں خبر دی محمد بن عبد اللہ حافظ نے ان کو ابو العباس بن یعقوب نے ان کو احمد بن عبد الجبار نے ان کو یونس بن بکیر نے ان کو ہشام بن عروہ نے ان کو ان کے والد نے وہ کہتے ہیں کہ ورقہ بن نوفل سیدنا بلال کے پاس سے گذرتے تھے اور اسلام پر سزا دی جا رہی ہوتی تھی اور وہ کہہ رہے ہوتے تھے احد احد چنانچہ ورقہ بھی یہی کہتے اے بلال احد احد۔"],[1587,"§آل یاسر کی دین کی خاطر قربانی\nاور اس کی اسناد میں عروہ سے روایت ہے کہ ابو بکر صدیق رضی اللہ تعالیٰ عنہ کو آزاد کرایا تھا ان لوگوں میں سے جو دین اسلام پر اللہ کے ساتھ ایمان کی پاداش میں سزا دیئے جاتے تھے...... مگر اسلام کا کلمہ واضح رہے اور مشرکین نے کہا کہ اس کی نظر لات اور عزیٰ نے مار دی ہے خاتون نے کہا نہیں ہرگز نہیں ایسی بات نہیں ہے پھر اللہ نے ان کی بینائی واپس لوٹا دی تھی۔"],[1588,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو العباس نے ان کو احمد نے ان کو یونس نے ان کو ابن اسحق نے وہ کہتے ہیں مجھے حدیث بیان کی ہے کئی رجال نے آل عمار بن یاسر سے کہ سمیہ ام عمار کو بنو مغیرہ کے قبیلے نے سزا دی تھی۔ اسلام لانے پر وہ برابر انکار کرتی رہیں یہاں تک کہ انہوں نے اسے قتل کر دیا حضور صلی اللہ علیہ وسلم آل عمار کے پاس سے گزرے۔ وہ ان کو مقام ابطح پر سزا دے رہے تھے۔ مکہ کی پتھریلی گرم زمین پر حضور صلی اللہ علیہ وسلم فرماتے صبر کرو اے آل یاسر تمہارے وعدے کی جگہ جنت ہے۔ (1)","",{"k":"(1) غير واضح۔ كلمة غير واضحة۔ أخرجه المصنف من طريق الحاكم (۳۸۳/۳)۔"}],[1589,"ہمیں خبر دی محمد بن موسیٰ بن فضل نے ان کو عبد اللہ بن صفار نے ان کو احمد بن محمد برنی قاضی نے ان کو محمد بن کثیر عبدی نے ان کو حماد بن سلمہ نے حضرت ثابت سے انہوں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے یہ کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا میں اللہ کے راستے میں اتنا ڈرایا گیا ہوں جس قدر کوئی دوسرا نہیں ڈرایا گیا اور البتہ تحقیق میں اللہ کی راہ میں اتنی اذیت دیا گیا ہوں کہ جس قدر کوئی دوسرا اذیت نہیں دیا گیا۔ البتہ تحقیق مجھ پر اور بلال پر ایسا وقت بھی آیا ہے کہ ایک ایک مہینہ تک ہمارے پاس کوئی کھانے کی چیز نہیں ہوتی تھی جسے کوئی زندہ چیز کھا لے مگر ایسی چیز جسے بلال کی بغل چھپا لے۔ اس مفہوم میں احادیث بہت ہیں ان میں سے بعض کو ہم نے دلائل النبوہ میں ذکر کر دیا ہے اور جب بھی نبی کریم کی خدمت میں انہوں نے شکایت کی جو انہیں تکلیف ہوتی تھی شرمندہ ہی ہوا۔ (ایسے اس سے زیادہ خود حضور کو پہنچی ہوتی تھی۔) پھر انہوں نے حضور دعا کی درخواست کی اس تکلیف کو ان سے دور کرنے کے بارے میں۔ (1)","",{"k":"(1) أخرجه الترمذى (۲۴۶۲) عن عبد الله بن عبد الرحمن عن روح بن أسلم أبو حاتم البصرى عن حماد بن سلمة۔ به۔ وقال الترمذى حسن غريب۔"}],[1590,"§سیدنا خباب رضی اللہ عنہ کا حضور صلی اللہ علیہ وسلم سے شکوہ\nہمیں خبر دی ابو زکریا بن ابو الحق نے ان کو ابو عبد اللہ بن یعقوب نے ان کو محمد بن عبد الوہاب نے ان کو جعفر بن عون نے ان کو اسماعیل بن ابو خالد نے قیس بن ابو حازم سے انہوں نے خباب سے وہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں شکایت کی حضور صلی اللہ علیہ وسلم اپنی ایک چادر کے ساتھ تکیہ لگائے ہوئے تھے کعبہ کے سائے تلے ہم نے عرض کیا کہ کیا آپ ہمارے لئے اللہ سے دعا نہیں فرماتے کہا آپ اللہ تعالیٰ سے ہمارے لئے نصرت نہیں طلب کرتے۔ کہتے ہیں کہ حضور صلی اللہ علیہ وسلم یہ سن کر سیدھے ہو کر بیٹھ گئے آپ کا چہرہ غصے سے سرخ ہو چکا تھا فرمانے لگے اللہ کی قسم تم سے پہلے لوگوں پر ایسا وقت بھی آیا کہ زمین میں گڑھا کھود کر دفن کر کے اس کے سر کے اوپر آرا چلا دیا جاتا چیر کر دو ٹکڑے کر دیا جاتا مگر یہ عذاب اس کو اللہ تعالیٰ کے دین سے نہ پھیر سکتا کسی کا لوہے کی کنگھی سے گوشت اتار دیا جاتا صرف ہڈیاں رہ جاتیں یہ عذاب اس کو اللہ کے دین سے نہ پھیر سکتا اللہ تعالیٰ اس امر کو ضرور پورا کریں گے یہاں تک کہ ایک سوار تم میں سے صنعاء سے حضرموت تک چلے گا اسے صرف اللہ کا ڈر ہوگا یا بھیڑیے کا اس کی بکریوں پر اور کسی کا ڈر نہیں ہو گا لیکن تم ایسے لوگ ہو جو جلدی کرتے ہو۔ اس کو بخاری و مسلم نے صحیح میں دوسری جگہ سے اسماعیل سے نقل کیا ہے۔ (1)","",{"k":"(1) أخرجه البخارى (۳۱۵/۱۲، ۳۱۶ فتح) عن مسدد عن يحيى عن إسماعيل۔ به۔ والحديث غير موجود فى صحيح مسلم وانظر تحفة الاشراف۔"}],[1591,"§سیدنا صہیب کے زبانی اصحاب الاخدود کا واقعہ\nہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو العباس محمد بن یعقوب نے ان کو محمد بن الحق صنعانی نے ان کو عفان نے ان کو حماد بن سلمہ نے ان کو ثابت نے عبد الرحمن بن ابی لیلیٰ سے انہوں نے صہیب رضی اللہ تعالیٰ عنہ سے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تم سے پہلے لوگوں میں ایک بادشاہ تھا اس کے پاس ایک جادوگر تھا جب جادوگر بوڑھا ہو گیا تو اس نے کہا۔ میں بوڑھا ہو گیا ہوں میری موت قریب ہے مجھے ایک لڑکا دو تا کہ میں اسے جادو سکھلا دوں بادشاہ نے اسے ایک لڑکا فراہم کر دیا جادوگر اسے جادو سکھلاتا رہا بادشاہ اور جادوگر کے درمیان راستے میں ایک راہب رہتا تھا ایک دن وہ لڑکا اس راہب کے پاس چلا گیا اس کی باتیں سنی تو اسے اچھی لگی اور اس کی سرگوشی بھی اسے اچھی لگی وہ لڑکا جب ساحر کے پاس آیا تو اس نے اسے مارا کہ اتنی دیر کہاں رہا چنانچہ جب وہ گھر واپس آتا تو راہب کے پاس بیٹھ جاتا اور گھر میں دیر سے پہنچتا اور گھر والے اسے مارتے کہ دیر سے کیوں آئے۔ چنانچہ لڑکے نے دونوں طرف کی مار کی شکایت راہب سے کر دی راہب نے اسے سکھلایا کہ جب جادوگر تجھے مارنے کا ارادہ کرے تو تم کہنا کہ گھر والوں نے دیر کرا دی تھی۔ اور جب تیرے گھر والے تجھے مارنے لگیں تو تم یہ کہہ دینا کہ جادوگر نے دیر سے چھٹی دی تھی۔ لہذا وہ لڑکا یہی کہتا رہا کہ اچانک اس نے ایک دن کیا دیکھا کہ کوئی ایک بھیانک شکل کا جانور بہت بڑا ہے راستے میں آیا ہوا ہے اس نے لوگوں کا راستہ روک رکھا ہے لوگوں کو گذرنے نہیں دے رہا چنانچہ لڑکے نے سوچا آج میں راہب کا معاملہ دیکھتا ہوں کہ وہ اللہ کو پسند ہے یا جادوگر کا معاملہ چنانچہ اس نے پتھر اٹھایا اور دعا کرنے لگا اے اللہ اگر راہب کا معاملہ تیرے نزدیک بہتر ہے اور پسند ہے تو اس پتھر سے اس جانور کو مار دے یہاں تک کہ لوگ گذرنے لگ جائیں یہ کہہ کر اسے پتھر مارا اور اس جانور کو مار دیا لوگ گذر گئے اس نے اس بات کی خبر راہب کو کر دی اس نے کہا اے بیٹے تم مجھ سے افضل ہو اور تم عنقریب آزمائے جاؤ گے اگر تم آزمائش میں پڑ جاؤ تو میرے بارے میں کسی کو نہ بتانا اب تو وہ لڑکا مادر زاد اندھوں کو بینا کرنے لگا کوڑھیوں کو تندرست کرنے لگا اور تمام بیماروں کو صحت یاب کرنے لگا۔ اسی دوران بادشاہ کا وزیر اندھا ہو گیا اس نے اس لڑکے کے بارے میں سنا تو بڑے بڑے ہدایا لے کر اس لڑکے کے پاس آیا اور کہنے لگا مجھے آپ شفا دے دیں یہاں جو کچھ لایا ہوں وہ تجھے دے دوں گا اس نے کہا کہ میں کسی کو شفا نہیں دیتا شفا تو اللہ دیتا ہے اگر آپ چاہیں تو میں اللہ سے دعا کرتا ہوں اللہ تجھے بھی شفا دے گا۔ چنانچہ اس نے اس کے لئے دعا کی اور اسے شفا ہو گئی اس کے بعد وزیر بادشاہ کے پاس آیا اور اپنی جگہ پر بیٹھا بادشاہ نے پوچھا کہ اے فلاں تیری بینائی کس نے لوٹا دی ہے وزیر نے کہا کہ میرے رب نے اس نے کہا کہ میں نے لوٹا دی ہے؟ وزیر نے کہا کہ نہیں۔ بلکہ میرا اور تیرا رب اللہ ہے۔ بادشاہ نے پوچھا کیا میرے سوا بھی تمہارا کوئی رب ہے اس نے کہا کہ ہاں تیرا اور میرا رب اللہ ہے بادشاہ نے اسے پکڑ کر سزا دی یہاں تک کہ اس نے اس لڑکے کے بارے میں بتا دیا بادشاہ نے اسے طلب کر لیا اور اسے بلا کر کہا۔ اے بیٹے تیرے جادو بلا کی اطلاع مجھے مل چکی ہے کہ تو مادر زاد اندھوں کو بینا کرتا ہے کوڑھ والوں کو ٹھیک کرتا ہے وغیرہ وغیرہ اس نے کہا میں تو کسی کو شفا نہیں دے سکتا اللہ شفا دیتا ہے اس نے کہا کہ کون اللہ ہے؟ اس نے کہا کہ میرا رب۔ اس نے پوچھا کہ میرے سوا تیرا اور بھی کوئی رب ہے؟ لڑکے نے کہا میرا اور تیرا رب اللہ ہے۔ چنانچہ بادشاہ نے اسے بھی سزا میں ڈال دیا اس کو اتنی سزا دی کہ اس نے راہب کے بارے میں بتلا دیا چنانچہ راہب کو گرفتار کر کے لے آئے تو اسے کہا کہ تو اپنے دین سے پھر جا اس نے انکار کر دیا۔ چنانچہ اس کے سر کی چوٹی پر آرا رکھا اور اسے دو ٹکڑوں میں چیر دیا اب لڑکے سے کہا کہ تو اپنے دین کو چھوڑ دے اس نے بھی انکار کر دیا بادشاہ نے حکم دیا کہ ایک جماعت اس کو لے کر پہاڑ پر چھوڑنے جائے جب تم چوٹی پر پہنچ جاؤ تو اگر یہ اپنا دین چھوڑ دے تو ٹھیک ورنہ اس کو وہیں سے پھینک کر مار دیا جائے وہ لوگ اسے لے کر اوپر گئے جب اوپر چڑھ گئے تو اس نے دعا کی اے اللہ تو میری طرف سے ان کو کافی ہو جا جیسے تو چاہے لہذا پہاڑ ان کے ساتھ کانپنے لگا چنانچہ وہ سارے گر کر ہلاک ہو گئے لڑکا چلتا ہوا نیچے آ گیا اور بادشاہ کے دربار میں داخل ہوا بادشاہ نے پوچھا کہ تیرے ساتھی کہاں ہیں؟ اس نے جواب دیا کہ اللہ نے میری طرف سے ان کو کفایت کی ہے (اور پوری بات بتا دی بادشاہ نے حکم دیا کہ اس لڑکے کو کشتی بانوں کی جماعت کے حوالے کیا جائے جب وہ اس کو لے کر بیچ سمندر میں موجوں میں پہنچیں تو اس کو روک کر معلوم کرو اگر اپنے دین سے رجوع کر لے تو ٹھیک ورنہ اس کو غرق کر دو اور اسے سمندر کی موجوں کے سپرد کر دو جب اسے لے کر گئے تو لڑکے نے اللہ سے دعا کی یا اللہ تو ان کو میری طرف سے کافی ہو جا جیسے تو چاہے چنانچہ وہ غرق کرنے والے سب کے سب غرق ہو گئے اور لڑکا چلتا ہوا بادشاہ کے دربار میں داخل ہوا بادشاہ نے پوچھا تیرے ساتھیوں نے کیا کیا؟ اس نے جواب دیا کہ میری طرف سے اللہ نے ان کو کفایت کی ہے اس کے بعد لڑکے نے بادشاہ سے کہا کہ تو مجھے قتل نہیں کر سکتا یہاں تک کہ میں جو کچھ تجھے کہوں وہ کر لے اگر تم نے وہی کچھ کیا جو میں کہوں گا تو تم مجھے قتل کر سکو گے ورنہ نہیں تم ہرگز مجھے قتل نہیں کر سکتے ہو۔ بادشاہ نے پوچھا وہ کیا ہے؟ اس نے کہا کہ ایک بڑے میدان میں تم سب لوگوں کو جمع کر دو اس کے بعد سب کے سامنے مجھے کھجور کے تنے پر پھانسی دو اور اس کے بعد میری ترکش سے تم تیر نکال کر کہو بسم اللہ رب الغلام اور تیر چلا دو چنانچہ بادشاہ نے ایسے ہی کیا۔ لڑکے نے کہا تم جب ایسے کرو گے تو تم مجھے قتل کر سکو گے وگرنہ تم مجھے قتل ہرگز نہیں کر سکو گے۔ چنانچہ اس نے تیر اس کی کمان پر رکھا پھر مارتے ہوئے یہی کہا بسم اللہ رب الغلام میں لڑکے کے رب کے نام کے ساتھ تیر چلاتا ہوں چنانچہ تیر لڑکے کی کنپٹی پر لگا اور لڑکے نے اپنا ہاتھ تیر کی جگہ رکھا اور مر گیا لہذا سب لوگوں نے یہ منظر دیکھ کر کہا امنا برب الغلام ہم لڑکے کے رب کے ساتھ ایمان لے آئے ہیں۔ لہذا بادشاہ سے کہا گیا دیکھا آپ نے جس بات سے آپ ڈرتے تھے وہی ہو کر رہا کہ سارے لوگ ایمان لے آئے ہیں، بادشاہ نے حکم دیا کہ گلیوں کے سروں پر کھائیاں کھودی گئیں اور ان میں آگ سلگائی گئی اس کے بعد لوگوں سے کہا گیا کہ اگر ایمان سے پھر جاؤ تو ٹھیک ہے ورنہ اس آگ میں چھوڑ دیئے جاؤ گے اور کارندوں کو حکم دیا کہ جو شخص دین چھوڑ دے اسے بچا لو باقی سب کو پکڑ کر آگ میں جھونک دو۔ لہذا وہ کسی کو بچانے کسی کو آگ میں ڈالنے لگے ایک عورت لائی گئی جو اپنے شیر خوار کو دودھ پلا رہی تھی اور ڈر رہی تھی کہ وہ بچے سمیت آگ میں ڈال دی جائے گی چنانچہ اس کے بچے نے اسے کہا اے امی تو صبر کر بے شک تو حق پر ہے۔ مسلم نے اس کو صحیح میں روایت کیا ہے ہداب بن خالد سے اس نے حماد سے اور دونوں جگہ کہا ہے لڑکا چلتا ہوا آیا حتیٰ کہ بادشاہ پر داخل ہوا اور کہنے لگا کشتی ان لوگوں سمیت الٹ گئی ہے اور وہ سب غرق ہو گئے ہیں۔ اور اس کو روایت کیا ہے معمر نے ثابت سے اپنی اسناد کے ساتھ اور اس نے آخر میں کہا ہے۔ بس ڈال دیا اس نے ان لوگوں کو کھائیوں میں۔ چنانچہ اللہ تعالیٰ فرمایا۔\n﴿قتل اصحب الاخدود النار ذات الوقود﴾\n’’ہلاک ہو گئے آگ کی کھائیوں والے وہ آگ تھی شعلے مارنے والی۔‘‘\nنبی کریم صلی اللہ علیہ وسلم اس آیت کو عزیز الحمید تک پڑھتے گئے فرمایا۔ بے شک وہ لڑکا دفن کر دیا گیا۔ ذکر کیا گیا ہے کہ وہ لڑکا سیدنا عمر کے زمانہ حکومت میں نکلا حالانکہ اس کی انگلی بدستور اس کی کنپٹی پر رکھی ہوئی تھی جیسے اس نے انگلی رکھی تھی جب قتل کیا گیا تھا۔ (1)","",{"k":"(1) أخرجه مسلم (۲۲۹۹/۴، ۲۳۰۱) عن هداب بن خالد عن حماد۔ به۔"}],[1592,"ہمیں اس کی خبر دی ہے حافظ نے ان کو صغانی نے ان کو اسحاق بن ابراہیم نے ان کو عبد الرزاق نے ان کو معمر نے پھر اس نے اس روایت کو ذکر کیا ہے مذکورہ روایت کے مفہوم میں کچھ کم کچھ زیادہ اور کہا ہے کہ کہا عبد الرزاق نے وہ کھائیاں نجران میں ہیں۔"],[1593,"§فرعون کی بیٹی کی خادمہ کا بیان\nہمیں خبر دی ابو عبد اللہ حافظ نے ان کو محمد بن اصلح بن بانی نے ان کو حسین بن فضل بجلی نے ان کو عفان بن مسلم نے ان کو حماد بن سلمہ نے ان کو عطاء بن السائب نے ان کو سعید بن جبیر نے ان کو ابن عباس رضی اللہ تعالیٰ عنہ نے کہتے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جب مجھے سیر کرائی گئی میری ساتھ ایک پاکیزہ خوشبو گذری میں نے پوچھا یہ کیسی خوشبو ہے؟ فرشتوں نے کہا یہ خوشبو ہے فرعون کی بیٹی کی کنگھی کرنے والی کی ہے اور اس کی اولاد کی ہے وہ اسی کے ساتھ کنگھی کر رہی تھی ایک بار کنگھی اس کے ہاتھ سے گر گئی تو اس نے کہا تھا بسم اللہ۔ چنانچہ فرعون کی بیٹی نے سنا تو پوچھا اللہ سے تیری مراد کون ہے؟ کیا میرا باپ مراد ہے؟ اس نے جواب دیا نہیں بلکہ وہ جو میرا رب ہے اور تیرا بھی رب ہے اور تیرے والد کا بھی رب ہے۔ فرعون کی بیٹی نے پوچھا کہ کیا میں اس بات کی خبر اپنے والد کو دوں؟ اس نوکرانی نے جواب دیا کہ بالکل آپ اپنے والد کو بتا دیں چنانچہ اس نے یہ بات فرعون کو بتا دی۔ لہذا فرعون نے اس خاتون کو اس کے بچوں سمیت بلا لیا اور کہا کہ کیا میرے سوا تیرا اور بھی کوئی رب ہے؟ نوکرانی نے جواب دیا جی ہاں میرا اور تیرا بھی رب اللہ ہے میرا خیال ہے کہ آپ نے فرمایا اس کے بعد فرعون نے حکم دیا تھا تانبے کا ایک کڑھا گرم کیا گیا پھر اس کے بارے میں حکم دیا کہ اس کو گرم کڑھے میں ڈال دو۔ اس خاتون نے کہا میری ایک ضرورت ہے آپ کی طرف فرعون نے پوچھا کہ وہ کیا ہے؟ وہ یہ ہے کہ میری اور میرے بچوں کی ہڈیاں اکٹھے دفن کرا دینا۔ فرعون نے حامی بھر لی کہ ٹھیک ہے ہم یہ کریں گے اس لئے کہ تیرا ہمارے اوپر حق ہے۔ چنانچہ اس کی اولاد لائی گئی ایک ایک کر کے ماں کے سامنے سب کو کڑھے میں گرا دیا گیا۔ جب آخری بچہ رہ گیا تو وہ چونکہ شیر خوار تھا وہ بولا اے میری امی تم صبر کرو بے شک تم حق پر ہو اس کے بعد وہ اپنے بچے سمیت ڈال دی گئی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا چار لوگوں نے صغر سنی میں کلام کیا تھا یہ بچہ اور یوسف علیہ السلام کے حق میں گواہی دینے والا بچہ۔ اور صاحب جریج اور عیسیٰ بن مریم علیہ السلام۔ (1)","",{"k":"(1) فى الأصل أبو عبد الله الحافظ الصغانى والصحيح أبو عبد الله الحافظ ثنا الصغانى وهو أبو عبد الله الصغانى۔ أخرجه الحاكم (۳۹۶/۲) بنفس الإسناد وصححه ووافقه الذهبى۔"}],[1594,"§امرأۃ فرعون کا قصہ اور اس کو دی گئی سزائیں\nہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو عبد اللہ محمد بن یعقوب شیبانی اور ابراہیم بن عبد اللہ نے ان کو یزید بن ہارون۔ ح۔ اور ہمیں خبر دی ہے ابو بکر حیری نے ان کو حاجب بن احمد نے ان کو محمد بن حماد نے ان کو یزید بن ہارون نے ان کو سلیمان تیمی نے ان کو ابو عثمان نے ان کو سلمان نے وہ کہتے ہیں کہ فرعون کی عورت (چونکہ مسلمان تھی) انہیں دھوپ میں سزا دی جاتی تھی جب فرعونی ان سے ہٹ جاتے فرشتے اس پر سایہ کرتے تھے اپنے پروں سے اور انہیں جنت میں ان کا گھر دکھایا جاتا تھا۔ دونوں کے الفاظ برابر ہیں۔ (1)","",{"k":"(1) أخرجه الحاكم (۳۹۶/۲) بنفس الإسناد وصححه ووافقه الذهبى۔"}],[1595,"ہمیں خبر دی ہے ابو عبد اللہ نے ان کو ابو عبد اللہ صغانی نے ان کو اسحاق بن ابراہیم نے ان کو عبد الرزاق نے ان کو معمر نے ان کو ثابت نے ان کو ابو رافع نے انہوں نے کہا کہ فرعون نے اپنی بیوی کو چار میخیں ٹھونکوا دیں تھیں دونوں ہاتھوں اور دونوں پیروں میں اس کے بعد اس کے پیٹ پر بہت بڑا بھاری پتھر رکھ دیا حتیٰ کہ وہ مر گئی۔ (1)","",{"k":"(1) عزاه السيوطى فى الدر المنثور إلى عبد بن حميد۔"}],[1596,"§عبد اللہ بن حذافہ رضی اللہ عنہ کا واقعہ\nہمیں خبر دی ہے ابو الحسین محمد بن فضل قطان نے ان کو ابو سہل بن زیاد قطان نے ان کو سعید بن عثمان احوازی نے ان کو عبد اللہ بن معاویہ جمحی نے۔ اور ہمیں خبر دی ہے ابو منصور عمر بن عبد العزیز بن قتادہ نے ان کو ابو محمد یحییٰ بن منصور قاضی نے ان کو ابو الفضل احمد بن سلمہ نے ان کو عبد اللہ بن معاویہ جمحی نے ان کو عبد العزیز بن محمد قسملی نے ان کو خضار بن عمرو نے ان کو ابو رافع نے انہوں نے کہا کہ سیدنا عمر رضی اللہ تعالیٰ عنہ نے روم کی طرف ایک لشکر روانہ کیا ان میں ایک آدمی تھے جنہیں عبد اللہ بن حذافہ کہا جاتا تھا اصحاب رسول میں سے تھے رومیوں نے انہیں قید کر لیا اور اسے اپنے بادشاہ کے پاس لے گئے اور جا کر کہا کہ یہ شخص محمد صلی اللہ علیہ وسلم کے اصحاب میں سے ہے اس سرکش نے اسے کہا کیا آپ کو دلچسپی ہے کہ آپ عیسائی بن جائیں۔ چنانچہ میں آپ کو اپنی حکومت میں اور اپنے ملک اور سلطنت میں شریک کروں گا؟ سیدنا عبد اللہ بن حذافہ نے اس سے کہا اگر آپ مجھے وہ سب کچھ دے دیں جس کے آپ مالک ہیں اور وہ سب کچھ بھی عرب جس کے مالک ہیں۔ اور قطان کی ایک روایت میں ہے کہ ساری مملکت عرب اس شرط پر کہ میں محمد صلی اللہ علیہ وسلم کا دین چھوڑ دوں وہ بھی صرف آنکھ جھپکنے کی دیر تو میں یہ کرنے کے لئے تیار نہیں ہوں۔ اور بادشاہ نے کہا کہ پھر میں تجھے قتل کرا دیتا ہوں انہوں نے جواب دیا کہ تم جانو اور تمہارا کام تمہیں اس کا اختیار ہے۔ فرماتے ہیں چنانچہ اس نے حکم دیا انہیں پھانسی پر لٹکایا گیا اور تیراندازوں سے کہا گیا کہ تیروں سے اس کے ہاتھوں اور پیروں کو نشانہ بنایا جائے، اور وہ برابر اس پر اس کے عیسائی بننے کی دعوت پیش کرتا رہا اور سیدنا عبد اللہ بن حذافہ انکار کرتا رہا اس کے بعد اس نے کہا کہ اس کو صلیب سے اتار لو اس کے بعد ایک ہنڈیا یا دیگ میں پانی کھولایا گیا اس کے بعد دو مسلمان قیدی بلائے ان میں سے ایک اس کھولتے ہوئے پانی میں ڈال دیا گیا اور بادشاہ برابر اس کے عیسائیت کی دعوت پیش کرتا رہا اور وہ انکار کرتے رہے اس کے بعد حکم دیا کہ اس کو بھی کھولتے ہوئے پانی میں ڈال دو جب انہیں لے جایا جانے لگا تو وہ رونے لگے، چنانچہ بادشاہ کو اطلاع کی گئی کہ وہ رو رہا ہے اس نے سوچا کہ شاید اب یہ شخص اسلام سے رجوع کرنا چاہتا ہے بادشاہ نے حکم دیا کہ اس کو واپس لاؤ پھر اس نے ان کو عیسائیت پیش کی اس نے انکار کر دیا اس نے کہا پھر تم کیوں روئے تھے؟ اس نے کہا کہ مجھے اس خیال نے رلایا کہ میں نے دل میں یہ سوچا تھا کہ آپ اسی وقت مجھے گرم پانی میں ڈال دیں گے میں ختم ہو جاؤں گا مگر میری یہ خواہش تھی کہ میرے ہر ہر بال کی جگہ میری روح ہوتی لہذا امیرا ہر روح کے ساتھ جس کے ساتھ میں بار بار اللہ کی راہ میں قربان ہو کر اللہ سے جا کر ملتا چنانچہ اس سرکش بادشاہ نے ان سے کہا اگر تم مجھے میرے سر پر بوسہ دو تو میں تجھے چھوڑ دوں گا؟ سیدنا عبد اللہ بن حذیفہ نے کہا ایک شرط کے ساتھ دوں گا وہ یہ کہ تم تمام مسلمان قیدیوں کو چھوڑ دو اس نے کہا ٹھیک ہے میں تمام مسلمان قیدی چھوڑ دوں گا سیدنا عبد اللہ قریب ہوئے اور اس کے سر کو بوسہ دیا اور اس نے تمام قیدی سیدنا عبد اللہ کے حوالے کر دیے وہ تمام قیدیوں کو لے کر سیدنا عمر رضی اللہ عنہ کی خدمت میں آئے سیدنا عمر رضی اللہ عنہ کو ساری خبر سنائی چنانچہ سیدنا عمر رضی اللہ عنہ نے فرمایا۔ ہر مسلمان پر حق بنتا ہے کہ ہر شخص سیدنا عبد اللہ کے سر کو بوسہ دے اور میں خود سب سے پہلے کرتا ہوں سیدنا عمر رضی اللہ عنہ اٹھے اور عبد اللہ بن حذافہ کے سر کو بوسہ دیا۔ احمد بن سلمہ کہتے ہیں کہ مجھ سے اس حدیث کے بارے میں محمد بن مسلم اور محمد بن ادریس نے پوچھا اور دونوں نے کہا کہ ہم نے یہ حدیث کبھی نہیں سنی۔ (1)","",{"k":"(1) انظر حياة الصحابه (۳۰۲/۱) ط/ دار القلم۔"}],[1597,"ہمیں خبر دی ہے ابو طاہر فقیہ نے ان کو ابو الفضل عبدوس بن حسین بن منصور نیساپوری نے ان کو ابو حاتم رازی انصاری نے ان کو حمید طویل نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا ایک آدمی آتا تھا آ کر ان سے حضور صلی اللہ علیہ وسلم کے بارے میں پوچھتا تھا کسی شئی کے بارے میں دنیا کے امر سے ابھی شام نہیں ہوئی کہ اسلام اس کو دنیا سے محبوب ترین یا عزیز ترین ہو گیا۔"],[1598,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے اور ابو نصر بن قتادہ دونوں نے کہا ان کو خبر دی ہے ابو محمد یحییٰ بن منصور قاضی نے ان کو علی بن نضر نے ان کو عفان نے ان کو حماد بن سلمہ نے ان کو ثابت نے ان کو سیدنا انس رضی اللہ تعالیٰ عنہ نے کہ ایک آدمی نے نبی کریم صلی اللہ علیہ وسلم سے سوال کیا حضور نے اس کو بکریاں عطا فرمائیں جو دو پہاڑوں کے درمیان تھیں لہذا وہ انہیں لے کر اپنی قوم کے پاس آیا اور کہنے لگا اے قوم اسلام لے آؤ اللہ کی قسم محمد صلی اللہ علیہ وسلم اتنا بڑا انعام دیتے ہیں کہ انسان کو فاقہ کا خوف نہیں رہتا اور بیشک ایک آدمی حضور صلی اللہ علیہ وسلم کے پاس آتا ہے۔ ف دنیا کا ارادہ کرتا ہے بس وہ واپس اس حالت میں لوٹتا ہے کہ اس کو اس کا دین زیادہ محبوب ہو جاتا ہے دنیا و مافیہا سے۔ اس کو مسلم نے نقل کیا ہے یزید بن ہارون کی حدیث سے حضرت حماد سے۔ (1)","",{"k":"(1) أخرجه مسلم (۱۸۰۶/۴) عن أبى بكر بن أبى شيبة عن يزيد بن هارون عن حماد۔ به۔"}],[1599,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو العباس محمد بن یعقوب نے ان کو یحییٰ بن ابو طالب نے ان کو عبد الوہاب یعنی ابن عطاء نے ان کو ابو سعید نے وہ ابن عروبہ ہیں اور ہشام بن سبز نے وہ دستوائی ہیں ان کو قتادہ نے ان کو یونس بن جبیر نے ہم ایک مجاہد سے ملے ہم نے کہا ہمیں وصیت کیجئے اس نے وصیت کرتے ہوئے کہا، میں تمہیں قرآن کے بارے میں وصیت کرتا ہوں۔ قرآن اندھیری رات کا نور اور روشنی ہے۔ دن کی ہدایت اور نمونہ ہے۔ قرآن کے ساتھ عمل کرو مشقت کے ساتھ ہو یا فاقہ کے ساتھ اگر کوئی آزمائش آں پڑے تو اسی کو اپنے آگے کر دو اور اگر آزمائش تجھ سے گذر جائے مل جائے تو اپنے نفس کو اپنے دین کے آگے کر دو بے شک آزاد وہ ہے جس کا دین آزاد ہوا اور لٹا ہوا وہ ہے جس کا دین چھن جائے، اس لئے کہ جنت مل جانے کے بعد کوئی فقر باقی نہیں ہوگا اور جہنم میں چلے جانے کے بعد غنی ہونا کام نہیں دے گا اس لئے کہ جہنم کا قیدی چھوٹتا نہیں ہے نہ ہی اس کا فقیر کبھی غنی ہو سکے گا۔"],[1600,"ہمیں خبر دی ہے ابو الحسین فضل بن قطان نے ان کو عبد بن جعفر نے ان کو یعقوب بن سفیان نے ان کو عقبہ بن مکرم نے ان کو سعید بن عامر نے ان کو ربی بن کعب نے کہنے لگے میں چاہتا ہوں کہ میں فتنہ اور آزمائش کے طرف نکلوں انہوں نے فرمایا میں نے حسن سے کہا تھا کہ آپ مجھے کوئی وصیت فرمائے فرمایا کہ آپ اللہ کے حکم کی اطاعت کیجئے آپ جہاں کہیں بھی ہوں اللہ تجھے عزت دے گا۔ اس کو جعفر بن سلیمان ابن سے روایت کیا ہے۔"],[1601,"ہمیں خبر دی ہے ابو علی رودباری نے ان کو اسماعیل بن محمد صفار نے ان کو محمد بن علی وراق نے ان کو ابو نعمان نے ان کو حماد بن زید نے ایوب سے انہوں نے حسن سے انہوں نے کہا بیشک اللہ تعالیٰ اگر چاہتے تو اس امر کو بندوں کے سپرد کرتے یا کہا تھا لوگوں کے سپرد کرتے پس انہوں نے فرمایا کہ جو شخص میرے لئے کوشش کرے گا میں اسے اس کا بدلہ اور جزا دوں گا لیکن امر فرمایا کسی امر کے ساتھ اور منع فرمایا کسی دوسرے امر سے پھر فرمایا کوشش کرو ان امور میں جن میں میں نے تمہیں حکم دیا۔"],[1602,"§مراقبہ کے تین اعمال\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو حسن بن محمد اسحاق نے انہوں نے سنا ابو عثمان خیاط سے وہ کہتے ہیں کہ انہوں نے سنا ذوالنون مصری سے وہ فرماتے تھے۔ تین اعمال اعمال مراقبہ میں سے ہیں اللہ نے جو کچھ اتارا ہے اس کا ایثار۔ اللہ نے جس کو عظمت دی ہے اس کی تعظیم، اللہ نے جس کو ذلت دی کہ اس کو ذلیل رکھنا۔ اور فرمایا کہ تین چیزیں اللہ سے عزت حاصل کرنے کی نشانیاں ہیں۔ حکمت و دانائی کو کثرت سے ڈھونڈھنا۔ کنبہ قبیلے کی نہیں۔ اللہ سے مدد مانگنا مخلوق سے نہیں۔ اہل دین کے آگے اظہار عجز و ذلت اختیار کرنا اہل دنیا کے لئے نہیں۔"],[1603,"§حضرت یعقوب علیہ السلام اور حضرت یوسف علیہ السلام کا واقعہ\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے اور ابو نصر محمد بن علی اور ابو عبد الرحمن سلمی نے انہوں نے کہا کہ ہمیں حدیث بیان کی ہے ابو العباس محمد بن یعقوب نے ان کو عبد اللہ بن ہلال بن فرات نے ان کو احمد بن ابو الحواری نے ان کو ابو جعفر بجلی نے ان کو قبیصہ نے سفیان سے کہتے ہیں کہ جب یوسف کی بشارت دینے والا یعقوب علیہ السلام کے پاس آیا تو انہوں نے پوچھا کہ یوسف کو کسی دین پر چھوڑ کر آئے ہو اس نے کہا کہ اسلام پر یعقوب علیہ السلام نے کہا اب نعمت پوری ہو گئی ہے۔ (1)","",{"k":"(1) أخرجه أبو نعيم فى الحلية (۷/۷) من طريق خلق بن تميم عن سفيان۔ به۔"}],[1604,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو جعفر محمد بن احمد رازی نے ان کو علی بن حسین بن شہریار رازی نے ان کو سلیمان بن منصور بن عمار نے ان کو محمد بن عبد الوہاب نے ان کو سفیان ثوری نے انہوں نے کہا کہ جب (طویل جدائی کے بعد) حضرت یعقوب اور حضرت یوسف علیہ السلام باہم ملے تو دونوں نے باہم معانقہ کیا اور یعقوب علیہ السلام رو پڑے۔ یوسف علیہ السلام نے پوچھا ابا جان آپ میرے اوپر روتے رہے یہاں تک کہ آپ کی بینائی چلی گئی کیا آپ یہ نہیں جانتے تھے کہ قیامت میں ہم ضرور اکٹھے ہوں گے یعقوب نے فرمایا بالکل جانتا تھا مگر میں ڈرتا تھا کہ کہیں تجھ سے تیرا دین نہ چھین لیا جائے لہذا میرے اور تیرے درمیان دین کی جدائی مائل نہ ہو جائے۔ (1)","",{"k":"(1) فى الأصل (عبد) وبعده بياض۔"}],[1605,"اور سلیم نے کہا مجھے خبر پہنچی ہے کہ پہلا شخص جس نے بیت کہا یعنی شعر وہ یعقوب علیہ السلام کا شعر تھا جب لوگوں نے ان کو خبر دی۔\nفصبر جميل للذى جئتم به...... وحسبى الهى من المهمات كافيا۔\nمیں صبر جمیل کروں گا اس کے لئے جسے تم لے کر گئے ہو اور مجھے میرا معبود تمام مشکلات میں کافی ہے۔"],[1606,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو جعفر محمد بن عبد اللہ بغدادی نے ان کو علی بن مبارک نے صغانی ان کو محمد بن اسماعیل صغانی نے ان کو سفیان نے کہتے ہیں کہ ابو حازم نے اپنے ساتھیوں سے کہا اور ان کے لئے حلف بھی اٹھائی البتہ تحقیق میں تم سے راضی ہوں بایں وجہ کہ دین پر باقی ہے جیسے اپنے جوتوں پر باقی ہے (یعنی جس طرح دائیں بائیں جوتے سب کے وہی قائم ہیں کسی کو چھوٹا بڑا نہیں کیا ایسے دین پر قائم ہیں کوئی تبدیلی نہیں ہوئی۔)"],[1607,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے کہ مجھے خبر دی ہے جعفر بن محمد بن کثیر نے کہتے کہ میں نے حضرت جنید بغدادی سے سنا وہ کہتے تھے۔ لازم پکڑ اپنے دین کو یا اپنے دین کی حفاظت کر اس سے زیادہ سخت جتنی کہ تو اپنی آنکھ کی حفاظت کرتا ہے۔"],[1608,"§حضرت ابراہیم بن ادھم کا خط\nہمیں خبر دی ابو عبد الرحمن نے وہ کہتے ہیں کہ میں نے سنا احمد بن علی بن حسین مقری سے کہتے تھے کہ میں نے سنا محمد بن غالب تمتام سے وہ کہتے تھے کہ حضرت ابراہیم بن ادھم نے حضرت سفیان ثوری کی طرف لکھا۔ جو شخص پہچان لے جو کچھ طلب کرتا ہے اس پر آسان ہو جاتا ہے جو کچھ خرچ کرتا ہے۔ جو شخص اپنی نظر کو آزاد چھوڑ دیتا ہے اس کا افسوس طویل ہو جاتا ہے اور جو شخص اپنی آرزو کو آزاد چھوڑتا ہے اس کا عمل برا ہو جاتا ہے اور جو شخص زبان کو آزاد چھوڑتا ہے اپنے نفس کو خود قتل کرتا ہے (یعنی ہلاک کرتا ہے)۔"],[1609,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو علی بن محمد مروزی نے ان کو ابو علی حسن بن محمد زاہد نے ان کو احمد بن یونس بغدادی نے وہ کہتے ہیں کہ میں نے سنا سری بن مفلس سے وہ کہتے تھے کہ میں سنا ایک ایسا کلمہ جس کے ساتھ میں پچاس سال سے نفع اندوز ہو رہا ہوں میں مکہ میں طواف کر رہا تھا اچانک دیکھا تو ایک آدمی میزاب رحمت تلے بیٹھا تھا اس کے ارد گرد ایک جماعت تھی میں نے سنا وہ یہ ان سے کہہ رہا تھا۔ اے لوگو جو شخص جان لیتا ہے کہ کیا چیز اس کو خوشی اور پسند ہے جو کچھ خرچ کرتا ہے اس پر آسان ہوتا ہے۔"],[1610,"میں نے سنا ابو عبد الرحمن سلمی سے کہتے تھے کہ میں نے سنا یوسف بن عمر زاہد سے کہتے تھے کہ میں نے سنا محمد بن حسین اجری سے کہتے تھے کہ میں نے سنا عبد اللہ بن محمد عطشی سے انہوں نے سنا معمرہ سے وہ کہتے تھے جو شخص عمل کا مٹھاس چکھ لیتا ہے وہ اسے صبر دے دیتا ہے، راستوں کی کڑواہٹ کو گھونٹ گھونٹ کر کے پی لینے پر جو شخص کہ اس کا عبرت حاصل کرنا طویل ہو جائے اس کا ذوق لذیذ ہو جاتا ہے وہ نفرت کرتا ہے ان سے جو اسے مشغول کر دیں۔"],[1611,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو العباس محمد بن یعقوب نے ان کو محمد بن اسحاق صغانی نے ان کو عفان نے ان کو سلام بن مسکین نے ان کو عمران بن عبد اللہ وہ کہتے ہیں کہ میں نے سعید بن مسیب کے نفس کو دیکھا کہ ان پر اللہ کے لئے تکلیف سہنا مکھی بیٹھنے سے بھی زیادہ آسان تھا۔ (1)","",{"k":"(1) غير واضح فى الأصل۔"}],[1612,"ہمیں خبر دی ابو عبد اللہ نے ان کو ابو عبد اللہ محمد بن عبد اللہ اصفہانی نے زاہد نے ان کو اسماعیل بن اسحاق قاضی نے ان کو سلیمان بن حرب نے ان کو حماد بن زید نے ان کو یحییٰ بن سعید نے وہ کہتے ہیں کہ حضرت سعید بن مسیب کثرت کے یہ دعا کرتے تھے۔ اللهم سلم اللهم سلم اے اللہ بچا اللہ تو بچا۔"],[1613,"اور ہمیں خبر دی ہے ابو عبد اللہ حسین بن حسن غضائری نے اور ان کو جعفر بن محمد بن نصیر نے ان کو احمد بن محمد بن مسروق نے ان کو عمر بن شیبہ نے ان کو سعید بن عامر نے ان کو حزم بن ابو حزم نے قصعی نے کہتے ہیں کہ میمون بن سیاہ نے کہا اپنی دنیا کو اپنے دین پر ترجیح نہ دے جو شخص دنیا کو دین پر فوقیت دیتا ہے ندامت اس کی طرف لپکتی ہے۔"],[1614,"اور ہمیں خبر دی ہے ابو عبد اللہ غضائری نے ان کو احمد بن سلمان انجاد نے ان کو محمد بن بیثم نے وہ کہتے ہیں کہ میں نے سنا قعنبی سے وہ کہتے تھے کہ حضرت مالک بن انس رضی اللہ تعالیٰ عنہ نے فرمایا تھا۔ ایک آدمی سے اے فلانے کیا تو دل لگی نہیں کرتا فرمایا کہ (ہماری دل لگی اور دلچسپی تو دین ہے۔) آپ بھی اپنے دین کے ساتھ اپنا دل بہلائیے اور دل خوش کیجئے۔ (1)","",{"k":"(1) كلمة غير واضحة وهذه الكلمة اسم بلد۔"}],[1615,"§ایمان کا سترھواں شعبہ\n§علم کی طلب\nجب مطلق علم کا ذکر ہو تو مراد علم دین ہوتا ہے اور اس کے کئی اقسام ہیں۔\nاول: بعض اس میں سے اصل کا علم ہے وہ ہے باری تعالیٰ کی معرفت اس کے بارے میں پہلے بات ہو چکی ہے۔ دوم بعض اس میں سے۔ اس چیز کی معرفت جو کچھ اللہ تعالیٰ کی طرف سے آیا ہے، چنانچہ علم نبوۃ بھی اسی میں داخل ہے اور وہ علم بھی جس کے ذریعے نبی کریم صلی اللہ علیہ وسلم دیگر تمام انبیاء سے ممتاز ہوتے ہیں۔ اور اللہ تعالیٰ کے احکام کا علم اور ان کے فیصلوں کا علم۔\nسوم:...... بعض اس میں سے۔ اس چیز کی معرفت جس میں احکام کا علم طلب کیا جاتا ہے، اور وہ کتاب و سنت ہے اس کے نصوص اور اس کے معانی، اور نصوص کے مراتب کی تمیز، اور ناسخ اور منسوخ کا علم اور معانی کے ادراک کے لئے اجتہاد کرنا اور قیاس کی وجوہ میں تمیز و فرق کرنا اور اس کی شرائط کا علم اور سلف کے اقوال کی معرفت حاصل کرنا صحابہ کرام اور تابعین کے اقوال ہوں یا ان کے ماسوا کے اور اجتماع اور اختلاف کی تمیز و فرق کرنا۔\nچہارم:...... بعض اس میں سے اس چیز کی معرفت حاصل کرنا جس کے ساتھ کتاب و سنت میں سے احکام کی تلاش ممکن ہو سکے اور وہ علم ہے لسان عرب کا اور ان کی عادات کا مخاطبات میں اور احادیث و اخبار کے مراتب کی تمیز و فرق تا کہ ہر خبر اپنے اپنے مرتبے اور مقام پر اتر سکے اور اس لئے اس کا پورا پورا حق دیا جا سکے۔ اس کے بعد شیخ نے بیان کو جاری رکھے ہوئے کلام کو چلا دیا ہے اور فرمایا۔ کہ جو شخص علم کی طلب کا ارادہ رکھتا ہے اور وہ اہل زبان عرب میں سے نہیں ہے اس کے لئے یہی مناسب ہے کہ وہ پہلے پہلے زبان کو سیکھے اور اس میں خوب مشق پیدا کرے اس کے بعد قرآن کریم کا علم طلب کرے پھر بھی اس کے لئے قرآن پاک کے معانی اچھی طرح واضح نہیں ہوں گے مگر آثار کے ساتھ اور سنن کے ساتھ، آثار اور سنن کے معانی اچھی طرح واضح نہیں ہو سکیں گے مگر اخبار صحابہ کے ساتھ اور اخبار صحابہ واضح نہیں ہوں گے مگر اس تفصیل کے ساتھ جو تابعین سے آئی ہے۔ بے شک علم دین اسی طرح ہم لوگوں تک پہنچا ہے۔ جو شخص اس کا ارادہ رکھتا ہے وہ اس سیڑھی سے اور اسی درجہ سے اس کی طرف درجہ بدرجہ چڑھ جائے۔ اور آنے والا علم کے دروازے پر آئے اور اس کے سامنے آنے کا قصد کرے جب اللہ تعالیٰ اسے مجتہدین کے درجے اور مقام تک پہنچا دے تو اس وقت وہ اختلاف کرنے والوں کے اقوالوں میں نظر ڈالے اور ان میں سے جس کو چاہے پسند کرے جس کو زیادہ راجح اور زیادہ درست دیکھے، اور اس کو چاہئے کہ وہ قیاس بھی کرے جو حدیث بیان کرے اور اس کی بنیاد رکھے مستحکم اصولوں پر اور اولیٰ اور بہتر پر۔\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو العباس محمد بن یعقوب نے ان کو ربیع بن سلیمان نے ان کو امام شافعی رحمۃ اللہ علیہ نے وہ فرماتے ہیں کہ علم دو طرح کا ہے۔ اول: عام لوگوں کا علم جس میں وسعت نہ ہو وہ عاجز ہوتا ہے اس کے عقل پر نادانی کا غلبہ ہوتا ہے (علم محدود ہوتا ہے) مثلا یہ کہ نمازیں پانچ ہیں۔ اللہ نے لوگوں پر ماہ رمضان کے روزے فرض کر دیئے ہیں۔ اور بیت اللہ کا حج بھی بشرط استطاعت فرض ہے۔ لوگوں کے مالوں میں زکاۃ فرض ہے، اللہ نے ان پر زنا کو حرام کر دیا ہے اور قتل چوری شراب یہ سب حرام ہے اور اس طرح کی دیگر باتوں کا عالم جو اسی مفہوم میں ہیں جن کا اللہ نے بندوں کو مکلف کیا ہے لوگ ان کو کریں اور ان امور کو جائیں اور دل و جان سے اس کی تعظیم کریں اور یہ کہ رک جائیں ان امور سے جن کو اللہ نے ان پر حرام کیا ہے یہ علم کی وہ قسم عام موجود و اہل اسلام کے پاس جسے عام مسلمان گذشتہ لوگوں سے عوام سے بھی نقل کرتے آ رہے ہیں جسے وہ رسول اللہ سے حکایت کرتے ہیں اور اس کے بیان کرنے میں کوئی نزاع اور کوئی اختلاف بھی نہیں ہے اور اس چیز کا وہم ضروری اور لازم ہونے کے بارے میں اس عام علم کے بارے میں کسی کو کوئی اختلاف نہیں ہے ویسے بھی اس میں غلط ہونے کا کوئی امکان نہیں ہے قبر میں ہو یا تاویل میں اور اس میں جھگڑا جائز نہیں ہے۔\nوجہ ثانی:...... وہ علم جس کو بندے بعض بعض حاصل کرتے ہیں جس کا تعلق فرائض کے فروع سے ہے اور وہ جو مخصوص احکام وغیرہ سے متعلق ہو جس کے بارے میں نہ تو کتاب اللہ کی صراحت ہے اور نہ ہی ان میں سے زیادہ تر کے بارے میں سنت میں کوئی نص ہے اگر چہ فی نفسہ اس میں سے کسی قدر سنت سے ثابت ہو۔ ایسا علم اخبار خاصہ ہیں اخبار عامہ نہیں ہیں اور جو اس میں سے تاویل کا احتمال رکھے اور جو قیاس سے معلوم ہو سکے ایسا علم علم کا وہ درجہ ہے جس علم تک عام لوگوں کی پہنچ نہیں اور رسائی نہیں ہے اور اس علم کا مکلف پر خاص بھی نہیں ہے اور نہ ہی ہر خاص کی وہاں تک رسائی کا احتمال ہے اور نہ ہی تمام خاص لوگ مجموعی طور پر اس کی اجازت رکھتے ہیں کہ اسے معطل اور بے کار چھوڑ دیں۔ جب ایسے علم کو حاصل کرنے کے لئے کچھ خاص لوگ کمر بستہ ہو کر حاصل کریں تو باقی لوگ اس کے تارک نہیں کہلائیں گے انشاء اللہ تاہم فضیلت و برتری صرف انہیں حاصل ہوگی جو اسے حاصل کریں گے انہیں فضیلت حاصل نہیں ہوگی جو اس سے محروم رہیں گے اس بارے میں اللہ تعالیٰ کے اس فرمان کے ساتھ حجت پکڑی گئی ہے۔\n﴿وما كان المؤمنون لينفروا كافة فلولا نفر من كل فرقة منهم طائفة ليتفقهوا في الدين ولينذروا قومهم اذا رجعوا اليهم لعلهم يحذرون﴾\n’’سارے مومن تو دین کی فہم حاصل کرنے کے لئے نہیں جا سکتے۔ کیوں نہیں کہ ہر بڑی جماعت میں سے ایک مختصر جماعت دین کی فہم حاصل کرنے کے لئے نکل جائیں اور وہ دین کی سمجھ بوجھ حاصل کر کے آئیں اور اپنی قوم کو ڈرائیں واپس آ کر تا کہ وہ لوگ (جو دین سیکھنے میں رہ گئے تھے) وہ بھی ڈریں۔‘‘\nامام شافعی رحمۃ اللہ علیہ نے اس کی مثال جہاد فی سبیل اور صلوٰۃ جنازہ۔ اور میت کو دفن کرنے اور سلام کا جواب دینے سے دی ہے۔ ظاہر ہے فضیلت و ثواب جہاد میں شریک ہونے والے مجاہد کو نماز جنازہ میں شریک ہونے والے کو میت دفن کرنے والے پورے گروہ میں سے سلام کا جواب دینے والے کو ملے گا باقی سب لوگ گنہ گار ہونے سے بچ جائیں گے اور اگر کوئی بھی یہ اعمال انجام نہیں دے گا تو پورا معاشرہ گنہ گار ہوگا۔ واللہ اعلم۔ (1)","",{"k":"(1) رسالة الشافعى (ص ۳۵۷) وما بعدها۔"}],[1616,"ہم نے کتاب المدخل میں روایت کیا ہے، سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے کہ انہوں نے اس آیت کے بارے میں فرمایا اس سے مراد سرایا ہیں۔ یعنی ایک جماعت دین سیکھنے کے لئے چلی جائے اور ایک جماعت بیٹھ جائے تا کہ وہ دین میں سمجھ بوجھ حاصل کرے۔ فرماتے ہیں۔ اس کتاب کا علم سیکھو اللہ تعالیٰ نے جسے اپنے نبی صلی اللہ علیہ وسلم پر نازل فرمایا ہے، اور جب واپس آئیں ان کو آ کر دین سکھائیں جو سیکھنے کے لئے نہیں گئے تھے تا کہ وہ بھی ڈریں اور اللہ کی نافرمانی سے بچیں۔"],[1617,"§رفع علم کے اسباب کا بیان\nہمیں خبر دی ہے ابو محمد بن یوسف نے ان کو ابو سعید احمد بن زیاد بصری نے مکہ مکرمہ میں ان کو عباس بن محمد دوری نے ان کو محمد بن بشار نے ہشام بن عروہ سے ان کو ان کے والد نے ان کو سیدنا عبداللہ بن عمرو نے نبی کریم صلی اللہ علیہ وسلم سے اور ہمیں خبر دی ہے ابو الحسین بن فضل قطان نے اور ابو عبد اللہ حسین بن حسن غضائری نے دونوں فرماتے ہیں ہمیں حدیث بیان کی ہے حسن بن علی بن عفان عامری نے ان کو ابو اسامہ نے ان کو ہشام بن عروہ نے ان کو ان کے والد نے انہوں نے سنا عبد اللہ بن عمرو سے وہ کہتے ہیں کہ رسول اللہ نے فرمایا: بے شک اللہ تعالیٰ علم کو اس طرح قبض نہیں کریں گے کہ یکا یک وہ اس کو لوگوں سے کھینچ لیں لیکن علماء کو قبض کریں گے جب کوئی عالم نہیں رہے گا۔ اور صفار کی روایت میں ہے۔ یہاں تک کہ جب وہ کسی ایک عالم کو بھی باقی نہیں چھوڑے گا تو لوگ جاہل ترین سرداروں کو پکڑ لیں گے ان سے دین پوچھیں گے (بھلا وہ دین کہاں سے سمجھانے لگے وہ تو خود بڑے جاہل ہوں گے) بس پھر وہ بغیر علم کے فتوے دیں گے وہ خود گمراہ ہوں گے لہذا وہ لوگوں کو بھی گمراہ کریں گے۔"],[1618,"ہمیں حدیث بیان کی ہے ابو محمد اصفہانی نے ان کو ابو سعید نے ان کو حسن بن علی بن عفان نے ان کو جعفر بن عون نے ان کو ہشام بن عروہ نے ان کو ان کے والد نے ان کو عبد اللہ بن عمرو نے نبی کریم صلی اللہ علیہ وسلم سے۔ اس حدیث کو مسلم نے روایت کیا ہے صحیح میں ابو کریب سے انہوں نے ابو اسامہ سے اور دونوں نے اس کو نقل کیا ہے دوسرے طریق سے ہشام سے۔ اور تحذیر میں یعنی علم کے اٹھ جانے کا جو ڈر ہو اسنایا گیا ہے اس میں دلیل ہے اس کے طلب کے وجوب پر اور علم سیکھنے پر ابھارنا اور برانگیختہ کرنا ہے۔ (یعنی رفع علم سے ڈرانے کا مطلب ہی یہی ہے کہ لوگ اس کو سیکھیں اس لئے کہ سیکھنا ضروری ہے۔)"],[1619,"ہمیں خبر دی ابو عبد اللہ حافظ نے انہوں نے سنا ابو بکر بن مؤمل سے کہتے تھے کہ ان کو بیان کیا فضل بن محمد شعرانی نے ان کو نفیلی نے ان کو عباد بن عوام نے ان کو ہلال بن خباب نے وہ کہتے ہیں کہ میں نے حضرت سعید بن جبیر سے پوچھا کہ لوگوں کی ہلاکت کی کیا علامت ہے؟ انہوں نے جواب دیا جب ان کے علماء ہلاک ہو جائیں گے یہی وقت لوگوں کی ہلاکت کا بھی ہے۔"],[1620,"§علم طلب کرنا فرض ہے\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو الحسن علی بن محمد بن عقبہ شیبانی نے، ان کو محمد بن علی بن عفان نے (ح) اور ہمیں خبر دی ہے محمد اصفہانی نے ان کو ابو سعید بن زیاد نے ان کو جعفر بن عامر عسکری نے دونوں نے کہا کہ ہمیں حدیث بیان کی ہے حسن بن عطیہ بن ابو عاتکہ\n(۱۶۶۰، ۱۶۶۱) أخرجه البخاري (۳۶/۱) ومسلم (۲۰۵۸/۴) من طريق هشام به. وأخرجه مسلم (۲۰۵۸/۴) عن أبي كريب عن أبي أسامة وغيره به.\n(۱۶۶۱) أخرجه البخاري (۳۶/۱) ومسلم (۲۰۵۸/۴) من طريق هشام به.\n(۱۶۶۲) النفيلي هو عبد الله بن محمد.\n(۱۶۶۳) أخرجه ابن عدي (۱۸۲/۱) والعقيلي (۲۳۰/۱) وفيه أبو عاتكة طريف بن سليمان منكر الحديث. وقال ابن حبان حديث باطل لا أصل له. وهذا الحديث له طرق كثيرة وانظر تنزيه الشريعة (۲۵۸/۱) جامع بيان العلم (۱/۷ و ۸) تاريخ بغداد (۳۱۴۱۹).\nنے اور ابو عبد اللہ کی روایت میں ہے ان کو بیان کیا ابو عاتکہ نے ان کو سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ نے روایت لاتے ہیں کہ رسول اللہ نے فرمایا۔ علم کو تلاش کرو اگر چہ چین میں جانا پڑے۔ بے شک علم کا طلب کرنا فرض ہے ہر مسلمان پر۔\nیہ حدیث بطور محاورہ مشہور ہے اور اس کی اسناد ضعیف ہے اور تحقیق کئی وجوہ سے مروی ہے مگر تمام وجوہ ضعیف ہیں۔"],[1621,"ہمیں خبر دی ابو عبد اللہ نے ان کو ابو العباس رحم نے ان کو عباس بن محمد نے ان کو ابو انظر ہاشم بن قاسم نے ان کو مسلم بن سعید نے زیاد بن عامر سے ان کو سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ نے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا علم کا طلب کرنا ہر مسلمان پر فرض ہے اور اللہ تعالیٰ مجبور کی فریاد رسی کرنے کو پسند کرتا ہے۔"],[1622,"ہمیں خبر دی ہے ابو الحسن علی بن محمد بن علی مقری سے ان کو حسن بن محمد بن اسحاق نے ان کو یوسف بن یعقوب قاضی نے ان کو محمد بن ابی بکر نے ان کو حسان بن سیاہ ان کو ثابت نے ان کو انس بن مالک رضی اللہ تعالیٰ عنہ نے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ علم کو طلب کرنا ہر مسلمان پر فرض ہے۔"],[1623,"ہمیں خبر دی ابو محمد بن یوسف نے ان کو ابو سعید بن اعرابی نے ان کو عباس بن عبد اللہ ترقی نے ان کو رواد بن جراح نے ان کو عبد القدوس نے ان کو حماد بن ابو سلیمان نے ان کو ابراہیم نے وہ کہتے ہیں کہ میں نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے ایک حدیث کے سوا کچھ نہیں سنا وہ فرماتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ علم کو طلب کرنا فرض ہے ہر مسلمان پر۔"],[1624,"ہمیں خبر دی ہے ابو الحسن علی بن محمد بن علی اسفرائنی نے ان کو ابو سہل بن زیاد قطان نے ان کو حسن بن مکرم نے ان کو یحییٰ بن ہاشم نے ان کو (شہر) نے ان کو عطیہ نے ان کو ابو سعید نے وہ کہتے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا علم کا طلب کرنا فرض ہے ہر مسلمان پر۔"],[1625,"§قرآن سیکھنے اور سکھانے کا بیان\nہمیں خبر دی ہے ابو الحسن علی بن محمد بن علی مقری نے ان کو حسن بن محمد بن اسحاق نے ان کو یوسف بن یعقوب نے ان کو محمد بن ابو بکر نے ان کو کشتی بن بکر عطار نے ان کو عوف نے ان کو سلیمان نے ان کو ابو الاحوص نے ان کو عبد اللہ نے وہ کہتے ہیں کہ رسول اللہ نے فرمایا۔ کہ قرآن کو سیکھو اور وہ لوگوں کو سکھلاؤ اور علم سیکھو اور وہ لوگوں کو سکھلاؤ اور فرائض (علم میراث) سیکھو اور وہ لوگوں کو سکھلاؤ میں ایک ایسا آدمی ہو جو قبض (فوت ہونے والا ہوں، اور بے شک علم عنقریب قبض کر لیا جائے گا یہاں تک کہ لوگ فرائض کا علم نہیں رکھیں گے اس میں بھی باہم اختلاف کریں گے کوئی ایسا انسان نہیں پائیں گے جو ان کو فرائض کے بارے میں بتلا سکے۔\n(۱۶۶۴) أخرجه ابن عبد البر في جامع البيان (۸/۱) من طريق زياد بن ميمون عن أنس.\n(۱۶۶۵) أخرجه ابن عبد البر في جامعه (۸/۱) من طريق حسان بن سياه به وفيه زيادة.\n(۱۶۶۶) أخرجه ابن عبد البر (۸/۱) من طريق رواد بن الجراح.\n(۱۶۶۷) قال الهيثمي في المجمع (۱۲۰/۱) رواه الطبراني في الأوسط وفيه يحيى بن هاشم السمسار كذاب.\n(۱) غير واضح بالأصل.\n(۱۶۶۸) قال الهيثمي في المجمع (۲۲۳/۴) رواه أبو يعلى والبزار وفي إسناده من لم أعرفه وأخرجه الدارقطني في سننه (۸۲، ۸۱/۴) من طريق عمرو بن حمران عن عوف به. وقال الدارقطني: تابعه جماعة عن عوف ورواه المثنى بن بكر عن عوف عن سليمان بن جابر عن أبي الأحوص عن عبد الله عن النبي صلى الله عليه وسلم بهذا وقال الفضل بن ولهم عن عوف عن شهر عن أبي هريرة.\nسلیمان یہ وہی ابن جابر ہیں اور تحقیق کہا گیا ہے کہ حضرت عوف سے انہوں نے سیدنا ابن مسعود سے روایت کیا ہے اور عوف سے اور اس سے حسن نے ان کو حدیث بیان کی سلیمان سے۔"],[1626,"ہمیں خبر دی ہے ابو الحسین بن بشران نے ان کو ابو عمرو بن سماک نے ان کو حنبل بن اسحاق نے ان کو بکار بن محمد نے ان کو عون نے ان کو ابن سیرین نے ان کو احنف بن قیس نے وہ کہتے کہ سیدنا عمر نے فرمایا دین کی سمجھ حاصل کرو اس سے قبل کہ تم سردار بنو۔"],[1627,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو جعفر بن محمد بن نصیر نے ان کو احمد بن محمد بن مسروق نے ان کو محمد بن حمید نے ان کو اسباط بن محمد نے ان کو سفیان ثوری نے وہ کہتے ہیں کہ جو شخص سردار بنے میں جلدی کرے وہ بہت سارے علم کا نقصان کرتا ہے۔ اور جو شخص حکمران اور سردار بننے میں جلدی نہیں کرتا لکھتا ہے پھر لکھتا ہے اور پھر لکھتا ہے۔"],[1628,"ہمیں خبر دی ابو عبد اللہ نے کہتے کہ ہمیں خبر دی جعفر نے وہ کہتے ہیں کہ ہمیں خبر دی ان کو بکر بن داؤد نے وہ کہتے ہیں میں نے سنا اپنے والد سے وہ کہتے ہیں جو شخص اپنی ذات کے لئے حدیث لکھتا ہے وہ سخاوت نہیں کرتا (یعنی کنجوسی کرتا ہے) اور جو شخص لوگوں کے لئے لکھتا ہے وہ سخاوت کرتا ہے۔"],[1629,"ہمیں خبر دی ابو نصر بن قتادہ نے ان کو ابو الحسن سراج نے ان کو مطین نے ان کو عبد الجبار بن عاصم نے ان کو بقیہ بن ولید نے ان کو ابو سعید و باقی نے ان کو اسحاق بن عبد اللہ بن ابی طلحہ نے ان کو سیدنا انس نے کہتے ہیں کہ رسول اللہ نے فرمایا۔ علم کو طلب کرنا واجب ہے ہر مسلمان پر۔"],[1630,"§بہترین تحفہ علم و ادب سکھانا ہے\nہمیں خبر دی ابو الحسین محمد بن حسین علوی نے ان کو عبدوس بن حسین سمار نے ان کو یوسف بن عبد اللہ بن ماہان دینوری نے ان کو محمد بن کثیر نے (ح) اور ہمیں خبر دی ہے ابو محمد حسن بن احمد بن ابراہیم بن فراس نے مکہ۔ ان کو اور بن ابراہیم بن محمد ضحاک نے ان کو ابو عبد اللہ نے ان کو علی بن عبد العزیز نے ان کو مسلم نے ان کو قواریری نے وہ دونوں کہتے ہیں کہ ان کو عامر بن ابی عامر فراز نے ان کو ایوب بن موسیٰ قرشی نے ان کو ان کے والد نے ان کو ان کے دادا نبی کریم صلی اللہ علیہ وسلم نے آپ نے فرمایا۔ کوئی والد اپنے بیٹے کو اچھے ادب سکھانے سے افضل کوئی تحفہ نہیں دے سکتا۔ لفظ حدیث رسول کے ہیں علاوہ اس کے انہوں نے نہیں کہا خزاز اور علوی نے کہا ہے انہی حدیث میں کہ رسول اللہ نے فرمایا۔ اور قرشی نے بھی نہیں کہا وہ ایوب بن موسیٰ بن عمرو بن سعید بن عاص ہیں۔\n(۱۶۶۹) قال العجلوني في كشف الخفاء (۳۷۰/۱) رواه البيهقي عن عمر من قوله وعلقه البخاري جازماً به.\n(۱۶۷۰) كشف الخفاء (۳۷۰/۱).\n(۱۶۷۲) أخرجه ابن عبد البر (۸/۱) من طريق بقية عن الأوزاعي عن إسحاق به. ومن طريق بقية عن أبي عبد السلام الوحاظي عن إسحاق به.\n(۱۶۷۳) أخرجه الترمذي (۱۹۵۲) والحاكم (۲۶۳/۴) من طريق عامر به. وقال الترمذي هذا حديث غريب لا نعرفه إلا من حديث عامر بن أبي عامر الخزاز وهو عامر بن صالح بن رستم الخزاز وأيوب بن موسى بن عمرو بن سعيد بن العاص وهذا عندي مرسل. والحديث صححه الحاكم وتعقبه الذهبي بأن عامر واه."],[1631,"§سیدنا عمر رضی اللہ تعالیٰ عنہ کا قول\nہمیں خبر دی ہے ابو محمد بن فراس کی نے اس کے بارے میں ابو عبد اللہ ضحاک نے ان کو علی بن عبد العزیز نے ان کو محمد بن عبد اللہ ابو یحییٰ نے ان کو مروان نے ان کو عاصم احول نے ان کو موزو عجلی نے وہ کہتے ہیں کہ سیدنا عمر نے فرمایا سنت کو سیکھو اور فرائض کو سُر اور لغت کو سیکھو۔ جیسے تم قرآن کو سیکھتے ہو۔"],[1632,"ہمیں خبر دی ہے ابو القاسم عبد الرحمن بن عبد اللہ حرف نے بغداد میں ان کو ابو الحسن علی بن محمد بن زبیر کوفی نے ان کو حسن بن علی بن عفان نے ان کو زید بن حباب نے ان کو عبد الوارث بن سعید عنبری ان کو ابو مسلم نے پچاس سال سے کہ عمر بن خطاب رضی اللہ تعالیٰ عنہ نے فرمایا عربی زبان سیکھو بے شک وہ مروت میں اضافہ کرتی ہے۔"],[1633,"ہمیں خبر دی ہے ابو محمد بن فراس نے ان کو ابو عبد اللہ بن ضحاک نے ان کو علی بن عبد العزیز نے ان کو ابن عمار نے ان کو عضیف نے وہ ابن سالم میں عبد الوارث بن سعید نے ان کو ابو مسلم نے وہ اور بصرہ کے ایک آدمی تھے انہوں نے کہا کہ سیدنا عمر نے فرمایا تھا عربی زبان سیکھو بے شک وہ عقل کو پکارتی ہے اور مروت میں اضافہ کرتی ہے۔"],[1634,"ہمیں خبر دی ابو القاسم حرفی نے ان کو علی بن محمد بن زبیر ان کو حسن بن علی نے ان کو زید بن حباب نے ان کو طلحہ بن عمرو مکی نے ان کو عطاء بن ابی رباح نے کہتے ہیں مجھے خبر پہنچی ہے کہ سیدنا عمر رضی اللہ تعالیٰ عنہ نے ایک آدمی سے سنا جو فارسی میں کلام کر رہا تھا طواف کے دوران انہوں نے اس کے بازوں سے پکڑ کر کہا عربی زبان کی طرف راستہ تلاش کیجئے۔"],[1635,"§زبان کا لہجہ درست ہونا ضروری ہے\nاور ہم نے روایت کیا ہے سیدنا عمر نے غیر قوی اسناد کے ساتھ کہ وہ ایسے لوگوں پر گذرے جو تیراندازی کی مشق کر رہے تھے انہوں نے فرمایا تم نے غلط تیراندازی کی ہے انہوں نے کہا کہ ہم ابھی سیکھ رہے ہیں۔ آپ نے فرمایا تمہارا زبان کے لہجے میں غلطی کرنا میرے نزدیک تمہاری تیراندازی کی غلطی کرنے سے زیادہ سخت ہے۔ اور پھر آپ نے ایک حرفی حدیث بیان کی کہ اللہ تعالیٰ اس آدمی پر رحم کرے جو اپنی زبان کو درست کرتا ہے۔"],[1636,"ہم نے ابو موسیٰ سے روایت کی ہے کہ انہوں نے لکھا سیدنا عمر کی کہ یہ ابو موسیٰ کی طرف سے پھر ان کی طرف عمر نے لکھا کہ آپ اپنے کاتب کو چابک کرادے۔\n(۱۶۷۵) أخرجه الخطيب في الجامع لأخلاق الراوي (۱۰۱۷) بنفس الإسناد.\n(۱۶۷۶) أخرجه أبو القاسم الحرفي في فوائده وابن المرزبان في كتاب المروءة والمصنف والخطيب في الجامع عن أبي مسلم البصري عن عمر. ورواه ابن الأنباري في الإيضاح من طريق مجاهد عن عمر (الكنز ۹۰۳۷).\n(۱۶۷۷) أخرجه أبو القاسم الحرفي والمصنف (الكنز ۹۰۳۸).\n(۱۶۷۸) أخرجه الخطيب في الجامع (۱۰۲۶).\n(۱۶۷۹) أخرجه ابن الأنباري وابن أبي شيبة (الكنز ۲۹۵۵۰).\n(۱۶۸۰) أخرجه الخطيب في الجامع (۱۰۸۲) بنفس الإسناد.\n(۱) في الأصل عمرو بن العاص رضي الله عنهما وما أثبتناه من الجامع الآداب الراوي للخطيب."],[1637,"ہمیں خبر دی ابو القاسم بن عبید اللہ بن عبد اللہ حرفی نے ان کو علی بن محمد بن زبیر نے ان کو حسن بن علی نے ان کو ربیع سمان نے ان کو عمرو بن دینار نے یہ کہ ابن عمر و ابن عباس رضی اللہ تعالیٰ عنہ اپنی اولاد کو مارتے تھے لہجے اور تلفظ کی غلطی"],[1638,"ہمیں خبر دی ابو عبد الرحمن سلمی نے ان کو ابو الحسن کارزی نے ان کو علی بن عبد العزیز نے ان کو ابو عبیدہ نے ان کو ہشیم نے ان کو عبد اللہ بن عبد اللہ بن عتبہ نے ان کو ابن عباس رضی اللہ تعالیٰ عنہ کہ بے شک وہ قرآن کے بارے میں پوچھتے جاتے تھے۔ اور وہ اس بارے میں شعر سناتے تھے۔ (یعنی کسی بھی جملے کی شہادت کے طور پر کوئی شعر پڑھ کر عرب کا استعمال واضح کرتے تھے۔)"],[1639,"ابو عبیدہ سے مروی ہے ان کو یحییٰ بن سعید نے بیان کیا ان کو سفیان نے ان کو ابراہیم بن مہاجر نے ان کو مجاہد نے ان کو سیدنا انس عباس رضی اللہ تعالیٰ عنہ نے فرماتے ہیں کہ میں نہیں جانتا تھا کہ فاطر السموات کا مفہوم کس طرح ہے حتی کہ میرے پاس دو دیہاتی عربی آئے جو کہ میرے پاس ایک کنویں کا جھگڑا لے کر آئے تھے دونوں میں سے ایک بولا انا فطرتها انا ابتدأتها میں نے اس کو از سرے بنایا ہے۔ یعنی اسے میں نے کھودا ہے۔ (یعنی مجھے اب عرب کی دیہاتی استعمال سے واضح ہوا کہ اس کا مطلب ہے ابتداء اور پہلی بار بنانے والا۔)"],[1640,"§سیدنا ابن عباس رضی اللہ تعالیٰ عنہ کا قول\nہمیں خبر دی ابو عبد اللہ حافظ نے اور محمد بن موسیٰ نے دونوں نے کہا ہمیں حدیث بیان کی ہے ابو العباس محمد بن یعقوب نے ان کو احمد بن عبد الجبار نے ان کو وکیع نے ان کو اسامہ بن زید نے ان کو عکرمہ نے ان کو ابن عباس نے وہ کہتے ہیں تم میں سے کوئی شخص جب قرآن میں سے کوئی شے پڑھے اور وہ نہ جانے کہ اس کی کیا تفسیر ہے اسے چاہئے کہ اسے وہ عرب شعراء کے شعروں میں تلاش کرے بے شک وہ عرب کا دیوان ہے۔"],[1641,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے فوائد شیخ میں ان کو مکی بن بندار نے زنجانی نے بغداد میں ان کو محمد بن احمد بن رجاء حنفی نے مصر میں ان کو ہارون بن محمد بن ابو سفید ام عسقلانی نے ان کو عثمان بن ابو طالوت محمدری نے ان کو بشر بن عمرو بن علاء نے ان کو ان کے والد نے ان کو ذیال بن حرملہ نے ان کو صعصعہ بن صوحان نے وہ کہتے ہیں کہ ایک اعرابی سیدنا علی کے پاس آیا اور بولا السلام علیکم یا امیر المؤمنین آپ اس حرف کو کیسے پڑھتے ہیں۔ لا يأكله الا الخاطون. كل والله يخطو. یہ سن کر سیدنا علی مسکرائے اور فرمایا اے اعرابی لا يأكله الا الخاطئون اعرابی نے کہا آپ نے سچ فرمایا اے امیر المومنین اللہ تعالیٰ اپنے بندے کو بے یار و مددگار نہیں چھوڑے گا اس کے بعد ابو الاسود دولی کی طرف متوجہ ہو کر فرمایا عجمی لوگ دین میں داخل ہو چکے ہیں زیادہ تر لہذا لوگوں کے لئے کوئی ایسی چیز وضع کریں جس کے ساتھ وہ اپنی زبانوں کو اصلاح پر دلیل پکڑ سکیں اور اس کے لئے رفع نصب اور جر کی علامت لگا دی ہے۔ (یہاں تک)"],[1642,"§نحوی ترکیب\nہمیں خبر دی ابو عبد اللہ حافظ نے ان کو حسن بن علی نے بن احمد رتانی نے مرو میں ان کو احمد بن جعفر بن محمد بغدادی نے جو کہ ہمارے پاس آئے تھے۔ ان کو ابو امیہ طرطوسی نے ان کو عبد اللہ بن صالح بن مسلم بجلی نے ان کو ابو زید نحوی نے۔ کہتے ہیں کہ انہوں نے کہا ایک آدمی حسن بصری کے پاس آئے اور بولے آپ کیا کہتے ہیں اس آدمی کے بارے میں ترک ابيه واخيه۔ حضرت حسن بصری نے کہا یوں کہوں ترک اباہ واخاہ اس آدمی نے کہا اباہ اور اخاہ سے کیا ہوگا۔ حضرت حسن بصری نے فرمایا ابیہ اور اخیہ سے کیا فائدہ ہوگا اس آدمی نے کہا دیکھئے جب بھی میں\n(۱۶۸۳) أخرجه المصنف وابن عساكر وابن النجار (الكنز ۲۹۳۵۷).\n(۱) الحديث في كنز العمال دون قوله إلى هنا.\nآپ کی متابعت کرتا ہوں آپ میری مخالفت کر دیتے ہیں (حالانکہ وہ شخص نحوی اعتبار سے عربی غلط بول رہا تھا حضرت حسن اس کی اصلاح کر رہے تھے۔)"],[1643,"ہمیں خبر دی ابو الحسن محمد بن عبد الرحمن بن محمد بن عبدان شروطی نے ان کو ابو العباس عبد الوارث نے ان کو حدیث بن سائب نے کہتے ہیں کہ میں حسن بصری کے پاس حاضر ہوا تو ان کے پاس ایک آدمی آیا اور بولا: یا ابو سعید کسب الدوانیق سفلک اور آپ کہتے ہو یا ابا سعید۔"],[1644,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو العباس اصم نے ان کو سری بن یحییٰ نے ان کو عثمان بن زفر نے ان کو حبان بن علی نے ان کو ابن شبرمہ نے انہوں نے کہا عربی سے زیادہ بہتر کسی عبارت کے ساتھ لوگوں نے کبھی کسی چیز کو تعبیر نہیں کیا۔"],[1645,"ہمیں خبر دی ابو عبد اللہ حافظ نے انہوں نے سنا ابو بکر بن اسماعیلی سے وہ کہتے ہیں مجھے خبر دی مرزبانی نے ان کو محمد بن فضل نے ان کو ریاشی نے ان کو اصمعی نے کہ وہ ایک آدمی کے ساتھ گذرے جو یوں دعا کر رہا تھا یا ذو الجلال والاکرام۔ چنانچہ اصمعی نے اس سے کہا اے فلانے! کیا نام ہے آپ کا؟ اس نے کہا تم پھر اصمعی نے کہا اپنے رب سے مناجات کرنا غلط الفاظ کے ساتھ (جھوٹے کی مانند) جب اس کو پکارے تو درست تلفظ کرے۔"],[1646,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو سعید مؤدب نے ان کو عباس بن فضل محمد اباذی نے ان کو ابو حاتم رازی نے وہ کہتے ہیں کہ ذکر کیا تھا علی بن جعد نے شعبہ سے کہتے ہیں انہوں نے کہا جب کوئی محدث نحو کو نہ جانتا ہو وہ اس گدھے کی مثل ہے جس کے سر پر خالی توبرا (تھیلا) چڑھا ہوا ہو جس میں جو نہ ہوں۔"],[1647,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے وہ کہتے ہیں کہ ہمیں خبر دی ابو احمد بن حمد بن علی فہری بغدادی نے کہتے ہیں میں نے سنا حسن بن سفیان سے انہوں نے سنا حسان بن موسیٰ سے کہتے ہیں کہ انہوں نے سنا عبد اللہ بن مبارک سے کہ کوئی آدمی علم کی کسی قسم میں مہارت حاصل نہیں کر سکتا جب تک وہ اپنے علم کو ادب کے ساتھ آراستہ کرے۔"],[1648,"ہمیں خبر دی ہے محمد بن ابو المعروف فقیہ نے ان کو ابو سہل اسفرائنی نے ان کو ابو جعفر حذاء نے ان کو علی بن مدینی نے ان کو حماد بن زید نے ان کو یحییٰ بن عتیق وہ کہتے ہیں میں نے حسن سے یا ابا سعید سے کہا ایک آدمی عربی سیکھتا ہے اس کے ساتھ وہ اچھی بولی چاہتا ہے اور اس کے ساتھ اپنی قرآت درست کرتا ہے انہوں نے کہا اچھا کر کے اس کا پڑھنا ایسے ہے جیسے کوئی شخص آیت کو صحیح کر کے پڑھے ارادہ کرتا ہے اس کی رضا کا اور بعض دفعہ ہلاک ہوتا ہے اس کی وجہ سے۔"],[1649,"ہمیں خبر دی ہے ابو محمد عسکری نے بغداد میں ان کو محمد بن عبد اللہ بن ابراہیم شافعی نے ان کو جعفر بن محمد بن ازہر نے ان کو غلابی نے ان کو واقدی نے ان کو ابو الزناد نے ان کو ان کے باپ نے انہوں نے کہا مشرق میں کلام عرب کے ساتھ جاہلوں نے زندیقی اور بے دینی کی تھی ان کے دل کج تھے۔"],[1650,"ہمیں خبر دی ہے ابو محمد ان کو محمد بن عبد اللہ شافعی نے ان کو جعفر بن محمد نے ان کو غلابی نے ان کو ربی نے وہ کہتے ہیں کہ سفیان بن عیینہ نے کہا طلب علم کے ساتھ کون لوگوں میں سے زیادہ حق دار ہے؟ کہئے اے ابو محمد انہوں نے کہا کہ عالم زیادہ حق دار ہے اس لئے کہ جبل نہیں۔ اس سے زیادہ بیج اس سے عالم کے ساتھ۔\n(۱) بياض بالأصل.\n(۲) غير واضح بالأصل.\n(۳) كلمة غير واضحة."],[1651,"کہتے ہیں کہ ہمیں حدیث بیان کی ہے غلابی نے ان کو ابو سہل مدائنی نے کہتے ہیں کہ سفیان نے کہا جب کہ سوال کیا تھا اے ابو محمد علم افضل ہے یا عمل؟ انہوں نے فرمایا کہ علم افضل ہے کیا آپ نے اللہ تعالیٰ کا یہ فرمان نہیں سنا۔ فاعلم انه لا اله الا الله واستغفر لذنبك. اے پیغمبر آپ جان لیجئے کہ اللہ کے سوا کوئی الہ نہیں ہے اور اپنی لغزش کے لئے اللہ تعالیٰ سے بخشش طلب کیجئے۔ اللہ تعالیٰ نے اس آیت میں عمل سے قبل علم کے ساتھ ابتداء کی ہے۔ (اس سے معلوم ہوا کہ علم عمل سے افضل ہے۔)"],[1652,"§فصل: علم کی فضیلت اور اس کا بلند مرتبہ\nارشاد باری تعالیٰ ہے۔\n§﴿شهد الله انه لا اله الا هو والملائكة واولوا العلم﴾\n’’اللہ تعالیٰ نے شہادت دی ہے کہ اس کے سوا کوئی معبود نہیں ہے مگر وہی ہے اور فرشتوں نے اور اہل علم نے بھی شہادت دی ہے۔‘‘\nاللہ تعالیٰ علماء کے نام کو اپنے فرشتوں کے ساتھ ملا دیا ہے جس طرح اللہ نے ملائکہ کے نام کو اپنے نام کے ساتھ ملا دیا ہے۔ جیسے ملائکہ کی فضیلت واجب ہے اس اکرام کی وجہ سے جو اللہ نے ان کو عطا کیا ہے اسی طرح علماء کی فضیلت بھی واجب ہے اسی اکرام کی وجہ اللہ نے ان کو جو عطا کیا ہے اس کی مثل۔ اور ارشاد باری تعالیٰ ہے:\n§﴿انما يخشى الله من عباده العلماء﴾\n§’’یقینی بات ہے کہ اللہ کے بندوں میں سے علماء ہی اللہ تعالیٰ سے ڈرتے ہیں۔‘‘\nاس آیت میں اللہ تعالیٰ نے یہ واضح فرما دیا ہے کہ خشیت الہی علم کے بسبب ہوتی ہے اور ارشاد باری ہے۔\n§﴿هل يستوى الذين يعلمون والذين لا يعلمون﴾\n§’’کیا وہ لوگ جو جانتے ان کے برابر ہو سکتے ہیں جو نہیں جانتے (یعنی عالم و جاہل برابر نہیں ہو سکتے۔)‘‘\n§نیز اللہ تعالیٰ نے اپنے رسول پر احسان جتلاتے ہوئے ارشاد فرمایا ہے:\n§﴿وانزل الله عليكم الكتاب والحكمة وعلمك مالم تكن تعلم وكان فضل الله عليك عظيما﴾\n’’اللہ تعالیٰ نے تیرے اوپر کتاب اور حکمت نازل کی ہے اور تجھے وہ چیز سکھلائی ہے جو آپ نہیں جانتے تھے اور تیرے اوپر اللہ کا فضل عظیم ہے۔‘‘\nاور ارشاد باری ہے۔\n§﴿نرفع درجات من نشاء وفوق كل ذى علم عليم﴾\n§’’ہم جس کے چاہتے ہیں درجات بلند کرتے ہیں اور ہر صاحب علم سے اوپر بڑے علم والا ہوتا ہے۔‘‘\nاور اللہ تعالیٰ نے فرمایا۔ کہ جو ایمان اسلام کے ساتھ علم سے آراستہ ہو اس میں اضافہ ہو جاتا ہے فرمایا۔\n§﴿يرفع الله الذين امنوا منكم والذين اوتوا العلم درجات﴾\n§’’اللہ تعالیٰ نے ان لوگوں کو بلند کر دیا ہے تم میں سے جو ایمان لائے ہیں اور جو علم دیئے گئے ہیں درجات میں۔‘‘\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے اور محمد بن موسیٰ نے دونوں نے کہا کہ ہمیں حدیث بیان کی ہے ابو العباس محمد بن یعقوب ان کو احمد بن عبد الجبار نے ان کو ابو معاویہ نے ان کو اعمش نے ان کو ابو صالح نے ان کو ابو ہریرہ رضی اللہ تعالیٰ عنہ فرماتے ہیں کہ رسول اللہ نے فرمایا جو جو شخص کسی مسلمان کی تکلیف اور پریشانی دور کرے دنیا کی پریشانیوں میں سے اللہ تعالیٰ اس کی قیامت کی پریشانیوں میں سے کوئی پریشانی دور کر دیں گے۔ اور جو شخص کسی تنگ دست کے لئے آسانی کریں گے۔ اللہ تعالیٰ اس کے دنیا اور آخرت میں آسانی کریں گے مسلمان پر پردہ پوشی کرے گا اللہ تعالیٰ اس پر دنیا اور آخرت میں پردہ ڈالے گا اور اللہ تعالیٰ بندے کی معاونت میں لگا رہتا ہے جب تک بندہ اپنے بھائی کی معاونت میں لگا رہتا ہے اور جو شخص کسی ایسے راستے پر چلتا ہے جس پر وہ علم کی تلاش کرتا ہے تو اللہ تعالیٰ اس کے لئے جنت کی طرف راستہ آسان کر دیتا ہے۔ اور اللہ گھروں میں سے کسی گھر میں جب کچھ لوگ جمع ہو جاتے ہیں جو ایک دوسرے سے قرآن سیکھتے ہیں اور باہم سکھاتے ہیں ان پر سکینہ نازل ہوتا ہے اور فرشتے ان کو گھیرے رہتے ہیں اور رحمت ان کو چھپا لیتی ہے اور اللہ تعالیٰ اس کا تذکرہ ان مقرب فرشتوں کے آگے کرتے ہیں جو اللہ کے پاس ہیں۔ وہ شخص جس کو اس کا عمل پیچھے کر دے اس کا نسب اس کو آگے نہیں کر سکے گا۔ اس کو مسلم نے صحیح میں یحییٰ بن یحییٰ وغیرہ سے اس نے ابو معاویہ سے نقل کیا ہے۔"],[1653,"§طالب علم کے لئے فرشتے پر بچھا دیتے ہیں\nہمیں خبر دی ہے ابو محمد عبد اللہ بن یوسف اصفہانی ہمیں املا کروایا ابو سعید احمد بن محمد بن زیاد بصری نے مکہ مکرمہ میں ان کو ابو یعلیٰ نے سیاجی نے ان کو عبد اللہ بن داؤد خریبی نے ان کو عاصم بن رجاء بن حیوۃ نے ان کو داؤد بن جمیل نے ان کو کثیر بن قیس نے وہ کہتے ہیں کہ میں سیدنا ابو الدرداء رضی اللہ تعالیٰ عنہ کے پاس آیا وہ دمشق کی مسجد میں بیٹھے ہوئے تھے میں نے کہا اے ابو درداء میں آپ کے پاس مدینۃ الرسول سے آیا ہوں ایک حدیث کی طلب میں جس کے بارے مجھے خبر ملی ہے کہ آپ وہ حدیث رسول اللہ سے بیان کرتے ہیں سیدنا ابو الدرداء نے فرمایا کہ تجھے کوئی اور غرض یہاں نہیں لائی؟ اور نہ ہی کوئی تجارت آپ کو یہاں لائی ہے؟ کوئی چیز تمہیں یہاں نہیں لائی مگر یہ حدیث؟ میں نے کہا کہ جی ہاں کہتے ہیں کہ میں نے سنا کہ رسول اللہ صلی اللہ علیہ وسلم فرما رہے تھے جو شخص کسی ایسے راستے پر چلتا ہے جس میں وہ علم کو تلاش کرتا ہے اللہ تعالیٰ اس کے لئے جنت کے راستوں میں سے ایک راستہ طے کرا دیتے ہیں اور بے شک فرشتے اپنے پروں کو بچھا دیتے ہیں طالب علم کی خوشی کے لئے جو عمل وہ کرتا ہے۔ بے شک عالم کی فضیلت عابد پر ایسے ہے جیسے چودھویں رات کے چاند کو تمام ستاروں پر اور بے شک عالم کے لئے استغفار کرتی ہیں وہ تمام مخلوقات جو آسمانوں میں ہیں اور وہ جو زمین میں ہیں حتی کہ مچھلیاں پانی کے پیٹ میں۔ اور بے شک علماء انبیاء کے وارث ہیں اور بے شک انبیاء نہیں وارث بناتے دینار اور درہم کا وہ وارث بناتے ہیں علم کا جس نے اس وراثت کا حصہ پالیا اس نے بہت بڑا حصہ پالیا۔"],[1654,"§طالب علم کے لئے مغفرت کی دعا\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے اور ابو عبد اللہ اسحاق بن محمد سوسی نے ابو العباس محمد بن یعقوب نے کہا ان کو ابو بکر محمد بن اسحاق صنعانی نے ان کو ابراہیم بن عرعرہ نے ان کو عبد الملک بن عبد الرحمن زماری نے ان کو سفیان نے اوزاعی سے ان کو کثیر بن قیس نے یزید بن سمرہ سے ان کو ابو درداء نے کہتے کہ میں نے سنا رسول اللہ صلی اللہ علیہ وسلم سے آپ فرما رہے تھے۔ جو شخص کسی ایسے راستے پر چلے جس میں وہ علم کی\n(۱۶۹۵) أخرجه مسلم (۲۰۷۴/۴) عن يحيى بن يحيى التميمي وأبو بكر بن أبي شيبة ومحمد بن العلاء الهمداني عن أبي معاوية به.\n(۱۶۹۶) أخرجه أبو داود (۳۶۴۱) من طريق عبد الله بن داود الخريبي به. وأخرجه المصنف في (الأربعون الصغرى ۳) من طريق إبراهيم بن مرزوق عن عبد الله بن داود به.\nتلاش کرے اللہ اس کو جنت کا راستہ طے کرا دیتے ہیں۔ اور بے شک فرشتے اپنے پروں کو طالب علم کی رضا کے لئے بچھا دیتے ہیں اس کے سبب سے جو وہ عمل کرتا ہے۔ اور بے شک عالم کے لئے استغفار کرتے ہیں وہ جو آسمانوں میں ہیں اور وہ جو زمین میں ہیں اور پانی میں مچھلیاں اور خشکی کے تمام جانور دعا کرتے ہیں۔ اور بے شک عالم کی فضیلت عابد پر ایسے ہے جیسے چودھویں رات کے چاند کی فضیلت تمام ستاروں پر ہے اور بے شک علماء انبیاء کے وارث ہیں اور بے شک نہیں چھوڑتے دینار اور درہم کو لیکن وہ وارث بناتے ہیں علم کا جس نے علم کو حاصل کیا اس نے بڑا وافر حصہ حاصل کیا۔ اسی طرح کہا ہے اس کو عبد الرزاق نے ابن مبارک سے انہوں نے اوزاعی سے اور کہا ہے بشر بن بکر نے اوزاعی سے عبد السلام بن سلیم سے انہوں نے یزید بن سمرہ سے انہوں نے کثیر بن قیس سے انہوں نے ابو درداء سے اور یہ زیادہ صحیح ہے بخاری نے اسی کو کہا ہے۔"],[1655,"ہمیں خبر دی ہے ابو زکریا بن ابو اسحاق مزکی نے ان کو ابو عمرہ عبد الملک بن حسن یوسف سقطی معدل نے ان کو احمد بن یحییٰ حلوانی نے ان کو ابراہیم بن حمزہ نے ان کو حاتم بن اسماعیل نے ان کو حمید بن صخر نے ان کو ابو سعید مقبری نے ان کو ابو ہریرہ رضی اللہ عنہ نے وہ کہتے ہیں کہ میں نے سنا رسول اللہ صلی اللہ علیہ وسلم سے وہ فرماتے تھے۔ جو شخص میری اس مسجد میں آئے وہ محض کسی چیز کو سیکھنے یا سکھلانے کے لئے آئے وہ شخص بمنزلہ مجاہد فی سبیل اللہ کے ہے اور جو شخص اس کے ماسوا کے لئے آئے وہ بمنزلہ اس شخص کے ہے جو دوسرے کے مبتاع اور سامان پر نظر رکھتا ہے۔ اور یہ روایت کی گئی ہے عثمان بن ابو سودہ سے اس نے سیدنا ابو درداء سے۔"],[1656,"§طالب علم جنت کا دروازہ کھلا ہوتا ہے\nہمیں خبر دی ہے ابو نصر بن قتادہ نے ان کو ابو عمرو بن مطر نے ان کو جعفر بن محمد فریابی نے ان کو صفورک بن صالح نے ان کو ولید بن مسلم نے ان کو خالد بن یزید بن ابی مالک نے ان کو عثمان بن ایمن نے ابو درداء رضی اللہ تعالیٰ عنہ نے کہتے ہیں انہوں نے سنا رسول اللہ فرماتے جو شخص اس طرح صبح کرتا ہے کہ علم کا ارادہ کرتا ہے کہ وہ اسے اللہ کی رضا کے لئے سیکھے گا اللہ تعالیٰ اس کے لئے جنت کی طرف ایک دروازہ کھول دیتے ہیں۔ اور فرشتے اس کے لئے اس کے اطراف کو سمیٹ دیتے ہیں اور اس پر آسمانوں کے فرشتے مغفرت کی دعا کرتے ہیں اور مچھلیاں سمندر میں اور عالم کے لئے عابد پر فضیلت ہے جیسے چودھویں کے چاند کو آسمان کے سب سے چھوٹے ستارے پر اور علماء انبیاء کے وارث ہیں انبیاء نہیں وارث بناتے دینار یا درہم کا لیکن وہ تو وارث بناتے ہیں علم کا جس نے علم حاصل کیا اس نے انبیاء کا ورثہ حاصل کیا اور موت پہنچنے والی ہے جس کا چیز نقصان نہیں ہے اور ایسا رخنہ ہے جو بند نہیں ہوتا اور ستارہ ہے مٹا ہوا، پورے قبیلے کی موت ایک عالم کی موت سے آسان ہے۔"],[1657,"ہمیں خبر دی ہے ابو الحسین محمد بن حسین علوی نے ان کو ابو الاحرز محمد بن عمر بن جمیل ازدی نے ان کو محمد بن احمد بن نصر ترمذی نے بغداد میں ان کو حسین بن ابو سری محمد بن ابو سری کے بھائی نے ان کو عبد القدوس بن حجاج ابو المغیرہ خولانی نے ان کو محمد بن ولید زبیری نے زہری نے عروۃ سے انہوں نے عائشہ رضی اللہ عنہا سے وہ کہتے ہیں کہ رسول اللہ نے فرمایا کہ بے شک فرشتے اپنے پروں کو پھیلا دیتے ہیں طالب علم\n(۱۶۹۸) أخرجه ابن ماجة (۲۲۷) عن أبي بكر بن أبي شيبة عن حاتم بن إسماعيل به. وقال البوصيري في الزوائد: إسناده صحيح على شرط مسلم. وأخرجه أبو داود (۳۶۴۲) من طريق عثمان بن أبي سودة به.\n(۱) في الأصل سويد.\n(۱۶۹۹) أخرجه ابن عبد البر في الجامع (۳۷/۱) من طريق الوليد بن مسلم به.\nکے لئے۔"],[1658,"ہمیں خبر دی ہے ابو طاہر فقیہ نے ان کو ابو حامد بن بلال نے ان کو احمد بن منصور مروزی نے ان کو نضر بن شمیل نے ان کو ابن سیرین نے ان کو ابو ہریرہ نے کہتے ہیں کہ رسول اللہ نے فرمایا لوگ کانیں ہیں ان میں سے جو جاہلیت میں اعلیٰ و ارفع ہیں بشرط یہ کہ جب وہ دین میں سمجھ بوجھ حاصل کر لیں۔ ابن عون نے ان کی مخالفت کی ہے اور اس روایت کو موقوف بیان کیا۔"],[1659,"اور ہم نے روایت کی ہے اس ثابت کی حدیث میں معاویہ بن ابو سفیان سے کہ انہوں نے سنا نبی کریم صلی اللہ علیہ وسلم فرما رہے تھے۔ اللہ تعالیٰ جس کے ساتھ بھلائی چاہتے ہیں اس کو دین کی سمجھ عطا کرتے ہیں۔"],[1660,"اور سیدنا ابن مسعود اور حذیفہ سے اور نبی کریم صلی اللہ علیہ وسلم سے روایت گذر چکی ہے۔ کہ علم کا فضل مجھے زیادہ محبوب ہے یا یوں فرمایا تھا کہ علم کا زیادہ ہونا میرے نزدیک عبادت کے زیادہ ہونے سے زیادہ بہتر ہے اور تمہارا بہتر دین پرہیزگاری ہے۔"],[1661,"اور ہم نے روایت کیا ہے اس کو باعتبار صحیح کے مطرف بن عبد اللہ بن شخیر کے قول سے۔"],[1662,"اور ہم اس کو روایت کیا ہے عبد اللہ بن عمرو سے انہوں نے سنا نبی کریم صلی اللہ علیہ وسلم سے وہ فرماتے تھے قلیل فقہ بہتر ہے کثیر عبادت سے اور کافی ہے مرد کیلئے فقہ باعتبار عبادت کے۔"],[1663,"اور ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو العباس محمد بن یعقوب نے ان کو محمد بن عبید اللہ منادی نے ان کو یونس بن محمد نے ان کو حماد نے قتادہ سے ان کو مطرف نے انہوں نے فرمایا کہ علم کا اضافہ افضل ہے عبادت کے اضافے سے اور تمہارا اچھا دین پرہیزگاری ہے۔"],[1664,"اور ہم نے روایت کیا ہے مسئلہ شفاعت میں کتاب البعث سے سیدنا عثمان بن عفان سے مرفوعا کہ قیامت کے دن انبیاء شفاعت کریں گے اس کے بعد علماء اس کے بعد شہداء اور احادیث علم کی فضیلت کی بابت اور اہل علم کی فضیلت کی بابت کثیر ہیں ہم نے ان کو کتاب المدخل کے آخر میں ذکر کیا ہے جو شخص ان کی تفصیل چاہے وہاں رجوع کرے اللہ کی توفیق کے ساتھ۔"],[1665,"§الدنیا ملعون\nاور ہمیں خبر دی ہے ابو عبد اللہ محمد بن احمد بن ابو طاہر دقاق نے بغداد میں ان کو احمد بن سلیمان فقیہ نے ان کو ہلال بن عراقی نے ان کو علی بن میمون رقی عطار نے ان کو ابو خلید مشقی نے ان کو ابن ثوبان نے ان کو ان کے والد نے ان کو عطاء بن قرہ نے ان کو عبد اللہ بن ضمرہ سلولی نے ان کو ابو ہریرہ رضی اللہ عنہ نے کہتے ہیں کہ میں نے سنا رسول اللہ صلی اللہ علیہ وسلم سے فرماتے تھے۔ دنیا ملعون ہے جو کچھ اس میں ہے وہ بھی ملعون ہے مگر ذکر اللہ اور عالم اور متعلم۔"],[1666,"ہمیں خبر دی ابو الحسن بن ابو علی سقا نے ان کو ابو سہل بن زیاد قطان نے ان کو احمد بن یحییٰ حلوانی نے ان کو عبید بن جناد نے ان کو عطاء ابو علی بن یحییٰ بن مسلم خفاف نے ان کو خالد حذاء نے ان کو عبد الرحمن بن ابی بکرہ نے ان کو ان کے والد نے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے آپ نے فرمایا آپ اس طرح صبح کیجئے کہ یا تو آپ عالم ہوں یا متعلم ہوں یا سنے والے ہوں یا محبت ہوں اور پانچویں نہ ہونا (بلکہ مذکورہ چار میں سے ایک\n(۱۷۰۱) أخرجه أحمد (۲۶۰/۲ و ۲۹۸) من طريق أبي سلمة و (۳۹۱/۲) من طريق أبي علقمة وعن أبي هريرة.\n(۱۷۰۲) متفق عليه. أخرجه البخاري (۲۷/۱) ومسلم (۷۱۸/۲).\n(۱۷۰۷) أخرجه ابن ماجة (۴۳۱۳).\n(۱۷۰۸) أخرجه الترمذي (۲۳۲۲) وابن ماجة (۴۱۱۲) من طريق ابن ثوبان عن عطاء بن قرة به.\nہونا ورنہ آپ ہلاک ہو جائیں گے۔ اس ہاتھوں میں نہیں تھا۔ سوائے اس کے نہیں کہ تھا ہمارے ہاتھوں میں صبح کر تو عالم یا متعلم یا مستمع چوتھا نہ ہونا ورنہ ہلاک ہو جاؤ گے۔ اے عطاء ہلاکت ہے اس شخص کے لئے جس میں مذکورہ صفات میں سے ایک بھی نہیں ہے۔ عبید بن جناد نے کہا کہ عطاء کہتے ہیں کہ مشعر بن کذام نے کہا اے عطاء یہ پانچویں چیز ہے اللہ ہمیں زیادہ کر ان سے"],[1667,"ہمیں خبر دی ہے ابو الحسن علی بن عبد اللہ خسرو جردی نے ان کو ابو بکر اسماعیل نے ان کو حسن بن علی بن سلیمان قطان نے ان کو عبید بن حماد حلبی نے پھر اس کو ذکر کیا ہے اپنی اسناد کے ساتھ علاوہ اس کے انہوں نے آخر میں اے عطاء ہلاکت ہے اس شخص کے لئے جن میں مذکورہ صفات میں سے کوئی ایک بھی نہ ہو اس روایت میں عطاء خفاف متفرد ہے اور یہ مروی ہے سیدنا عبد اللہ بن مسعود سے اور سیدنا ابو درداء سے دونوں کے قول سے اور ابو درداء کی حدیث میں متبعا کے الفاظ میں مستمعاً کی جگہ"],[1668,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو علی حامد بن محمد خانے ان کو محمد صالح انج نے ان کو عیسیٰ بن زیاد دورفی نے ان کو مسلمہ بن قعنب نے ان کو نافع نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے وہ فرماتے ہیں کہ رسول اللہ نے فرمایا: دین میں فہم حاصل کرنے سے زیادہ افضل کسی شے کی عبادت اللہ کے لئے نہیں ہو سکتی۔ عیسیٰ بن زیاد اس اسناد کے ساتھ منفرد ہے۔ اور ایک دوسرے ضعیف طریق سے بھی یہ حدیث مروی ہے اور یہی لفظ قول زہری سے محفوظ ہیں۔"],[1669,"ہمیں خبر دی ہے ابو منصور عبد القاہر بن طاہر امام فقیہ نے ان کو ابو العباس احمد بن محمد نے محمد عمروی نے بطور املا کے ان کو محمد بن مسیب ارغیانی نے ان کو محمد بن یزید بن حکم نے ان کو یزید بن ہارون نے یزید بن عیاض سے انہوں نے صفوان بن سلیم سے اس سے سلیمان بن یسار سے اس نے ابو ہریرہ سے اس نے نبی کریم صلی اللہ علیہ وسلم سے کہ آپ نے فرمایا دین میں فہم حاصل کرنے سے زیادہ افضل کسی شئی کی عبادت اللہ تعالیٰ کے لئے نہیں ہو سکتی اور البتہ ایک فقیہ شیطان پر ایک ہزار عابد سے زیادہ سخت (اور بھاری) ہے۔ اور ہر دین کا ایک ستون ہوتا ہے دین کا ستون فقیہ ہے۔ اور سیدنا ابو ہریرہ نے فرمایا البتہ اگر میں ایک لحظہ دین کی سمجھ حاصل کرنے کے لئے بیٹھ جاؤں یہ مجھے رات بھر صبح تک شب بیداری کرنے سے زیادہ محبوب ہے۔"],[1670,"کہتے ہیں اور ہمیں حدیث بیان کی ہے محمد بن مسیب بن عقبہ نے ان کو محمد بن یحییٰ بن ابو حاتم ازدی نے ان کو یزید بن ہارون نے ان کو یزید بن عیاض نے ان کو صفوان بن سلیم نے ان کو عطاء بن یسار نے ان کو ابو ہریرہ نے فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا مذکورہ روایت مگر یزید بن عیاض ضعیف فی الحدیث ہے۔ واللہ اعلم۔\n(۱۷۰۹) أخرجه الطبراني في الصغير (۹/۲) من طريق عبيد بن جناد به. وقال الهيثمي في المجمع (۱۲۲/۱) رواه الطبراني في الثلاثة والبزار ورجاله موثقون اه. وقال الطبراني: لم يروه عن خالد العطاء ولم يروه أيضاً عن مسعر إلا عطاء تفرد به عبيد بن جناد.\n(۱۷۱۲) أخرجه الدارقطني (۷۹/۳) من طريق يزيد بن هارون به."],[1671,"§ابلیس کی خوشی عالم کی موت پر\nہمیں خبر دی ہے ابو محمد عبد اللہ بن یوسف نے ان کو مروان قاضی نے مدینہ الرسول میں ان کو سلیمان بن داؤد طوسی نے ان کو رفاعی نے ان کو ابو بکر بن عیاش نے ان کو سعید اسکاف نے ان کو معروف بن خربوذ نے ان کو ابو جعفر نے انہوں نے کہا کہ ایک عالم کی موت ابلیس کے نزدیک ستر عابد کی موت سے زیادہ پسندیدہ ہوتی ہے۔"],[1672,"ہمیں خبر دی ابو عبد اللہ حافظ نے اور ابو بکر بن حسین نے دونوں کو ابو العباس محمد بن یعقوب نے ان کو یزید بن محمد نے ان کو عبد الصمد ثقفی نے ان کو ہشام بن عمار نے ان کو ولید نے ان کو ابو سعد روح بن جناح نے ان کو مجاہد نے سمع بن عباس نے وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ایک فقیہ (دین کی سمجھ بوجھ رکھنے والا عالم) شیطان پر ایک ہزار عبادت گزار سے بھاری ہوتا ہے۔ روح بن جناح اس روایت کرنے میں متفرد ہے۔"],[1673,"ہمیں خبر دی ابو سعید مالینی نے ان کو ابو احمد بن عدی حافظ نے ان کو محمد بن سعید بن مہران نے ان کو شیبان نے ان کو ابو ربیع سمان نے ان کو ابو الزناد نے ان کو اعرج نے ان کو ابو ہریرہ وہ کہتے ہیں کہ رسول اللہ نے فرمایا ہر چیز کا ایک سہارا یا ستون ہوتا ہے اور اسلام کا ستون دین میں سمجھ بوجھ حاصل کرنا ہے اور البتہ ایک فقیہ (دین کی سمجھ رکھنے والا عالم) شیطان پر ہزار عابد سے زیادہ سخت ہوتا ہے ابو ربیع ابو الزناد سے اس روایت میں متفرد ہے۔"],[1674,"§عالم سے سفارش کا کہا جائے گا\nاور ہمیں خبر دی ہے ابو سعد نے ان کو ابو احمد بن عدی نے ان کو احمد بن محمد بن عنبہ نے ان کو کثیر بن عبید نجی نے ان کو بقیہ نے ان کو مقاتل بن سلیمان نے وہ کہتے ہیں مجھے حدیث بیان کی ہے ابو زبیر نے اور شرحبیل بن سعید نے ان کو جابر بن عبد اللہ نے وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا عالم اور عابد دونوں قیامت میں اٹھائے جائیں گے اور عابد سے کہا جائے گا کہ آپ جنت میں داخل ہو جائیے اور عالم سے کہا جائے گا آپ ٹھہر جائیے پہلے آپ لوگوں کے لئے شفاعت کر لیجئے جن کو آپ نے بہتر ادب سکھایا تھا۔ مقاتل بن سلیمان کا اس حدیث میں تفرد ہے۔"],[1675,"ان روایات میں سے ہے جن کے ساتھ مجھے اجازت دی تھی ابو عبد اللہ نے اور اس میں اجازت دی تھی ابو العباس اصم سے ان کو\n(۱۷۱۳) تذكرة الموضوعات للفتني (ص ۲۱۶).\n(۱۷۱۵) أخرجه الترمذي (۲۶۸۱) عن محمد بن إسماعيل عن إبراهيم بن موسى عن الوليد بن مسلم به. وأخرجه ابن ماجة (۲۲۲) عن هشام بن عمار به. وقال الترمذي: هذا حديث غريب ولا نعرفه إلا من هذا الوجه من حديث الوليد بن مسلم.\n(۱۷۱۶) أخرجه المصنف من طريق ابن عدي (۳۶۹/۱). وقال ابن عدي: وهذا الحديث لا أعلم رواه عن أبي الزناد غير أبي الربيع السمان.\n(۱۷۱۷) أخرجه المصنف من طريق ابن عدي (۲۴۳۰/۶) في ترجمة مقاتل بن سليمان أبو الحسن الأزدي.\n(۱۷۱۸) عزاه ابن حجر في الفتح (۴۱/۱۳) إلى يعقوب بن شيبة من طريق الحارث بن حصيرة عن زيد بن وهب عن ابن مسعود ومن طريق أبي إسحاق عن أبي الأحوص عن ابن مسعود.\n(۱) غير واضح في الأصل.\nیحییٰ بن ابو طالب نے ان کو شجاع بن ولید نے ان کو ابو خثیمہ نے ان کو ابو اسحاق نے ہبیرہ بن مریم اور ابو الاحوص سے کہتے ہیں کہ انہوں نے فرمایا نہیں آتا کوئی سال مگر جو اس کے بعد آئے گا وہ پہلے سے برا ہوتا ہے۔ لوگوں نے کہا بے شک ہم ایسے ہیں کہ ہمارے اوپر ایک سال خوشحالی کا آتا ہے اور کوئی سال قحط کا سیدنا ابن مسعود اللہ کی قسم یہ تمہارے قحط اور خوشحال سال کو مراد نہیں لیا مگر مراد تو علم اور علماء کا فقدان ہے تحقیق تمہارے گذشتہ سالوں میں عمر رضی اللہ عنہ تھے اب تم مجھے اس جیسے دکھاؤ۔ یا یہ مراد ہے کہ جو تمہاری گذشتہ سالوں والی زندگی تھی اب وہ کہاں ہے مجھے وہ دکھلاؤ ذرا؟"],[1676,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو جعفر محمد بن سلیمان منصور نے ان کو زکریا بن یحییٰ بن حارث نے ان کو ایوب بن حسن نے ان کو حجاج بن مسلم نے ان کو ابن مبارک نے ان کو ہشام بن حسان نے حسن سے وہ کہتے ہیں کہ سیدنا ابن مسعود نے فرمایا: کہ عالم کی موت ایک ایسا فتنہ ہے جسے کوئی شئی نہیں روک سکتی۔ دوسری تعبیر یہ ہے کہ عالم کی موت ایک ایسا خلا ہوتا ہے جو پر نہیں کیا جا سکتا جب تک اختلاف شب و روز باقی ہے (یعنی قیامت تک خلا پر نہیں ہو سکتا، حجاج بن مسلم وہ ابو مسلم صاحب صحیح ہیں۔\nبہترین عالم کون ہے؟"],[1677,"ہمیں خبر دی ہے ابو محمد عبد اللہ بن یوسف اصفہانی نے ان کو ابو رجاء بغدادی نے مکہ مکرمہ میں ان کو یوسف بن بحر نے مقام جبلہ میں ان کو محمد بن سعید بن سابق نے ان کو مروان بن جناح نے کہ انہوں نے اس کو حدیث بیان کی میسرہ بن علیس سے یہ کہ سیدنا ابو درداء نے فرمایا کہ تم لوگ علم سیکھو اس وقت سے پہلے کہ تمہاری طرف لوگوں کو علم کے لئے احتیاجی ہو بے شک سب لوگوں میں سے عابد ترین شخص وہ عالم ہے جس کی طرف لوگوں کو احتیاجی ہو اور وہ لوگوں کو اپنے علم کے ساتھ نفع دے اور اگر لوگوں کو اس کی ضرورت نہ پڑے تو علم کے ساتھ اپنے نفس کو نفع دے جو اللہ نے اس کو علم عطا کیا ہے۔ کیا حال ہو گا تمہارے علماء ختم ہو جا رہے ہیں۔ اور تمہارے اہل علم حاصل نہیں کر رہے، اگر عالم اپنے علم کو بڑھانا چاہے تو علم کو بڑھا سکتا ہے۔ علم کسی شئی کو کم نہیں کرتا۔ اگر بے علم انسان علم حاصل کرنا چاہے تو وہ علم حاصل کر سکتا ہے۔"],[1678,"ہمیں خبر دی ہے ابو سعید بن محمد موسیٰ نے ان کو ابو العباس رحم نے ان کو یوسف بن عبید خوارزمی نے ان کو محمد بن روح نے ان کو ایوب بن سلیمان ثقفی نے ان کو ولید بن شجاع نے ان کو خضرار بن عمرو نے ان کو قتادہ نے ان کو ابو ہریرہ رضی اللہ عنہ نے وہ فرماتے ہیں۔ اگر میں علم کی طلب میں کسی قدر نکل جاؤں جس سے میں اپنے اصلاح کا ارادہ کروں اور ان کی اصلاح کا جن کی طرف میں واپس لوٹ کر آؤں تو میرے نزدیک یہ چیز سال بھر روزے رکھنے سے زیادہ محبوب ہے اور سال بھر عبادت کرنے سے زیادہ محبوب ہے اس لئے کہ شیطان نے ابن آدم سے کہا کاش کہ تو عمل کرتا پس تم نے نہ جانا چنانچہ اس نے اسے حصول علم سے روک دیا۔ اگر کسی کو اس کا علم پورا ہوتا تو موسیٰ کلیم اللہ علیہ السلام کو پورا ہوتا۔ حالانکہ ان کے پاس علم کی الواح اور تختیاں تھیں ان میں ہر چیز کی تفصیل تھی۔ مگر انہوں نے (حضرت خضر سے حصول علم کے لئے کہا تھا۔) هل اتبعك على ان تعلمني مما علمت رشدا. کیا میں آپ کے پیچھے پیچھے اس شرط کے ساتھ چلوں کہ آپ مجھے وہ علم سکھلائیں جو رشد و ہدایت آپ سکھلائے گئے ہیں۔"],[1679,"ہمیں خبر دی ہے ابو جعفر مستملی نے ان کو محمد بن جعفر بن محمد بن مطر نے ان کو فضل بن حباب نے جمحی نے بطور املا کے ان کو سلیمان\n(۱۷۲۲) أخرجه أحمد (۵۰۸/۲) عن يزيد عن حماد بن سلمة به. وقال الهيثمي في المجمع (۱۲۸/۱) رواه أبو يعلى وفيه علي بن زيد وهو ضعيف واختلف في الاحتجاج.\nبن حرب نے ان کو حماد بن سلمہ نے ان کو علی بن زید نے ان کو اوس بن خالد نے ان کو ابو ہریرہ نے وہ کہتے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اس شخص کی مثال جو حکمت کو سنتا ہے اور اس سے شر ہی حاصل کرتا ہے مثل اس شخص کے ہے جو کسی چرواہے کے پاس آئے میاں! مجھے ایک بکری بکریوں میں سے دے دو۔ وہ یہ کہے کہ جاؤ کسی بکری کو کان سے پکڑ کر لے جاؤ وہ جائے اور جا کر بکریوں کے کتے کو کان سے پکڑ لے۔"],[1680,"اور ہمیں خبر دی ہے جعفر مستملی نے ان کو محمد بن احمد بن سنان نحوی نے ان کو حسن بن سفیان نے ان کو حمید بن زنجویہ نے ان کو عثمان بن صالح نے ان کو ابن لہیعہ نے ان کو عطاء نے کہتے کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا تم لوگ آپس میں ایک دوسرے کے ناموں کو اس قدر جانو جن کے ساتھ تم اپنے رشتوں کو ملا سکو اس کے بعد رک جاؤ۔ یا تم لوگ اس قدر عربی زبان سیکھو جس کے ساتھ کتاب اللہ کو سمجھ سکو اس کے بعد رک جاؤ اور ستاروں کے بارے میں اس قدر سیکھو جس کے ساتھ تم بر و بحر کی تاریکیوں میں راستہ ڈھونڈ سکو اس کے بعد رک جاؤ۔"],[1681,"ہمیں خبر دی ہے علی بن احمد بن عبدان نے ان کو احمد بن عبید نے ان کو محمد بن خلف مروزی نے ان کو احمد یونس نے ان کو ابو بکر عیاش نے وہ کہتے ہیں کہ میں نے اکثر حدیث رسول نزدیک (فلاں شخص کے) انصار میں سے پائی میں ان میں سے ایک شخص کے پاس آتا تھا۔ پس مجھ سے کہا گیا کہ وہ سو رہے ہیں اگر میں چاہوں تو میرے لئے انہیں بیدار کر لیا جائے۔ میرے لئے بیدار کر لیا جاتا میں بیٹھتا حتی کہ وہ شخص نکلتا البتہ استنباط کرتا اس کے ساتھ اپنی حدیث۔"],[1682,"§چہل حدیث کی فضیلت\nہمیں خبر دی ابو سعد مالینی ان کو ابو احمد بن عدی نے ان کو ابو یعلیٰ نے ان کو عمرو بن حصین نے ان کو ابن علاثہ نے ان کو خصیف بن مجاہد نے ان کو ابو ہریرہ نے وہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جو شخص میری امت میں سے چالیس حدیثیں یاد کرے گا جو انہیں ان کے دین میں فائدہ دیں اللہ تعالیٰ اس کو قیامت کے دن علماء میں سے اٹھائیں گے اور عالم کی فضیلت عابد پر ستر درجہ ہے اور ہر دو درجوں کے درمیان کتنا فاصلہ ہے اسے اللہ تعالیٰ جانتا ہے۔"],[1683,"ہمیں خبر دی ہے ابو الحسن محمد بن یعقوب فقیہ نے ان کو ابو الحسن محمد بن علی بن حبیش نے ان کو میرے چچا احمد بن حبیش نے ان کو ہارون بن عمرہ نے (ح) اور ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے ان کو ابو عبد اللہ محمد بن عبد اللہ صفار نے ان کو ابراہیم بن اسماعیل سیوطی نے ان کو عمرو بن محمد صاحب یعلیٰ بن اشدق نے ان کو عبد الملک بن ہارون بن عنترہ نے ان کو ان کے والد نے ان کو ان کے دادا سیدنا ابو درداء رضی اللہ تعالیٰ عنہ نے کہ حضور صلی اللہ علیہ وسلم سے سوال کیا گیا کہ علم کی حد کیا ہے کہ جس وقت آدمی حفاظت کرے گو وہ فقیہ ہو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جو شخص میری امت میں سے چالیس حدیثیں یاد کرے اپنے دین کے بارے میں اللہ تعالیٰ اسے فقیہ اٹھائیں گے اور میں قیامت کے دن اس کا شفاعت کرنے والا اور گواہ ہوں گا۔"],[1684,"ہمیں خبر دی علی بن احمد بن عبدان نے ان کو احمد بن عبید نے ان کو محمد بن بشر عطار نے ان کو ہاشم بن ولید ابو طالب ہروی نے ان کو\n(۱) غير واضح في الأصل.\n(۱۷۲۵) أخرجه ابن عدي (۱۷۹۹/۵) عن أحمد بن علي بن المثنى أبو يعلى به.\n(۱۷۲۶) أخرجه الشيرازي في الألقاب وابن حبان في الضعفاء وأبو بكر في الغيلانيات والبيهقي والسلفي وابن النجار (الكنز ۲۹۱۴).\n(۱۷۲۷) أخرجه ابن حبان في الضعفاء (۱۳۳/۲) عن إبراهيم بن أبي أمية بطرسوس عن أبي طالب هاشم بن الوليد الهروي به. = عبد الملک بن ہارون بن عنتر نے پھر اس نے مذکورہ کو مثل حدیث ذکر کی علاوہ اس کے کہ اس نے کہا کہ میں نے سوال کیا اس کے لئے سفارشی اور گواہ ہوں گا۔ یہ لوگوں کے مابین مشہور ہے مگر اس کی اسناد نہیں ہے۔"],[1685,"ہمیں خبر دی ہے عبد اللہ بن یوسف نے ان کو ابو نصر احمد بن سہل فقیہ نے بطور املا کے بخاری میں ان کو جعفر بن شعیب شاشی نے ان کو ابو طالب ہروی نے ان کو عمرو بن ہارون بن ضحاک نے ان کو عثمان اسدی نے عوف بن عبد اللہ سے ان کو عقبہ نے کہتے ہیں سیدنا عبد اللہ بن مسعود نے کہا بے شک لوگوں کی ہدایت اس کے عالم پڑوس میں ہے اور اس کے اپنے اہل بیت میں ہے اور سوائے اس کے نہیں کہ عالم کی مثال اس کے پڑوس اور اس کے اہل بیت میں ان کے درمیان ایک کنویں جیسی ہے جب انہیں ضرورت پڑتی ہے اس سے پانی پی لیتے ہیں۔ وہ اسی حال میں ہوتے ہیں کہ اچانک جب وہ صبح کرتے ہیں اور اس کا پانی خشک ہو چکا ہو۔"],[1686,"ہمیں خبر دی ہے ابو محمد بن یوسف نے ان کو عبد اللہ جرجانی ان کو ابو العباس شیبانی نے ان کو ابو نعیم عبید بن ہشام حلبی نے ان کو اصح بن محمد اتی نے ان کو کلثوم بن جوشن قیشری نے ان کو عبد اللہ بن ابی عیزار نے کہتے ہیں کہ سیدنا عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ جب کسی جوان کو دیکھتے جو علم طلب کر رہے ہوتے تو فرماتے تمہیں خوش آمدید ہو حکمت کے چشموں اور اندھیروں کے چراغوں اور پرانے لباسوں اور جدید قلوب والوں کو۔"],[1687,"ہمیں خبر دی ہے ابو حازم عموری حافظ نے کہتے ہیں کہ میں نے سنا ابراہیم بن عبد الاعلیٰ سے کہتے تھے میں نے سنا معتمر بن سلیمان سے کہتے تھے میرے والد نے مجھے اس وقت لکھا جب میں کوفہ میں تھا اے بیٹے صحیفوں میں دیکھو اور علم کو لکھو بے شک مال فنا ہو جائے گا اور علم باقی رہے گا۔"],[1688,"§علم کے لئے چار چیزیں ضروری ہیں\nہمیں خبر دی ابو عبد اللہ حافظ نے کہتے ہیں کہ میں نے سنا ابو الحسن محمد بن علی بن بکر عدل سے کیا آپ نے ابراہیم بن محمد بن ہانی کو دیکھا ہے وہ کہتے تھے کہ میں نے اپنے دادا سے سنا وہ کہتے تھے کہ میں نے عبدان بن عثمان کو کہتے ہوئے سنا کہ ابن مبارک نے کہا تھا۔ علم چار چیزوں کے بغیر طلب نہیں کیا جاتا۔"],[1689,"اور ہمیں خبر دی ہے ابو حازم حافظ نے ان کو ابو علی حسین بن احمد ماسرجسی نے ان کو احمد بن محمد جیری نے ان کو ابراہیم بن محمد بن ہانی نے ان کو ابو محمد بن ہانی نے کہتے ہیں کہ میں نے سنا ابن مبارک سے وہ کہتے تھے کہ علم کی طلب چار چیزوں کے بغیر تمام نہیں ہوتی (۱) فرصت ہو۔ (۲) مال ہو (۳) یاد کرنا (۴) پرہیزگاری۔"],[1690,"ہمیں خبر دی ہے ابو حازم نے کہتے ہیں کہ میں نے سنا محمد بن یحییٰ بن زکریا شاشی سے انہوں نے سنا احمد بن محمد بن یاسین سے انہوں نے سنا محمد بن طالب سے وہ حکایت کرتے تھے حرملہ بن یحییٰ سے انہوں نے سنا شافعی رحمہ اللہ سے۔ وہ فرماتے تھے کہ اس علم دین کو کوئی شخص (چاپلوسی کے ساتھ) تحکم اور سینہ زوری زبردستی کے ساتھ اور نفس کے غلبے کے ساتھ طلب نہ کرے کہ کامیاب نہیں ہوگا۔ مگر وہ شخص جو اس کو طلب کرے اپنے نفس کو ذلیل کرنے، گذران اور زندگی کی تنگی اور علماء کی خدمت کرنے کے ساتھ وہ شخص علم دین حاصل کرنے میں کامیاب ہوگا۔"],[1691,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے انہوں نے سنا ابو الطیب محمد بن احمد ذہلی سے انہوں نے سنا مسدد بن قطن سے انہوں نے سنا\n(۱۷۲۹) أخرجه الديلمي (۶۵۰۱) عن ابن مسعود مرفوعاً.\nعلی بن حشرم سے کہتے تھے کہ میں نے حضرت وکیع کی خدمت میں حافظہ کی کمی کی شکایت کی، انہوں نے فرمایا۔ حافظہ کے لئے آپ مدد طلب کیجئے گناہوں کی کمی کرنے کے ساتھ۔"],[1692,"ہمیں خبر دی ہے۔ محمد بن عبد اللہ فارسی نے ان کو ابو الحسین محمد بن حسن بن ابراہیم بن قدامہ جند قرجی نے، وہ کہتے ہیں میں نے سنا ابو بکر محمد بن اسحاق بن خزیمہ سے وہ کہتے تھے میں نے سنا محمد بن رافع سے وہ کہتے تھے کہ حضرت سفیان بن عیینہ سے کہا گیا کہ آپ نے حافظہ کیسے اچھا اور بہتر کیا؟ فرمایا کہ ترک معاصی کے ذریعے۔ دوسری روایت میں میں حافظہ کیسے تازہ کروں؟ فرمایا ترک معاصی کے ساتھ۔ (1)","",{"k":"(1) ﴿ماكان المؤمنون لينفروا كافة فلولا نفر من كل فرقة منهم طائفة ليتفقهوا في الدين ولينذروا قومهم اذا رجعوا اليهم﴾ ’’تمام اہل ایمان کے لئے تو ممکن نہیں ہے ہو سکتا کہ وہ سارے جا کر (علم دین میں مہارت پیدا کریں) (پھر ایسا کیوں نہیں کرتے کہ) کہ ہر بڑی جماعت سے ایک مختصر جماعت جائیں اور جا کر دین میں خوب سمجھ حاصل کریں اور واپس آکر اپنی پوری قوم کو ڈرائیں تا کہ وہ بھی اللہ کی نافرمانی کرنے سے بچیں۔‘‘ اس آیت میں اللہ تعالیٰ نے واضح فرمایا ہے کہ جا کر دین کی تعلیم حاصل کر کے آنے والے جب واپس آئیں تو جو کچھ دین کا علم سیکھ کر آئے ہیں وہ ان لوگوں کو بتلائیں جو کچھ ان سے غائب رہ کر انہوں نے حاصل کیا ہے تا کہ دونوں فریق جو علم سیکھنے گئے اور جو نہیں جا سکے علم رکھنے اور جاننے میں شریک ہو سکیں (اس سے معلوم ہوا بتلانا ان پر لازم ہے اور علم لینا ان لوگوں کا حق ہے چھپانے کی اجازت نہیں ہے بلکہ چھپانا گناہ ہے۔ (مترجم) (۲) ارشاد باری تعالیٰ ہے۔ ﴿واذ أخذ الله ميثاق الذين اوتوا الكتاب لتبيننه للناس ولاتكتمونه فنبذوه وراء ظهورهم﴾ ’’(وہ وقت قابل ذکر ہے) جب اللہ تعالیٰ نے ان لوگوں کا پکا وعدہ لیا جو کتاب دیئے گئے ہیں کہ تم احکام کتاب کو ضرور بیان کرنا لوگوں کے لئے اور اسے تم مت چھپانا مگر انہوں نے (لوگوں کے سامنے بیان کرنے کی بجائے) اسے اپنی پیٹھ کے پیچھے پھینک دیا۔‘‘ اللہ تعالیٰ نے اس آیت میں ہمیں یہ خبر دی ہے کہ اللہ تعالیٰ نے ہر اس آدمی پر شرط رکھی تھی جس کو اس نے کتاب عطا کی تھی کہ وہ اس کو لوگوں کے لئے بیان کر دے اور بالکل نہ چھپائے تو اس سے یہ بات واضح ہوئی کہ علم دین علم دین رکھنے والوں پر محمول ہے اور لدا ہوا ہے اس شرط کے ساتھ کہ جو ان کے آگے آئے اس تک اس کو پہنچائیں اس شرط پر نہیں ہے کہ اس علم کا حاصل اس کے ساتھ منفرد رہے اور دوسروں سے الگ تھلگ رہ کر اس میں اضافہ کرتا ہے۔ چنانچہ ارشاد باری ہے۔ ﴿فاسئلوا اهل الذكر ان كنتم لاتعلمون﴾ ’’اہل علم سے پوچھو اگر تم نہیں جانتے ہو۔‘‘ اللہ تعالیٰ نے اس آیت میں ان لوگوں کو حکم دیا ہے جو نہیں جانتے کہ وہ جانے والے سے پوچھیں یعنی بے علم عالم سے پوچھیں تو گویا اسی طرح یہ آیت دلالت کرتی ہے کہ جب عالم سے پوچھا جائے وہ درست جواب دے اور بتلائے۔"}],[1693,"§ایمان کا اٹھارھواں شعبہ\n§علم کا پھیلانا، صاحب علم کے اہل خانہ کو اس سے منع نہیں کرنا چاہئے\n§کوئی شخص جب عالم کے پاس آئے (تو اس کی کیا ذمہ داری ہے؟)\nجو شخص کسی ایسے صاحب علم سے سوال کرے جس کے پاس اس چیز کا علم موجود ہو اور وہ سائل رہنمائی طلب کرے اور استفادہ کرنا چاہے تو صاحب علم پر واجب ہے کہ اس کو اس چیز کے بارے میں بتلائے، صاحب علم کو اس کے چھپانے کا اختیار نہیں ہے۔ استنباط کرنے کے امور میں کتمان سے نصوص میں کتمان کرنا زیادہ سخت گناہ ہے ارشاد باری تعالیٰ ہے۔\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے اور ابو عبد الرحمن سلمی نے ان دونوں کے ماسوا نے وہ سب کہتے ہیں کہ ہمیں خبر دی ہے ابو العباس محمد بن یعقوب نے ان کو ابو امیہ نے ان کو ابو داؤد طیالسی نے ان کو شعبہ نے ان کو عمر بن سلیمان نے ان کو عبد الرحمن بن ابان بن عثمان نے ان کو ان کے والد نے وہ کہتے ہیں کہ مروان ابو الحکم نے مجھے زید بن ثابت کی طرف بھیجا دو پہر کے وقت اور میں ان کے پاس چلا گیا تو انہوں نے ہم سے کہا کہ آپ دو پہر کے وقت ہمارے پاس تشریف لائے ہیں میں نے ان کو کہا کہ رسول اللہ صلی اللہ علیہ وسلم سے ہم نے ایک حدیث سنی تھی میں نے چاہا کہ وہ حدیث آپ سے سن لوں انہوں نے فرمایا وہ حدیث بیان کرو جنہیں ہم نے رسول اللہ سے سنا تھا انہوں نے فرمایا۔\nاللہ تعالیٰ اس آدمی کو ترو تازہ رکھے (خوش رکھے) جس نے ہم سے کوئی حدیث سنی اور اس کو آگے تک پہنچا دیا جیسے کہ اس نے اس حدیث کو سنا تھا کیونکہ بہت سے ایسے آدمی ہیں جو حدیث کو اس کی اصل حالت میں (آگے) پہنچانے والے ہیں لیکن خود فقیہ نہیں ہیں اور بہت سے حدیث کو پہنچانے والے ایسے ہیں جو خود فقیہ ہیں (اور جس کو پہنچاتے ہیں وہ فقیہ نہیں ہے)۔\nتین چیزیں چوری نہیں ہوتی\nتین چیزیں ایسی ہیں جن سے دھوکا نہیں ہوتا (۱) دائمی طور پر قلب مسلم (۲) اخلاص عمل اللہ کے لئے (۳) حکمرانوں کو نصیحت اور خیر خواہی کرنا ہے۔ اور مسلمانوں کی جماعت کے ساتھ لزوم اختیار کرنا ہے بے شک مسلمانوں کی دعوت ان کے پیچھے کو گھیر لیتی ہے۔ اور جس شخص کی نیت آخرت کی ہو تو اللہ تعالیٰ اس کو سارے معاملات کے لئے کافی ہو جائے گا۔ اور جس شخص کی نیت دنیا کی ہو تو اللہ اس کے کام کو منتشر اور منتشر کر دیتا ہے اس کی فقیری کو اس کے سامنے کر دیتا ہے اور دنیا اس کے پاس اتنی ہی آئے گی جتنی اس کے لئے مقدر ہو چکی ہوگی۔ (1)","",{"k":"(1) أخرجه المصنف في الأربعون الصغرى رقم (۱) من طريق أبي داود الطيالسي به. وأخرجه أبو داؤد (۳۶۶۰) والترمذي (۲۶۵۶) مختصراً."}],[1694,"ہمیں خبر دی ہے ابو امیہ نے ان کو عمر بن یونس یمامی نے ان کو جہنم نے ان کو عمر بن سلیمان نے ان کو عبد الرحمن بن ربان بن عثمان نے ان کو ان کے والد نے ان کو زید بن ثابت نے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کی مثل روایت کی ہے۔"],[1695,"ہمیں خبر دی ہے ابو الحسن علی بن محمد مقری نے ان کو حسن بن محمد بن اسحاق نے ان کو یوسف بن یعقوب نے ان کو سلیمان بن حرب نے ان کو حماد بن سلمہ نے ان کو سماک بن حرب نے ان کو عبد الرحمن نے ان کو عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا کہ اللہ تروتازہ رکھے (خوش رکھے) اس آدمی کو جس نے ہم سے کوئی چیز سنی پھر اس کو اس طرح پہنچا دیا جس طرح اس نے سنا تھا۔ کیونکہ کتنے ہی ایسے مبلغ ہیں جو خود فقیہ نہیں ہیں۔ (1)","",{"k":"(1) أخرجه المصنف في دلائل النبوة (۵۳۰/۶) بنفس الإسناد."}],[1696,"ہمیں خبر دی ہے ابو الحسن مقری نے ان کو حسن بن محمد نے ان کو یوسف نے ان کو محمد بن ابن بکر نے ان کو عبد الوہاب ثقفی نے ان کو ایوب نے ان کو محمد بن ابن ابی بکرۃ نے ان کو ان کے والد نے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی ہے آپ نے اپنے منی کے خطبے میں ارشاد فرمایا: خبردار تم میں سے جو موجود ہیں وہ ان تک اس پیغام کو ضرور بالضرور پہنچائیں جو یہاں موجود نہیں ہیں۔ شاید کہ وہ جن کو یہ پہنچائیں وہ اس پیغام کے لئے زیادہ محفوظ کرنے والے ہوں ان بعض سے جنہوں نے اس کو سنا ہے۔ بخاری مسلم نے اس کو نقل کیا ہے صحیح میں۔ (1)","",{"k":"(1) أخرجه البخاري (۲۶/۱) ومسلم (۱۳۰۵/۲، ۱۳۰۶) من طريق محمد سيرين."}],[1697,"ہمیں خبر دی ہے ابو محمد بن فراس نے مکہ مکرمہ میں ان کو ابو عبد اللہ بن ضحاک نے ان کو علی بن عبد العزیز نے ان کو احمد بن یونس نے ان کو ابو بکر بن عیاش نے ان کو اعمش نے ان کو عبد اللہ بن عبد اللہ نے ان کو سعید بن جبیر نے ان کو ابن عباس نے انہوں نے فرمایا: تم سنو اور تم سے ہر وہ شخص سنے گا جو تم سے سنے گا۔ دوسری تعبیر۔ تم سن رہے ہو (ہم سے) اور جو تم سے سنے گا ان میں سے بھی بعض کوئی سنے گا۔ (1)","",{"k":"(1) أخرجه أبو داود (۳۶۵۹) من طريق الأعمش به."}],[1698,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو سہل احمد بن محمد بن زیاد قطان نحوی نے ان کو محمد بن جہم سمری نے ان کو ہیثم بن خالد مقری نے ان کو یحییٰ بن متوکل باہلی نے ان کو محمد بن ذکوان ازدی نے ان کو ابو ہارون عبدی نے ان کو ابو سعید خدری رضی اللہ تعالیٰ عنہ نے وہ کہتے ہیں کہ خوش آمدید ہو مبارک ہو رسول اللہ صلی اللہ علیہ وسلم کی وصیت کے ساتھ ہم لوگوں کو رسول اللہ صلی اللہ علیہ وسلم نے وصیت فرمائی تھی کہ ہم تمہارے لئے مجلس میں وسعت کریں۔ اور ہم تمہیں حدیث سمجھائیں بے شک تم لوگ ہمارے خلیفہ ہو بعد میں پیچھے رہنے والے ہو۔ اور حدیث والے ہمارے بعد ہوں گے اور نوجوان کا بوسہ لیتے اور اسے کہتے تھے اسے بھیجے جب تم کسی چیز کے بارے میں شک کرو تو مجھ سے پوچھ لو یہاں تک تم یقین کر لو اگر آپ یقین کے ساتھ لوٹیں تو یہ میرے نزدیک اس سے زیادہ پسندیدہ ہے کہ آپ شک پر لوٹیں۔ امام بیہقی رحمتہ اللہ علیہ نے فرمایا۔ (1)","",{"k":"(1) أخرجه المصنف في المدخل (۶۲۴) من طريق محمد بن الجهم السمري به."}],[1699,"§علم سیکھو اور سکھاؤ\nاس کو روایت کیا ہے سعید بن ابی بن کعب بصری نے راشد حمانی سے روایت کیا ہے انہوں نے ابو سعید سے روایت کیا ہے۔ اسی کو روایت کیا ہے ابو بکر فارسی نے ان کو ابو الحق اصفہانی نے ان کو احمد بن فارس نے ان کو محمد بن اسماعیل بخاری نے ان کو محمد بن عقبہ سدوس نے انہوں نے فرمایا۔"],[1700,"ہمیں خبر دی ہے ابو علی روزباری نے ان کو ابو بکر بن داسہ نے ان کو ابو داؤد نے ان کو موسیٰ بن اسماعیل نے ان کو حماد نے ان کو علی بن حکم نے ان کو عطاء نے ان کو ابو ہریرہ رضی اللہ تعالیٰ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ہے کہ آپ نے فرمایا جس شخص علم کے بارے میں سوال کیا جائے (اور وہ جانتا ہو) پھر وہ اس کو چھپا لے قیامت کے دن اس کو آگ کی لگام چڑھائی جائے گی۔ (1)","",{"k":"(1) أخرجه أبو داود (۳۶۵۸) عن موسى بن إسماعيل به. وأخرجه الترمذي وابن ماجه (۲۶۱) وقال الترمذي حسن."}],[1701,"ہمیں خبر دی ہے علی بن حمشاد عدل نے ان کو بشر بن موسیٰ نے ان کو خلاد بن یحییٰ نے ان کو سفیان نے ان کو ابو ہارون عبدی نے پھر مذکورہ حدیث ذکر کی ہے۔ (1)","",{"k":"(1) هكذا في الأصل وباقي في الإسناد في المستدرك (۱۰۱/۱): عبد الوارث ثنا علي بن الحكم عن عطاء عن رجل عن أبي هريرة مرفوعاً."}],[1702,"§کتمان علم پر وعیدیں\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو بکر بن اسحاق نے ان کو علی بن حمشاد نے ان کو احمد بن عبد اللہ بن یونس نے ان کو ابن جریج نے وہ کہتے ہیں یہ اعمش تشریف لائے عطاء کے پاس اور اس سے ان کی حدیث کے بارے میں پوچھا چنانچہ اس نے بیان کی ہم نے ان سے کہا کہ آپ اس کو حدیث بیان کر رہے ہیں حالانکہ یہ تو عراقی ہے انہوں نے اس سے فرمایا کہ میں نے سیدنا ابو ہریرہ رضی اللہ عنہ اور وہ رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کرتے تھے۔ کہ آپ صلی اللہ علیہ وسلم نے فرمایا۔ جس شخص علم کے بارے میں دریافت کیا جائے وہ اس کو چھپا لے قیامت کے دن اس کو اس طرح لایا جائے گا کہ وہ آگ کی لگام چڑھایا ہوا ہوگا۔ (1)","",{"k":"(1) أخرجه الحاكم (۱۰۱/۱) من طريق أحمد بن عبد الله بن يونس به. وصححه الحاكم وقال الحاكم: ذاكرت شيخنا أبا علي الحافظ بهذا الباب ثم سألته هل يصح شيء من هذه الأسانيد عن عطاء فقال لا قلت لم قال لأن عطاء لم يسمعه من أبي هريرة."}],[1703,"ہمیں خبر دی ہے ابراہیم بن طہمان نے ان کو سماک نے ان کو عطاء بن ابی رباح نے مذکور کی مثل منصور مرفوع روایت کے۔ حمید اس روایت میں منفرد ہے اور وہ منکر الحدیث ہے۔"],[1704,"قتادہ نے عطاء سے انہوں نے ابو ہریرہ رضی اللہ تعالیٰ عنہ سے موقوف روایت کیا ہے۔"],[1705,"ہم نے روایت کیا ہے عبد اللہ بن عمرو اس نے نبی کریم صلی اللہ علیہ وسلم سے اور یہ سب بطرق مذکور ہیں کتاب المدخل میں۔"],[1706,"ہمیں خبر دی ہے ابو سعد مالینی نے ان کو ابو احمد بن عدی حافظ نے ان کو ابراہیم بن اسباط نے ان کو منصور بن مزاحم نے ان کو اسماعیل بن عیاش نے ان کو حمید بن ابو سوید نے ان کو عطاء بن ابی رباح نے ان کو سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا علم سکھلاؤ اور شدت نہ کرو بے شک معلم بہتر ہے شدت کرنے والے سے۔ دوسری تعبیر یہ ہے علم سکھلاؤ اور مغرور نہ بنو بے شک معلم مغرور سے بہتر ہے۔ (1)","",{"k":"(1) أخرجه المصنف في المدخل (۶۲۷) من طريق إسماعيل بن عياش."}],[1707,"ہمیں خبر دی ہے ابو محمد بن یوسف نے ان کو ابو سعد بن اعرابی نے ان کو حسن بن محمد زعفرانی نے ان کو اسماعیل بن علیہ نے ان کو ایوب نے ان کو مجاہد نے ان کو سیدنا علی رضی اللہ تعالیٰ عنہ نے وہ کہتے ہیں جب آیت نازل ہوئی ﴿فتول عنهم فما انت بملوم﴾ پس منہ پھیر لے تو ان سے اعراض کر لے پس آپ کے اوپر کوئی اعتراض نہیں ہے۔ اس آیت میں ہمیں بڑا غمگین اور فکر مند کر دیا اور ہم نے کہا کہ رسول اللہ کو حکم مل گیا ہے آپ ہم سے منہ پھیر لیں اور ہم سے اعراض برتیں۔ چنانچہ اس کے بعد یہ آیت نازل ہوئی۔\n﴿وذكر فان الذكرى تنفع المؤمنين﴾\n’’آپ نصیحت کیجئے بے شک نصیحت فائدہ دے گی مؤمنوں کو۔‘‘\nتو ہم نے سمجھ لیا کہ آپ ہم سے منہ پھیرنے والے نہیں ہیں۔"],[1708,"ہمیں خبر دی ہے ابو حازم عثمان بن احمد حافظ نے ان کو ابو الفضل احمد بن اسماعیل بن یحییٰ ازدی نے ان کو محمد بن احمد بن زہیر نے ان کو محمد بن اسماعیل بخاری نے ان کو علی بن عبد اللہ نے ان کو ایوب بن متوکل نے ان کو خلیل بن احمد نے وہ کہتے ہیں کہ میں نے ایک آدمی کو ایک حدیث سکھلائی پھر میں ان سے کچھ عرصے کے بعد ملا انہوں نے مجھے وہی حدیث سنائی میں نے کہا کہ آپ نے اس کو یاد کر لیا ہے۔ انہوں نے کہا کہ کیا میں بھلا سکتا ہوں میں نے ان کو فائدہ دیا۔"],[1709,"§خلیل بن احمد کی وضاحت\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو احمد بن فضل ادیب نے ہمدان میں ان کو صولی نے ان کو ابو العباس نے ان کو ابو عثمان مازنی نے ان کو ابو الحسین اخفش نے ان کو خلیل بن احمد نے وہ کہتے ہیں میں کئی طرح کے لوگوں سے ملتا ہوں: ❶ وہ آدمی جو مجھ سے زیادہ علم رکھتا ہو کہ وہ مجھے فائدہ دے گا۔ ❷ وہ آدمی جو میری مثل ہو وہ مجھ سے مذاکرہ کرے گا۔ ❸ وہ آدمی جو متعلم ہو یعنی مجھ سے کچھ سیکھے وہ میرے اجر و ثواب میں اضافے کا باعث بنے گا۔ ❹ وہ انسان جو مجھ سے دور ہے یا وہ یہ سوچتا ہے وہ مجھ سے اونچا ہے میں ایسے انسان کی طرف نظر اٹھا کر بھی نہیں دیکھتا۔ (1)","",{"k":"(1) أخرجه بنحوه ابن عبد البر في جامع البيان (۱۳۳/۱)."}],[1710,"ہمیں خبر دی ہے ابو حازم حافظ ابو عمرو بن مطر نے ان کو محمد بن منذر ہروی نے وہ کہتے ہیں کہ ہمیں حدیث بیان کی ہے محمود بن محمد حلبی نے ان کو ابو صالح فراء نے ان کو ابن مبارک نے ان کو یعقوب بن عطاء نے ان کو ان کے والد نے وہ کہتے ہیں کہ میرے والد نے کہا تم ٹھہر جاؤ بیٹا میں تم کو حدیث سناتا ہوں اس کے لئے تمہیں کچھ پیسے دینے ہوں گے۔"],[1711,"§لوگوں کے مزاج مختلف ہوتے ہیں\nہمیں حدیث بیان کی ہے ابو العباس اصم نے ان کو ربیع بن سلیمان نے ان کو اسد نے ان کو عدی بن فضل نے ان کو حبیب اعور نے ان کو ابو رجاء نے ان کو سلیمان نے وہ کہتے ہیں کہ لوگ تین طرح کے ہیں: ایک وہ آدمی جو حدیث کو سن کر محفوظ کر لیتا ہے وہ اس کو پہنچا دیتا ہے۔ دوسرا آدمی وہ ہے جس کو سنا جائے تو وہ اس کو قبول کر لیتا ہے لیکن یاد نہیں رکھ سکتا اور نہ ہی اس کی اشاعت کر سکتا ہے۔ تیسرا آدمی وہ ہے جس کو سنایا جائے نہ ہی محفوظ رکھ سکتا ہے اور نہ ہی اشاعت کر سکتا ہے تو علم ان تینوں میں سے صرف پہلے آدمی کے لئے ہے اس کے سوا نہیں۔ تم سن کر محفوظ کر لو اور اس کو عام کرو۔ تا کہ وہ جان لیں جن کو علم نہیں۔\nبے شک اس عالم کی مثال جو علم رکھتا ہے اس آدمی جیسی ہے جو چراغ راستے میں لئے کھڑا ہے جو بھی راستے پر گذرتا ہے اس سے روشنی حاصل کرتا ہے اور اس کے لئے برکت کی دعا کرتا ہے اور خیر کی۔ اور اس علم کی مثال جو اس کے ساتھ نصیحت نہ کی جائے خاموش بت جیسی ہے جو نہ کھاتا ہے نہ پیتا ہے اور اس حکمت و دانائی کی مثال جو بلند ہو جائے اس خزانے جیسی ہے جس کے ساتھ فائدہ نہ اٹھایا جائے۔"],[1712,"ہمیں حدیث بیان کی ہے محمد بن موسیٰ نے ان کو والد نے ان کو ابو العباس رحم نے ان کو یحییٰ بن ابی طالب نے ان کو عبد الوہاب نے ان کو سعید نے ان کو قتادہ نے وہ کہتے ہیں کہ حکمت و دانائی کے بارے میں کہا جاتا ہے کہ اس عالم کے لئے مبارک بادی ہے جو علم کے ساتھ بولتا ہے اور اس سننے والے کے لئے مبارک باد ہے جو باب محفوظ کرتا ہے۔"],[1713,"ہمیں خبر دی ہے ابو العباس اصم نے ان کو عبد اللہ بن احمد بن حنبل نے ان کو ان کے والد نے ان کو عبد الرزاق نے ان کو معمر نے وہ کہتے ہیں کہ دھرتی پر کوئی ایسا سامان نہیں جو اللہ کے نزدیک علم سے زیادہ قیمتی ہو۔"],[1714,"§علم کے لئے آفت جھوٹ ہے\nہمیں خبر دی ہے ابو بکر اسماعیل بن محمد ضریر نے ان کو ان کے والد نے ان کو بشر بن موسیٰ نے ان کو اصمعی نے ان کو علاء بن اسلم نے ان کو اوبہ بن عجاج نے وہ کہتے ہیں کہ میں نسابہ بکری کے پاس آیا انہوں نے مجھ سے کہا شاید تم ایسی قوم سے میرے پاس آئے ہو، ہو اگر میں ان کو حدیث بیان کروں تو وہ مجھ سے اس کو محفوظ نہیں کریں گے۔ میں نے کہا کہ مروہ کے دشمن کیا کیا ہیں؟ انہوں نے کہا بنو عمر برائی اور اس کے علاوہ اور بھی بہت ہیں انہوں نے کہا کہ علم کی آفت و ہلاکت جھوٹ ہے اس کی ناقدری نسیان ہے اور اس کی بربادی اس کو ان لوگوں میں عام کرنا ہے جو اس کے اہل نہیں۔"],[1715,"ہمیں خبر دی ہے عبد الخالق بن علی نے ان کو ابو الحسن علی بن احمد طفاحی نے ان کو فضیل بن عیاض نے وہ کہتے ہیں کہ میں اس آدمی کی مثال نہیں جانتا جو علم رکھتا ہو مگر بے عمل ہو۔"],[1716,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے ان کو ابو الحسین احمد بن محمد فقیہ نے ان کو ابو العباس بن عطا نے وہ کہتے ہیں کہ موعظہ اور نصیحت عوام کے لئے ہوتی ہے۔ عالم کے لئے ہوتی ہے وہ جس کے ذریعے نصیحت کرے گا گویا کہ عالم کا وعظ و نصیحت یہ ہے کہ وہ اس کے ذریعے نصیحت کرے گا (اگر یہ چیز ہمیشہ جاری نہ ہو تو سنت باطل ہو جائے اور شریعت معطل ہو جائے۔) (1)","",{"k":"(1) في الأصل (إلى) بدلاً من (به). في جامع البيان (إسماعیل). سقط من المخطوطة وأثبتناه من الجامع. فآفته نسيانه وهجنته أن تضعه عند غير أهله ونكره الكذب فيه كذا في جامع بيان العلم ص 132 ج 1."}],[1717,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو خبر دی علی بن محمد مروزی نے ان کو خبر دی ابو علی سامی نے ان کو حدیث بیان کی ہے احمد بن یونس نے وہ کہتے ہیں میں نے سنا سری بن مغلس عابد سے وہ کہتے تھے بے شک اللہ کے کچھ ایسے بندے ہیں کہ جن کے دلوں سے اسباب کی حیثیت ختم ہو چکی ہے۔ اور ان کے سیاست کے والی ہونے کی اور ان کے درست کرنے کی کوئی حیثیت نہیں ہے۔ وہ محض اللہ کی عطاء کردہ توفیق کے ساتھ سیدھے اور درست چلتے ہیں۔ اللہ کے سوا انہوں نے کوئی اپنا دوست بنایا ہے اور نہ ہی کوئی مرشد اور رہنما بنایا ہے بالآخر انہوں نے اپنا معاملہ اسباب کے قائم کرنے پر دیا ہے چنانچہ انہوں نے علم کو طلب کیا ہے اور اس کا اقتباس کیا ہے لہذا وہ لوگ بمنزلہ اس چراغ کے ہو گئے جو راستے کے بیچ میں ہوں جس سے لوگ روشنی حاصل کر رہے ہیں۔ لیکن اس کی روشنی کم نہیں ہوتی۔"],[1718,"ہمیں خبر دی ہے ابو عمرو عثمان بن احمد بن سماک نے ان کو فتح بن شحنون نے ان کو عباس بن یزید نے ان کو حباب بن موسیٰ نے ان کو حضرت عبد اللہ بن مبارک نے وہ کہتے ہیں میرے دوست نے مجھے خبر دی ہے اور کہا کہ میرے ایک دوست نے مجھے کچھ مال تقسیم کرنے کے لئے دیا تھا تو ہم دونوں ایک بڑی گلی میں بیٹھ گئے پھر جب ہم واپس آئے تو اس آدمی نے کہا میں نے ان لوگوں کو تلاش کیا ہے جن کے بارے میں آپ نے فرمایا تھا۔ اس نے کہا کہ ہم سب جانتے ہیں۔ پھر اس آدمی نے کہا کہ کوئی یہ بتائے کہ وہ شخص کیسا ہے جو اللہ کا نافرمان ہو یا جو اپنے رب کا احسان کرنے والا ہو۔"],[1719,"ہمیں خبر دی ہے جعفر بن محمد نے ان کو ابو محمد جریری نے ان کو سہل نے وہ کہتے ہیں کہ علم کا شکر تعلیم ہے اور عمل کا شکر معرفت کی زیادتی ہے علم اور عمل کے درمیان کوئی فرق نہیں ہے۔ (1)","",{"k":"(1) أخرجه أبو نعيم في الحلية (۱۹۳/۱۰) عن سهل بلفظ شكر العلم العمل وشكر العمل زيادة العلم."}],[1720,"§کلمہ خیر مال سے بہتر ہے\nہمیں خبر دی ہے ابو الحسن محمد بن ظفر بن محمد علوی نے ان کو ابو الحسن علی بن عمرو بن سہل بغدادی نے ان کو عبد الغافر بن سلماء حمصی نے ان کو ابو حمید نے ان کو ابو حیون نے ان کو ابو ساء عقبہ بن تمیم تنوخی نے ان کو ابو عبید صوری نے وہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ایک ساتھی کے پاس بیٹھے تھے انہوں نے کہا کہ ایک کلمہ خیر (خیر کی بات) میرے نزدیک دنیا و مافیہا سے بہتر ہے۔"],[1721,"ہمیں خبر دی ہے ابو نصر بن قتادہ نے ان کو محمد بن عبد اللہ بن حمیرو یہ ہروی نے ان کو احمد بن نجدہ نے ان کو سعید بن منصور نے ان کو اسماعیل بن عیاش نے ان کو عمارہ بن غزیہ نے ان کو عبد اللہ بن ابو جعفر نے ان کو عبد اللہ بن عمرو بن عاص نے وہ کہتے ہیں کہ یہ رسول اللہ نے فرمایا ایک آدمی نے کہا کہ یا رسول اللہ سب سے افضل اسلام کیا ہے؟ آپ نے فرمایا جو آدمی کسی ایسے آدمی کے لئے امن و امان میں ہو جو اس کے لئے امانتدار ہو۔ یحییٰ بن یحییٰ نے اس کے متابع روایت کی ہے عبد اللہ بن عمر سے اور اس کی اسناد میں عبید اللہ اور عبد اللہ کے درمیان ارسال ہے روایت مرسل ہے۔ (1)","",{"k":"(1) أخرجه أبو يعلى عن ابن عمر (الكنز ۲۸۸۹۲)."}],[1722,"§کثیر بن مرہ حضرمی کی نصیحت\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو العباس اصم نے ان کو حسن بن مکرم نے ان کو یزید بن ہارون نے ان کو جریر نے ان کو سلیمان بن مسہر نے ان کو کثیر بن مرہ حضرمی نے وہ کہتے ہیں کہ آپ حکمت و دانائی کی باتیں بیوقوفوں کے سامنے نہ کیا کریں اس لئے کہ وہ ایک جھوٹا سمجھیں گے۔ اور جھوٹی باتیں حکماء کے سامنے نہ کریں اس لئے کہ وہ تم پر سخت ناراض ہوں گے۔ اور علم کے مستحق سے علم کو نہ روکیں گے آپ گنہگار ہو جائیں گے۔ اور نا اہل کے آگے علم کو بیان نہ کیجئے ورنہ آپ خود جاہل بن جائیں گے۔ بے شک تیرے اوپر تیرے علم کے بارے میں حق ہے، بے شک تیرے اوپر تیرے مال میں بھی حق ہے۔"],[1723,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے ان کو محمد بن عبد اللہ بن محمد بن صبیح نمیری نے ان کو عبد اللہ بن محمد مدینی نے ان کو اسحاق حنظلی نے ان کو بقیہ نے ان کو ولید بن کامل بجلی نے ان کو نصر بن علقمہ نے ان کو عبد الرحمن بن عائد نے ان کو مقدام بن معدیکرب نے انہوں نے رسول اللہ صلی اللہ علیہ وسلم نے آپ نے فرمایا: جب تم لوگ لوگوں کو کچھ بیان کرنے لگے تو ان کو ایسی بات بیان کرو جو غائب ہو اور ان پر مشقت ہو۔ (1)","",{"k":"(1) أخرجه ابن عدي في الكامل (۲۵۴۲/۷) من طريق أبي همام عن بقية به."}],[1724,"§متعلم اور معلم سخی ہوتے ہیں\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے اور ابو سعید بن ابو عمرو نے ان کو عباس محمد بن یعقوب نے ان کو ابو بکر احمد بن عاصم نبیل قاضی اصفہانی نے ان کو حوئی عبد الوہاب بن نجدہ نے ان کو سوید بن عبد العزیز نے ان کو نوح بن ذکوان نے ان کو ان کے بھائی نے ان کو حسن نے ان کو انس بن مالک رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا کہ رسول اللہ نے فرمایا تم لوگوں میں سب سے زیادہ سخی اللہ تعالیٰ ہے۔ اور میں بنی آدم میں سب سے زیادہ سخی ہوں۔ اور میرے بعد سب سے زیادہ سخی وہ آدمی ہوگا جس نے علم سیکھا اور اس علم کو پھیلایا قیامت کے دن وہ اکیلا امت بن کر آئے گا۔ اور ایک آدمی وہ ہے جو اپنی جان کے بارے میں بخل کرے اور اللہ کی راہ میں خرچ نہ کرے یہاں تک کہ قتل کر دیا جائے۔ (1)","",{"k":"(1) أخرجه الشجري (۵۶/۱) من طريق ابن أبي عاصم به."}],[1725,"ہمیں خبر دی ہے علی بن احمد بن عبدان نے ان کو احمد بن عبید نے ان کو اسماعیل بن فضل بلخی نے ان کو محمد بن مصفا نے ان کو بقیہ نے ان کو زبیری نے ان کو زہری نے ان کو سائب بن یزید نے وہ کہتے ہیں کہ عہد رسول عہد بدر میں کوئی قصہ بیان نہیں کیا تھا لیکن جب سیدنا عمر فاروق رضی اللہ تعالیٰ عنہ کا زمانہ آیا تو تمیم داری نے سیدنا عمر سے قصہ بیان کرنے کی اجازت طلب کی تو انہوں نے اس کو اجازت دے دی اور قصہ بیان کرنے لگے۔ اس کو ہم نے کتاب المدخل میں روایت کیا ہے۔\nشیخ حلیمی نے فرمایا\nطالب علم کو چاہئے کہ اس کا تعلیم حاصل کرنا اور عالم کو چاہئے کہ اس کا تعلیم دینا محض اللہ تعالیٰ کی رضا کے لئے ہونا چاہئے۔ طالب علم یہ ارادہ کرے کہ جو کچھ وہ تعلیم کر رہا ہے اس کے ساتھ مال کمائے گا یا لوگوں میں اپنی شہرت میں اضافہ کرے گا یا اپنے ہم عصروں پر اپنی فوقیت و برتری جتلائے گا، یا اپنے مخالفین کو نیچا دیکھائے گا یا ان کا مقابلہ کرے گا اور عالم اپنے پڑھانے اور تعلیم دینے سے یہ ارادہ نہ کرے کہ اس سے پڑھنے والے شاگرد بہت ہوں گے اور جب شمار کئے جائیں گے تو اس کے علاوہ لوگوں کے مقابلے میں اس سے علم حاصل کرنے والے زیادہ تعداد میں ہوں گے، اور یہ بھی ارادہ نہ ہو کہ اس کا علم دوسروں کے علم کے مقابلے میں لوگوں میں غالب ہو گا۔ بلکہ عالم امانت کو پہچاننے کا ارادہ کرے کہ اس سے جس نے علم حاصل کیا ہے اس طرح اس نے اس امانت کو پھیلایا ہے جو اس کے سینے میں محفوظ اور دفن تھی اور معالم دین کے جیسا نیت کرے اور ان کے مٹنے اور سے اپنے درس کے ساتھ حفاظت کرنے کی نیت کرے۔"],[1726,"سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے مروی ہے کہ انہوں نے فرمایا کہ اگر قرآن میں یہ آیت نہ اتری ہوتی تو میں تمہیں حدیث بیان نہ کرتا اس کے بعد انہوں نے یہ آیت پڑھی:\n﴿واذ اخذ الله ميثاق الذين اوتوا الكتاب لتبيننه للناس ولاتكتمونه﴾\n’’(یاد کرو اس وقت کو) جب اللہ نے ان لوگوں سے پکا عہد لیا تھا جو کتاب دیئے گئے ہیں کہ تم اس کو لوگوں کے لئے ضرور بیان کرو گے اور اسے بالکل نہیں چھپاؤ گے۔‘‘\nتبصرہ: شاگرد اللہ کی عبادت کا تصور اور ارادہ کرے اور علم دین اس لئے سیکھے کہ اس کا علم اسے عمل تک پہنچائے جس کے ذریعہ اللہ تعالیٰ اس سے راضی ہو جائے اور علماء میں اضافہ ہو یہ بات علم کے لئے زیادہ احتیاط کی بات ہوگی۔ اور علم کی بقاء کے لئے زیادہ انسب ہوگی۔"],[1727,"§علم اگر دنیا کے حصول کے لئے ہو تو جنت سے محروم کر دے گا\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو العباس سیاری نے اور ابو محمد بن حکم نے ان کو ابو الموجہ نے ان کو سعید بن منصور مکی نے ان کو فلیح نے ان کو ابو طوالہ نے ان کو سعید بن یسار نے ان کو سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا کہ جو شخص اللہ کی رضا حاصل کرنے کے لئے علم حاصل کرتا جاتا ہے اس سے دینوی اسباب و مال یا جاہ کے لئے طلب کرتا ہے وہ جنت کی خوشبو بھی نہیں پائے گا۔ فلیح نے کہا کہ عرفھا سے مراد اس کی خوشبو ہے۔ (1)","",{"k":"(1) أخرجه أبو داؤد (۳۶۶۴) وابن ماجه (۲۵۲) والحاكم (۸۵/۱) من طريق فليح به."}],[1728,"§علماء پر فخر کرنے کے لئے علم حاصل مت کرو\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو الحسین محمد بن احمد بن تمیم قنطری نے ان کو ابو اسماعیل محمد بن اسماعیل سلمی نے ان کو سعید بن ابو مریم نے ان کو یحییٰ بن ایوب نے ان کو ابن جریج نے ان کو ابو زبیر نے ان کو جابر بن عبد اللہ نے انہوں نے فرمایا کہ علم اس لئے حاصل نہ کرو کہ تم اس کے ذریعے علماء پر فخر کرو (انہیں حقیر دیکھو) یا بے وقوفوں کے آگے بڑ مارو ان پر رعب جھاڑو اور اس لئے بھی نہیں کہ اس کے ذریعے تم مجالس میں اور محافل کی زینت بنو جس نے ایسا کیا بس آگ ہے اس کے لئے آگ۔ (1)","",{"k":"(1) أخرجه المصنف من طريق الحاكم (۸۶/۱)."}],[1729,"ہمیں خبر دی ہے محمد بن عبد اللہ حافظ نے ان کو ابو بکر بن الحق فقیہ نے ان کو حسن بن علی بن زیاد نے ان کو ابن ابی اویس نے ان کو ان کے بھائی نے سلیمان بن بلال سے ان کو الحق بن یحییٰ بن طلحہ نے ان کو عبد اللہ بن کعب بن مالک نے اپنے والد سے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے آپ نے فرمایا۔ جس نے علم حاصل کیا تا کہ اس کے ذریعے علماء کے ساتھ مقابلہ کرے ان پر فخر کرے بڑائی کرے یا اس کے ذریعے کم عقلوں سے بحث کرے یا اس کے ذریعے لوگوں سے مالی مفاد حاصل کرے بس وہ جہنم کی طرف چلا گیا۔ (1)","",{"k":"(1) أخرجه المصنف من طريق الحاكم (۸۶/۱)."}],[1730,"§بے عمل خطیب کی سزا\nہمیں خبر دی ہے ابو الحسین بن فضل قطان نے ان کو ابو عمرو بن سماک نے ان کو محمد بن غالب نے ان کو مسلم نے ان کو صدقہ بن موسیٰ نے ان کو حسن بن جعفر نے ان کو مالک بن دینار نے ان کو عمامہ بن عبد اللہ بن انس نے ان کو سیدنا انس رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا کہ میں شب معراج ایسے لوگوں پر گذرا جن کے ہونٹ کاٹے جا رہے تھے جہنم کی آگ کی قینچیوں کے ساتھ جب بھی کاٹے جاتے وہ بڑھتے تھے میں نے پوچھا اے جبرائیل یہ کون لوگ ہیں؟ جبرائیل نے جواب دیا کہ آپ کی امت کے خطیب ہیں جو لوگ جو کچھ کہتے تھے اس پر عمل نہیں کرتے تھے اور کتاب اللہ کو پڑھتے تھے اور اس پر عمل نہیں کرتے تھے۔"],[1731,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے ان کو محمود بن محمد فقیہ نے مقام مرو میں ان کو ابو امامہ نے ان کو احمد بن عبد اللہ فریانانی نے ان کو فضیل بن عیاض نے (ح) اور ہمیں خبر دی ہے ابو نصر بن قتادہ نے ان کو محمد بن عبد اللہ بن حمیرو یہ ہروی نے ان کو احمد بن نجدہ نے ان کو سعید بن منصور نے ان کو فضیل بن عیاض نے ان کو یحییٰ بن عبد اللہ نے ان کو ان کے والد نے ان کو ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا کہ اے امت مجھے تمہارے اوپر اس بات کا خوف نہیں ہے کہ تم لوگ علم حاصل نہیں کرو گے لیکن یہ دیکھو کہ تم عمل کیسے کرتے ہو اس پر جس کا علم سیکھتے ہو۔ (یعنی ڈرا عمل نہ کرنے کا ہے۔) (1)","",{"k":"(1) أخرجه أبو نعيم في الحلية (۱۳۲/۸) من طريق فضيل بن عياض به."}],[1732,"§مجھے ڈر لگتا ہے منافق عالم سے\nہمیں خبر دی ہے ابو الحسین بن بشران نے ان کو ابو جعفر محمد بن عمرو رزاز نے ان کو عبد الکریم بن ہیثم نے ان کو عبید اللہ بن معاذ عنبری نے ان کو ان کے والد نے ان کو حسن معلم نے ان کو ابن بریدہ نے ان کو عمران بن حصین نے وہ کہتے ہیں کہ رسول اللہ نے فرمایا جس چیز کا میں تم لوگوں پر خوف کرتا ہوں میرے بعد وہ منافق عالم کی زبان ہے۔ (1)","",{"k":"(1) قال الهيثمي في المجمع (۱۷۷/۱) إلى الطبراني في الكبير والبزار ورجاله رجال الصحيح. أخرجه البزار (۹۷/۱، كشف الأستار) من طريق حسن المعلم به بلفظ. حذرنا رسول الله صلى الله عليه وسلم كل منافق عليم اللسان. وقال البزار لا تحفظه إلا عن عمر بن الخطاب وإسناد عمر صالح فأخرجناه عنه وأعدناه عن عمران لحسن إسناد عمران."}],[1733,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے ان کو محمد بن عبد اللہ بن محمد بن قریش نے ان کو حسن بن سفیان نے ان کو محمد بن عبید بن حسان نے ان کو حماد بن زید نے ان کو میمون کردی نے ان کو ابو عثمان نہدی نے ان کو سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ نے وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے اور منبر پر فرما رہے تھے بچاؤ بچاؤ تم اپنے آپ کو منافق عالم سے لوگوں نے پوچھا کہ منافق عالم کیسے ہوتا ہے فرمایا کہ جو حق کی بات کرے اور عمل برا کرے۔ (1)","",{"k":"(1) في المخطوطة \"مسجد الحرام\"."}],[1734,"ہمیں خبر دی ہے ابو محمد عبد اللہ بن یوسف اصفہانی نے ان کو محمد بن احمد بن ہامان مؤذن سید الحرام نے ان کو علی بن عبد العزیز نے ان کو عارم نے ان کو دیلم بن غزوان نے ان کو میمون کردی نے ان کو ابو عثمان نہدی نے ان کو سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ نے انہوں نے نبی کریم سے کہ آپ نے فرمایا میں اس امت پر ڈرتا ہوں ہر منافق سے جو حکمت کی اور دانائی کی باتیں کرے گا اور عمل گناہ اور ظلم کے ساتھ کرے گا یہ بھی کہا کہ لوگ اس کی بات پر عمل کریں گے اس کی بات کو لوگ مانیں گے لیکن اس کے دل میں ایمان اتنا ہوگا جتنا کہ دانہ ہوتا ہے۔ (1)","",{"k":"(1) أخرجه عبد بن حميد والمصنف (الكنز ۲۹۰۴۴). أخرجه ابن عساكر في تاريخ دمشق (الكنز ۲۹۰۹۹)."}],[1735,"§جس کا علم اس کو فائدہ نہ دے\nہمیں خبر دی ابو زکریا بن ابو اسحاق نے ان کو ابو بکر احمد بن سلیمان فقیہ نے ان کو جعفر صائغ نے ان کو ولید بن صالح نے ان کو عثمان بن مقیم نے (ح) اور ہمیں خبر دی ہے ابو محمد بن یوسف نے ان کو ابو مراس اسحاق بن ابراہیم مالکی نے مکہ میں ان کو عبد العزیز بن ابو رجاء نے ان کو یونس بن عبد الاعلیٰ نے ان کو ابن رہب نے ان کو جریر یحییٰ بن سلمان نے ان کو عثمان بن مقیم نے ان کو سعید مقبری نے ان کو سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا قیامت کے دن شدید عذاب والا آدمی وہ عالم ہوگا جس کے علم نے اس کو فائدہ نہیں دیا ہوگا۔ ابو زکریا کی روایت میں ہے اس نے کہا جس کے علم نے اس کو فائدہ نہیں دیا ہوگا۔"],[1736,"§بے عمل عالم سے حضور صلی اللہ علیہ وسلم کا پناہ مانگنا\nہمیں خبر دی ہے ابو عثمان سعید بن محمد بن محمد بن عبدان نیساپوری نے ان کو ابو الحسن محمد بن حسن کاوزی نے ان کو ابو عبد اللہ محمد بن علی زید صائغ نے ان کو سعید بن منصور نے (ح) اور ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو علی بن حمشاد نے ان کو محمد بن نعیم نے ان کو قتیبہ بن سعید نے ان کو خلف بن خلیفہ نے ان کو حفص بن اخی انس نے ان کو سیدنا انس رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا کہ حضور صلی اللہ علیہ وسلم کی دعا میں سے یہ دعا تھی۔ اے اللہ میں تیرا پناہ چاہتا ہوں ایسے علم سے جو فائدہ نہ دے اور ایسے دل اور نفس سے جو سیر نہ ہو سکے اور ایسی دعا سے جو قبول نہ ہو سکے۔ اور دعا کے آخر میں یہ کہتے تھے اللہ میں ان مذکورہ چار چیزوں سے تیرے ساتھ پناہ لیتا ہوں۔"],[1737,"اور اس کو زید بن ارقم نے بھی نبی کریم صلی اللہ علیہ وسلم سے روایت کرتا ہوں اور اسی طریق سے اس کو امام مسلم نے روایت کیا۔ (1)","",{"k":"(1) أخرجه مسلم (۲۰۸۸/۳) عن زيد بن أرقم مرفوعاً أثناء حديث."}],[1738,"ہمیں خبر دی ہے ابو محمد یوسف اصفہانی نے ان کو ابو محمد عبد اللہ بن محمد بن اسحاق ماکھی نے ان کو ابو یحییٰ بن ابو مسرۃ نے ان کو یحییٰ بن محمد نے ان کو عبد العزیز بن محمد نے ان کو اسامہ بن زید نے ان کو محمد بن منکدر نے ان کو جابر بن عبد اللہ نے وہ کہتے ہیں کہ یہ کہ رسول اللہ نے فرمایا جب آپ منبر پر تشریف فرما تھے کہ اللہ تعالیٰ سے علم نافع کا سوال کرو اور غیر نافع علم سے اللہ کی پناہ مانگو۔ (1)","",{"k":"(1) أخرجه ابن ماجه (۳۸۴۳) من طريق أسامة بن زيد الليثي به وقال البوصيري في الزوائد إسناده صحيح رجاله ثقات."}],[1739,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے اور ابو سعید بن ابو عمرو نے اور دونوں نے کہا کہ ہمیں حدیث بیان کی شعبہ نے موسیٰ بن ابی عائشہ سے اس نے مولیٰ ام سلمہ سے اس نے سیدہ ام سلمہ سے کہ وہ یہ حدیث بیان کرتی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم جب صبح کی نماز کا سلام پھیرتے تو یوں کہتے تھے اے اللہ میں تجھ سے علم نافع کا سوال کرتا ہوں اور پاکیزہ رزق کا اور عمل مقبول کا۔ (1)","",{"k":"(1) أخرجه أحمد (۳۰۵/۶) عن روح عن شعبة به."}],[1740,"§سیدنا عویمر کا بیان\nہمیں خبر دی ہے علی بن احمد بن عبدان نے ان کو احمد بن عبید نے ان کو ابو اسماعیل ترمذی نے ان کو ابو صالح نے ان کو معاویہ بن صالح نے ان کو ابو زاہریہ نے ان کو سیدنا ابو درداء رضی اللہ تعالیٰ عنہ نے انہوں نے فرمایا مجھے اس بات کا ڈر نہیں ہے کہ کل قیامت کے دن مجھ سے یہ سوال کیا جائے کہ اے عویمر تو نے کیا عمل کیا؟ لیکن مجھے اس بات کا ڈر ہے کہ مجھ سے کل قیامت کے دن یہ سوال کیا جائے کہ اے عویمر تو نے کیا سیکھا تھا یا جس چیز کا علم حاصل کیا تھا اس پر کتنا عمل کیا تھا؟"],[1741,"§قیامت کے دن کے پانچ سوال\nہمیں خبر دی ہے ابو سعد مالینی نے ان کو ابو احمد بن عدی حافظ نے ان کو ابو یعلیٰ نے ان کو محمد بن عقبہ نے ان کو ابو حفص حصین بن نمیر ہمدانی نے ان کو حسین بن قیس ابو علی رحبی نے اور ابو حص کا خیال ہے کہ وہ شیخ صدوق ہیں انہوں نے عطاء بن عمر سے انہوں نے سیدنا عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے آپ نے فرمایا کہ ابن آدم کے قدم اس وقت تک اپنے رب کے آگے سے نہیں ہٹیں گے یہاں تک کہ پانچ خصلتوں کے بارے جواب دینا پڑے گا: ❶ جوانی کے بارے میں کہاں کہاں بڑھاپے تک خرچ کی تھی۔ ❷ عمر کے بارے میں کہ کہاں اس کو فنا کیا تھا۔ ❸ مال کے بارے میں کہاں سے کمایا تھا۔ ❹ اور کس چیز میں خرچ کیا تھا۔ ❺ اور جو علم رکھتے تھے اس پر کتنی عمل کیا تھا؟ محمد بن عقبہ نے کہا کہ میں حشان اور نھر کے پاس گیا یونوں نے اسی حدیث کے بارے میں سوال کیا۔ (1)","",{"k":"(1) أخرجه المصنف من طريق ابن عدي (۷۶۳/۲)."}],[1742,"ہمیں خبر دی ہے ابو الحسن محمد بن یعقوب بن احمد فقیہ نے مقام طاہران میں ان کو ابو محمد عبد اللہ بن محمد نے ان کو عشان واسطی نے ان کو مفضل بن محمد جزری نے مکہ میں ان کو صامت بن معاذ جزری نے ان کو عبد المجید بن عبد العزیز بن ابو درداء نے ان کو سفیان ثوری نے ان کو صفوان بن سلیم نے ان کو عدی بن عدی صنابحی نے ان کو سیدنا معاذ بن جبل رضی اللہ تعالیٰ عنہ نے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے آپ نے فرمایا نہیں ہٹیں گے اس آدمی کے دونوں قدم اس وقت تک کہ اس سے چار چیزوں کے بارے میں سوال نہ کیا جائے عمر کے بارے میں کہ اس کو کہاں فنا کیا تھا اور جسم کے بارے میں کہ اس کو کس چیز میں بوڑھا کیا تھا اور مال کے بارے میں کہ اس کو کہاں سے کمایا تھا اور کہاں خرچ کیا تھا اور علم کے بارے میں کہ اس پر کتنا عمل کیا تھا۔ اس کو بھی یحییٰ بن راشد نے ایک آدمی سے اس نے سیدنا معاذ سے روایت کیا ہے۔ (1)","",{"k":"(1) أخرجه الخطيب في تاريخ بغداد (۴۴۱/۱۱ و ۴۴۲) من طريق المفضل بن محمد به."}],[1743,"ہم نے اس کو بھی روایت کیا ہے ابو بردہ اسلمی سے اس نے نبی کریم صلی اللہ علیہ وسلم سے۔ (1)","",{"k":"(1) أخرجه الترمذي (۲۴۱۷) عن أبي برزة الأسلمي وقال: هذا حديث حسن صحيح. وأبو برزة إسمه نضلة بن عبيد."}],[1744,"§حضرت مالک بن دینار کی عادت\nہمیں خبر دی ہے ابو الحسین بن بشران نے ان کو ابو الحسین اسحاق بن احمد کاذی نے ان کو عبد اللہ بن احمد بن محمد بن حنبل نے ان کو ان کے والد نے ان کو سیار نے ان کو جعفر بن سلیمان نے ان کو مالک بن دینار نے ان کو حسن نے وہ کہتے ہیں کہ جب کوئی خطیب خطبہ دیتا ہے تو اس کے خطبے پر غور کیا جائے اگر اس کا خطبہ اس کے دل کی آواز ہو تو سمجھو کہ اس کا خطبہ مقبول ہے اور اگر اس کا خطبہ اس کے دل سے نہ نکلے تو لوگ یہ سمجھتے ہیں کہ میری آنکھ ٹھنڈی ہوتی ہے جب میں اپنے آپ کو خطیبوں میں کھڑا دیکھوں۔ حضرت جعفر نے کہا کہ حضرت مالک بن دینار کی عادت تھی کہ جب وہ خطبہ دیتے تو روتے تھے اور حاضرین بھی روتے تھے۔ (1)","",{"k":"(1) أخرجه المصنف من طريق أحمد بن حنبل في الزهد (۱۸۹۴) ط/ دار الكتاب العربي."}],[1745,"ہمیں خبر دی ہے علی بن احمد بن عبدان نے ان کو احمد بن عبید نے ان کو اسماعیل بن اسحاق نے ان کو حجاج نے اور سلیمان بن حرب نے ان کو حماد بن سلمہ نے ان کو علی بن زید نے ان کو اوس بن خالد نے ان کو ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انہوں نے کہا کہ رسول اللہ نے فرمایا تھا۔ کہ اللہ تعالیٰ نے حکمت و دانائی کو ایک چرواہے کے پاس رکھا تھا اور اس کے ساتھ اس کا چرواہا تھا اس کو چرواہے کے پاس ہونا تھا جب وہ اس سے راضی ہو گیا تو اس نے اس کو اس کی اصل حالت میں واپس کر دیا۔ یہ الفاظ حجاج بن منہال کی حدیث کے ہیں۔"],[1746,"§سیدنا عمر بن خطاب رضی اللہ عنہ کا بیان\nہمیں خبر دی ہے محمد بن عبد اللہ حافظ نے ان کو ابو العباس بن یعقوب نے ان کو محمد بن عبد اللہ بن حکم نے ان کو ابن وہب نے ان کو مجھے خبر دی ہے یونس بن یزید نے عمران بن مسلم سے یہ عمر بن خطاب رضی اللہ تعالیٰ عنہ فرمایا تھا۔ علم سیکھو اور لوگوں کو سکھلاؤ اور اس کے لئے وقار اور بردباری سیکھو اور جو شخص تمہیں تعلیم دے رہا ہے اس کے لئے عاجزی کرو علم سیکھتے وقت اور اس کے لئے بھی عاجزی کرو جس کو تم علم سکھلا رہے ہو تم سرکش علماء نہ ہو ورنہ تمہارا علم تمہارے جہل کا مقابلہ نہیں کر سکے گا۔ (1)","",{"k":"(1) سبق برقم (۱۷۲۲). أخرجه أحمد في الزهد وآدم بن أبي إياس في العلم والدينوري في المجالسة وابن منده في غرائب شعبة والإجري من أخلاق حملة القرآن والمصنف وابن أبي شيبة (الكنز ۲۹۳۴۸) أخرجه ابن عبد البر (۱۳۵/۱) من طريق يونس بن يزيد به."}],[1747,"ہمیں خبر دی ہے ابو الحسین بن فصل قطان نے ان کو علی بن عبد الرحمن بن ماتی کوفی نے ان کو احمد بن حازم بن ابی غرزہ نے ان کو ہشیم بن محمد خشاب نے ان کو عبد العزیز بن ابی حازم نے ان کو ان کے والد نے ان کو سعید بن جبیر نے ان کو جابر بن عبد اللہ نے انہوں نے فرمایا کہ عالم کو چاہئے کہ وہ اپنے دل کو ایسے دھو ڈالے جیسے کپڑا نجاست سے دھو دیا جاتا ہے۔"],[1748,"§سیدنا جابر رضی اللہ عنہ فرماتے ہیں\nاسی کی اسناد کے ساتھ سیدنا جابر رضی اللہ تعالیٰ عنہ سے مروی ہے کہ آپ نے فرمایا۔ خاموشی سیکھو۔ اس کے بعد حوصلہ سیکھو اس کے بعد علم سیکھو اس کے بعد عمل سیکھو اس کے بعد تم پھیل جاؤ (یعنی علم پھیلانے میں لگ جاؤ۔)"],[1749,"§حضرت ابراہیم بن ادھم فرماتے ہیں\nہمیں خبر دی ہے جعفر بن محمد خواص نے ان کو ابراہیم بن نصر منصوری نے ان کو ابراہیم بن بشار نے ان کو ابراہیم بن ادھم نے وہ کہتے ہیں کہ اگر اللہ تعالیٰ میرے معاملے میں آسانی کرے تو مجھے پہاڑ کی چوٹی پسند ہے میں اس پر رہوں گا لوگوں کے ساتھ زیادہ میل ملاقات نہیں کروں گا مجھے زیادہ بولنا پسند نہیں۔ مجھے تو اجتہاد و عبادت کے لئے فراغت پسند ہے۔ علماء نے کہا ہم کو یہ خبر ملی ہے کہ اللہ تعالیٰ سے ڈرنے والے بندے کو اپنے یہ پرواہ نہیں ہوتی کہ اس کا دن شروع ہو گیا ہے یا شام ہوگئی ہے۔"],[1750,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو الحسن سری نے ان کو عثمان بن سعید نے ان کو نعیم بن حماد نے ان کو حضرت ابن مبارک نے وہ کہتے ہیں کہ ہم ایک مرتبہ بچوں کے ساتھ نکلے ہم میں سے کسی کو کوئی کام تھا ہمارے بزرگ نے مجھ سے کہا کہ اب زیادہ تر میں صحابہ کرام رضی اللہ عنہم کے ساتھ ہوتا ہوں۔ اور تابعین کے ساتھ ہوتا ہوں۔"],[1751,"§عالم کی تین نشانیاں\nہمیں خبر دی ہے ابو اسامہ محمد بن امر مقری نے مکہ میں ان کو محمد بن احمد بن عبد اللہ بن نصر قاضی نے ان کو احمد بن مسلم نے ان کو عصمہ بن فضل نے ان کو زید بن حباب نے ان کو مبارک بن فضالہ نے ان کو عبید بن عمر نے ان کو ابو حازم نے انہوں نے کہا کہ آپ اس وقت تک عالم نہیں ہو سکتے جب تک کہ تیرے اندر تین خصلتیں نہ آجائیں: ❶ جو تم سے اوپر ہے اس تک پہنچنے کی طلب نہ کرو۔ اور ❷ جو تم سے کمتر ہے اس کو حقیر نہ سمجھو۔ اور ❸ اپنے علم کے ساتھ دنیا حاصل نہ کرو۔ (1)","",{"k":"(1) أخرجه أبو نعيم في الحلية (۲۴۳/۳) من طريق زيد بن الحباب به."}],[1752,"ہمیں خبر دی ہے ابو محمد فراس نے مکہ مکرمہ میں ان کو ابو عبد اللہ بن ضحاک نے ان کو علی بن عبد العزیز نے ان کو ابو یعقوب مروزی نے نے انہوں نے فرمایا کہ میں نے سنا سفیان ثوری سے وہ فرماتے تھے۔ کہ عالم جھگڑا اور جدال نہیں کرتا۔ اور کسی کی مخالفت نہیں کرتا بلکہ وہ اللہ کی حکمت کو پھیلاتا ہے اگر قبول ہو جائے تو اللہ کی حمد کرتا ہے اور اگر رد ہو جائے تو بھی اللہ کی حمد کرتا ہے۔"],[1753,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے اور محمد بن موسیٰ نے دونوں نے کہا ہمیں حدیث بیان کی ہے ابو العباس محمد بن یعقوب نے ان کو عبد اللہ بن احمد بن حنبل نے وہ فرماتے ہیں کہ مجھ کو حدیث بیان کی ہے میرے والد نے ان کو ابو جھم عبد القدوس بن بکر بن خنیس نے ان کو محمد بن نضر حارثی نے وہ کہتے ہیں۔ پہلے دور میں یوں کہا جاتا تھا کہ پہلی تعلیم خاموش رہنے کی ہوتی تھی اس کے بعد توجہ سے سننے کی اس کے بعد اس کو یاد کرنے کی اس کے بعد اس پر عمل کرنے کی اس کے بعد اس کو پھیلانے کی۔"],[1754,"§طالب علم کا کام\nہمیں خبر دی ہے ابو عبد اللہ نے ان کو حسن بن محمد بن اسحاق نے کہتے ہیں کہ میں نے سنا ابو عثمان حناط سے وہ کہتے ہیں کہ میں نے سنا ذوالنون سے وہ کہتے ہیں کہ سفیان بن عیینہ نے کہا پہلا علم توجہ سے بات کو سننا اس کے بعد سمجھنا اس کے بعد اس کو یاد رکھنا پھر اس پر عمل کرنا پھر اس کو آگے پھیلانا ہے۔"],[1755,"ہمیں خبر دی ہے ابو حازم حافظ نے وہ کہتے ہیں کہ میں نے سنا اسماعیل بن احمد جرجانی نے وہ کہتے ہیں میں نے سنا عبد اللہ بن محمد سے انہوں نے محمود بن غیلان سے انہوں نے وکیع سے انہوں نے ابراہیم بن اسماعیل بن مجمع بن حارثہ نے وہ کہتے ہیں کہ ہم لوگ حدیث کو یاد کرنے کے لئے حدیث کے ساتھ عمل کرنے سے مدد لیتے تھے۔"],[1756,"§کائنات کا عظیم انسان\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو العباس محمد بن یعقوب نے ان کو ہارون بن سلیمان نے ان کو عبد الرحمن بن مہدی نے ان کو مبشر بن منصور نے ان کو ثور بن یزید نے ان کو عبد العزیز بن ظبیان نے وہ کہتے ہیں کہ شیخ نے فرمایا۔ جو شخص علم سیکھے اور عمل کرے اور دوسروں کو علم سکھلائے ایسا شخص کائنات سماوی میں عظیم انسان ہوتا ہے۔"],[1757,"§حسن سے احسن تک\nہمیں خبر دی ہے سعید بن محمد شعیمی نے وہ کہتے ہیں کہ میں نے سنا ہے احمد بن نصر (۱) بن فقیہ سے انہوں نے ابو یعقوب اسماعیل بن حسن قروی سے انہوں نے سنا یحییٰ بن معاذ رازی وہ کہتے ہیں کہ کلام حسن ہوتا ہے اور کلام سے احسن اس کا معنی ہوتا ہے اور اس کے معنی سے احسن اس پر عمل ہوتا ہے اور اس پر عمل سے احسن اس کا ثواب ہوتا ہے اور اس کے ثواب سے احسن اس ذات کی رضا ہوتی ہے جس کے لئے آپ نے عمل کیا ہے۔"],[1758,"ہمیں خبر دی ہے ابو محمد بن حسین بن داؤد حسنی نے ان کو عبد اللہ بن محمد بن حسن شرقی نے ان کو علی بن سعید فسوی نے ان کو سعید بن عامر نے ان کو حمید بن اسود نے ان کو عیسیٰ خیاط نے انہوں نے سنا شعبی سے وہ کہتے ہیں کہ وہ انسان تلاش کیا جاتا اور پسند کیا جاتا تھا جس میں دو\n(۱۷۹۶) أخرجه أبو نعيم في الحلية (۲۱۷/۸) من طريق عبد الله بن أحمد بن حنبل. به.\n(۱۷۹۷) أخرجه أبو نعيم في الحلية (۲۷۳/۷) من طريق محمد بن بشر الحارثي عن ابن عيينة.\n(۱) كلمة غير واضحة ورسمها هكذا (انتليب)\nخصلتیں جمع ہو جاتیں عقل اور پرہیزگاری جو شخص عاقل ہوتا اور پرہیزگار نہ ہوتا تو لوگ کہتے تھے یہ ایسا امر ہے جس کو پرہیزگار ہی پا سکتا ہے اور اگر پرہیزگار ہوتا مگر عاقل نہ ہوتا تو لوگ یہی کہتے تھے کہ یہ ایسا امر ہے کہ اس کو عقلاء ہی پا سکتے ہیں۔ پھر تم نے کیوں طلب کیا؟ امام شعبی نے فرمایا تحقیق مجھے خوف ہے کہ آج ایسے انسان کو ہی نہ طلب کیا جائے جس میں دونوں میں سے ایک بھی نہ ہو نہ عقل نہ پرہیزگاری۔"],[1759,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو خبر دی ہے جعفر بن محمد نے ان کو جنید بن محمد نے وہ کہتے ہیں کہ میں نے سنا سری سے کہتے تھے جس وقت انسان ابتدا کرے عبادت و پرہیزگاری کی۔ اس کے بعد حدیث کی کتابت کرے فقیر رہتا ہے اور جب اولاً حدیث لکھے اس کے بعد عبادت و ریاضت کرے آگے نکل جاتا ہے۔"],[1760,"§فقہ نصف علم ہے باعتبار انجام\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے انہوں نے سنا عبد الرحمن بن احمد قاضی نے وہ کہتے ہیں کہ میں نے سنا زنجویہ بن محمد سے کہتے ہیں میں نے سنا محمد بن اسماعیل بخاری سے کہتے ہیں میں نے سنا علی بن عبد اللہ سے وہ کہتے ہیں۔ کہ فقہ انجام کے اعتبار سے نصف علم ہے اور معرفت رجال و مذاہب نصف علم ہے۔"],[1761,"ہمیں خبر دی ہے یحییٰ بن ابراہیم بن محمد بن یحییٰ نے ان کو ابو الحسن طراھی نے ان کو عثمان دارمی نے ان کو زکریا بن نافع فلسطینی نے ان کو عباد بن عباد نے وہ خواص رملی ہیں ان کو ابن شوذب نے انہوں نے مطر سے وہ کہتے ہیں کہ بہترین علم وہ ہے جو نفع دے سوائے اس کے نہیں کہ اللہ نفع دیتا ہے علم سے اس شخص کو جو علم حاصل کرے اور اس پر عمل کرے اس شخص کو اللہ اس کے علم سے فائدہ نہیں دیتا جو علم حاصل کر کے اس کو چھوڑ دے۔"],[1762,"§علم حدیث کی زکوٰۃ کیسے ادا ہوگی\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو زرعہ رازی نے ان کو حسین بن اسماعیل نے ان کو عبید بن محمد وراق نے وہ کہتے ہیں میں نے سنا بشر بن حارث سے وہ کہتے ہیں اے اصحاب الحدیث اس علم حدیث کی زکاۃ ادا کرو لوگوں نے پوچھا کہ اس کی زکاۃ کیا ہے؟ فرمایا کہ ہر ایک سو حدیث میں سے پانچ احادیث پر ضرور عمل کرو۔"],[1763,"ہمیں خبر دی ہے ابو نصر بن قتادہ نے ان کو ابو محمد بن سعید حافظ نے ان کو محمد بن ابراہیم بوشنجی نے ان کو سعید بن نصیر نے ان کو سیار بن حاتم نے ان کو جعفر نے وہ کہتے ہیں میں نے سنا مالک بن دینار سے وہ کہتے ہیں میں نے توراۃ میں پڑھا ہے۔ کہ وہ شخص جس کا علم اس کی خواہش پر غالب وہی زبردست عالم ہے۔"],[1764,"ہمیں خبر دی ہے ابو محمد عبد اللہ بن یوسف نے ان کو ابو بکر عبد اللہ بن یحییٰ طلحی نے کوفہ میں ان کو ابو عمر عثمان نے ایک آدمی سے اس نے مسیب بن رافع سے انہوں نے کہا کہ سیدنا عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ نے فرمایا حامل قرآن (حافظ قاری عالم قرآن کا علم رکھنے والے) کو چاہئے کہ وہ رات میں قرآن کی خوشبو بکھیرے جب لوگ سو رہے ہوں اور دن میں جب لوگ (اس کو) چھوڑ رہے ہوں اور اس کے غم کے ساتھ جب لوگ خوش ہو رہے ہوں اور اس کے رونے کے ساتھ جب لوگ غرور اور تکبر کر رہے ہوں۔\n(۱۸۰۲) أخرجه أبو نعيم في الحلية (۱۲۵/۱۰) من طريق الجنيد. به."],[1765,"ہمیں خبر دی ہے ابو الحسین بن بشران نے ان کو عثمان بن احمد سماک نے ان کو ابو حسین حسن بن عمرو سبیعی مروزی نے وہ کہتے کہ میں نے سنا بشر بن حارث سے۔ جبکہ ان کے پاس ایک دن اصحاب حدیث آئے ہوئے تھے اور میں بھی وہاں موجود تھا۔ چنانچہ بشر نے کہا یہ کیا چیز ہے جو میں تمہارے ساتھ دیکھتا ہوں جسے تم نے ظاہر کیا ہے۔ ان لوگوں نے کہا اے ابو نصر ہم یہ علوم طلب کرتے ہیں۔ شاید اللہ تعالیٰ ان کے ذریعے سے کسی دن فائدہ دے فرمایا اگر تم لوگ یہ سمجھو کہ تمہارے اوپر اس میں زکوٰۃ ہے جیسے تمہارے ایک انسان پر اس وقت زکوٰۃ واجب ہوتی ہے جب وہ دو سو درہم کا مالک بن جاتا ہے تو پانچ درہم بطور زکوٰۃ دینا لازم ہوتے ہیں تم لوگوں پر اسی طرح اس وقت یہ لازم ہوتا ہے جب تم میں سے کوئی شخص دو سو احادیث سن لیتا ہے کہ وہ ان میں سے پانچ احادیث پر ضرور عمل کرے وگرنہ نظر ڈالو کہ تمہارے اوپر کل کتنا بڑا بوجھ ہو گا۔ امام بیہقی رحمۃ اللہ علیہ نے فرمایا۔ اس فرمان کا اصل مطلب یہ ہے کہ ان کی مراد ان احادیث کے بارے میں تھی جو ترغیب کے بارے میں آئی ہیں نوافل کے سلسلے میں ہیں۔ رہے واجبات تو ان میں سے تو تمام احادیث پر عمل لازمی ہے۔"],[1766,"§طالب علم کی پہچان\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے اور محمد بن موسیٰ نے دونوں نے کہا ہمیں حدیث بیان کی ہے ابو العباس اصم نے ان کو عبد الملک بن عبد الحمید رقی نے ان کو روح نے ان کو ہشام نے ان کو حسن نے وہ کہتے ہیں کہ۔\nایک آدمی طالب علم ہوتا تھا (ہر وقت علم کی طلب میں لگا رہتا تھا) یہاں تک کہ یہ بات اس کی عاجزی سے اور اس کی عادت سے اور اس کی زبان سے اور اس کی نیکی سے واضح طور پر دیکھی جاتی تھی۔"],[1767,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو خبر دی ابراہیم بن عصمہ بن ابراہیم نے ان کو ان کے والد نے ان کو یحییٰ بن یحییٰ نے ان کو سعید بن شمس نے ان کو سلیمان اعمش نے انہوں نے فرمایا۔\nایک آدمی ایک حدیث سنتا تھا تو اس کے علم سے اس کی خوشبو آتی تھی۔"],[1768,"ہمیں خبر دی ہے امام ابو طاہر نے ان کو محمد بن عمر بن حفص نے ان کو یزید بن ہیثم ابو خالد نے ان کو ابراہیم بن نصیر نے وہ کہتے ہیں کہ فضیل بن عیاض نے کہا کہ جس شخص کو ایسا علم ملے کہ جس سے اس کے خوف خدا میں اور حزن و بکاء میں اضافہ نہ ہو وہ اسی قابل ہے کہ اس کو علم غیر نافع ملے۔ اس کے بعد انہوں نے یہ آیت پڑھی:\n﴿افمن هذا الحديث تعجبون وتضحكون ولا تبكون﴾\n’’کیا اس بات سے (قرآن سے) تعجب کرتے ہو اور تم اس پر ہنستے ہو روتے نہیں ہو۔‘‘"],[1769,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے وہ کہتے ہیں کہ میں نے سنا ابو جعفر محمد بن احمد بن سعید رازی سے وہ کہتے ہیں کہ انہوں نے سنا ابو الفضل عباس بن حمزہ سے وہ کہتے کہ انہوں نے سنا ذوالنون مصری سے پہلے اہل میں سے کوئی آدمی ہوتا تھا تو اس کے علم کی وجہ سے دنیا سے اس کے بغض میں اضافہ ہو جاتا تھا اور ترک دنیا میں بھی اور آج ایسا دور ہے کہ انسان کی علم کی وجہ سے دنیا کی محبت اور دنیا کی طلب میں اضافہ ہو جاتا ہے پہلے تو صاحب علم کے ظاہر و باطن میں نکھار آ جاتا تھا اور آج کل اکثر اہل علم میں ظاہر اور باطن کا فساد دیکھنے میں آتا ہے۔"],[1770,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو محمد حسن بن محمد اسفرائنی نے ان کو سعید بن عثمان حناط نے۔ کہتے ہیں کہ میں نے سنا ذوالنون مصری سے کہتے تھے کہ حکیم اور دانا کی شان یہ ہے کہ وہ اپنی حکمت و دانائی کے ذریعے دنیاوی عزت و مقام طلب نہ کرے حکیم جب\n(۱۸۱۲) أخرجه السلمى (ص ۳۵) بنفس الإسناد.\nریاست و سرداری کو پسند کرتا ہے تو اس کے دل سے اللہ کی محبت زائل ہو جاتی ہے۔ اس لئے کہ اس پر اس بات کی پسند کا غلبہ آ جاتا ہے کہ مسلمان ابھی اس کی تعریف کریں۔ لہذا اس کی کیفیت کچھ ایسی ہو جاتی ہے کہ وہ ایک بھی لفظ نہیں بولتا جس سے لوگوں کا نفع ہو کیونکہ اس کے دل پر لوگوں سے اپنی تعریف و تعظیم کی باتیں سننے کے جذبے کا غلبہ ہو جاتا ہے۔"],[1771,"§شقاوت اور بدبختی کی علامات\nہمیں خبر دی ہے ابو عبد الرحمن سلمی نے کہتے ہیں کہ میں نے سنا محمد بن احمد رفا نے وہ کہتے ہیں کہ میں نے سنا ابو بکر بن عثمان سے وہ کہتے ہیں کہ ابو عثمان نے محمد بن فضل کو خط لکھا اور ان سے پوچھا کہ شقاوت کی اور بدبختی کی علامات کیا ہیں؟ انہوں نے جواب دیا کہ تین چیزیں ہیں ایک تو یہ کہ اسے عمل کی توفیق تو میسر ہو جائے عمل خوب کرے مگر اخلاص سے محروم ہو دوسری یہ کہ صالحین کی صحبت تو ظاہر کرے یعنی بظاہر نیکوں میں نشست و برخاست رکھے مگر ان کا احترام نہ کرے۔"],[1772,"میں نے سنا ہے ابو عبد الرحمن سے وہ کہتے ہیں کہ میں نے سنا عبد اللہ بن عبد المطلب سے انہوں نے سنا عبد اللہ بن محمد بن عبید تیمی سے وہ کہتے ہیں (اس دور میں) تین چیزیں غائب ہیں اور تین چیزیں موجود ہیں۔\nعلم موجود ہے اور علم پر عمل مفقود ہے۔\nعمل موجود ہے اور اس میں اخلاص مفقود ہے۔\nمحبت موجود ہے اور اس میں سچائی مفقود ہے۔"],[1773,"§چار چیزیں کمیاب ہیں\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو سعید احمد بن یعقوب ثقفی نے ان کو عباس بن یوسف شکلی نے وہ کہتے ہیں میں نے سنا یحییٰ بن حسین قریشی سے وہ کہتے ہیں چار چیزیں لوگوں میں کمیاب ہیں یعنی تقریباً مفقود ہیں۔\nعالم جو اپنے علم کو استعمال کرے حکیم جو اپنے دل سے بولے اور تارک الدنیا زاہد جسے طمع نہ ہو اور پناہ لینے والا جس کا کوئی تعلق نہ ہو۔"],[1774,"میں نے سنا محمد بن حسین بن محمد سے وہ کہتے ہیں کہ میں نے سنا محمد بن عبد اللہ سے وہ کہتے ہیں میں نے سنا محمد بن فضل سے وہ کہتے ہیں کہ: اسلام کا مٹنا چار چیزوں سے ہے۔ پہلی بات لوگ اپنے علم کے مطابق عمل کریں گے۔ دوسری بات جو بات نہ جانتے ہوں گے اس پر عمل کریں گے (یعنی عمل بغیر علم و مسئلہ کے) تیسری بات وہ چیزیں سیکھیں گے جو نہیں چاہئیں گے۔ چوتھی بات لوگوں کو تعلیم سے روکیں گے۔"],[1775,"§علماء، امراء اور فقراء\nمیں نے سنا ابو عبد الرحمن سلمی سے وہ کہتے ہیں کہ میں نے سنا ابو بکر محمد بن محمد بن شاذان سے وہ کہتے ہیں میں نے سنا محمد بن یعقوب ترمذی سے انہوں نے کہا میں نے سنا ابو بکر وراق سے وہ کہتے تھے لوگ تین طرح کے ہیں۔ علماء، امراء اور فقراء۔ جب امراء میں فساد اور خرابی آ جائے تو معاش اور اجتماعی زندگی میں بگاڑ پیدا ہو جاتا ہے اور علماء میں فساد اور خرابی پیدا ہو جائے تو طاعات و عبادات کے نظام میں فساد آ جاتا ہے اور جب فقراء میں فساد آ جائے تو اخلاق و عادات میں فساد آ جاتا ہے۔\n(۱) في المخطوطة (أبا عثمان) والتصحيح ما أثبتناه.\n(۲) لم يذكر الثالثة."],[1776,"ہمیں خبر دی ہے محمد بن محمد بن محمش نے ان کو ابو بکر فخام نے ان کو محمد بن یحییٰ نے ان کو محمد بن یوسف نے سفیان سے وہ کہتے ہیں کہ حضرت عمر بن عبد العزیز نے فرمایا۔ جو شخص اپنے کلام کو اپنے عمل میں نہ گردانے اس کے گناہ زیادہ ہو جاتے ہیں اور جو شخص علم کے بغیر عمل کرے وہ اصلاح کم اور فساد زیادہ کرے گا۔"],[1777,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو حامد احمد بن محمد بن حسین خسروجردی نے ان کو عبد اللہ بن حارث صنعانی حمیری نے خسروجرد میں ان کو عبد الصمد بن حسان مروزی نے انہوں نے سنا فضیل بن عیاض رضی اللہ عنہ سے وہ فرماتے تھے کہ علم عمل کی دلیل ہے۔"],[1778,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے انہوں نے سنا حسین بن یحییٰ (۱) سے انہوں نے جعفر بن محمد سے انہوں نے سنا ابو عثمان بلدی سے وہ کہتے تھے حارث کہتے ہیں کہ علم خشیت الہی کو پیدا کرتا ہے اور زہد راحت کو اور مغفرت انابت کو۔"],[1779,"§جس نے علم روایت پر عمل کیا\nمیں نے سنا ابو عبد الرحمن سلمی سے وہ کہتے تھے کہ میں نے سنا ابو بکر رازی سے وہ کہتے ہیں کہ میں نے سنا ابن ابی سعدان سے وہ کہتے تھے۔ جس نے روایت پر عمل کیا وہ علم درایت کا وارث بنا جس نے علم درایت پر عمل کیا وہ علم رعایہ کا وارث ہوا اور جس نے علم رعایہ پر عمل کیا اس نے حق کی راہ پالی۔\nانسان عالم کیسے بنتا ہے؟"],[1780,"میں نے سنا ابو عبد الرحمن سلمی سے انہوں نے ابو بکر رازی سے انہوں نے سنا ابراہیم خواص سے وہ کہتے تھے کہ عالم کثرت روایت کے ساتھ نہیں ہوتا، عالم وہ ہوتا ہے جو علم کے تابع ہوتا ہے اور اس علم کو استعمال کرتا ہے اور سنتوں کی اقتدا کرتا اگر چہ قلیل العلم ہو۔"],[1781,"میں نے سنا ابو عبد الرحمن سلمی سے انہوں نے سنا ابو نصر محمد بن احمد مزکی سے انہوں نے سنا عبد اللہ رازی سے وہ کہتے تھے کہ دلائل معرفت علم ہے اور عمل بالعلم اور خوف علی العلم ہے۔"],[1782,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے انہوں نے سنا اسماعیل بن محمد سے انہوں نے اپنے دادا سے انہوں نے علی بن حکیم اودی سے انہوں نے فضیل بن عیاض سے انہوں نے کہا۔ علم دو طرح کے ہیں۔ علم باللسان اور علم بالقلب۔ رہا علم بالقلب یہی علم نافع ہے اور رہا علم باللسان تو یہ اللہ کی حجت ہے اس کی مخلوق پر۔"],[1783,"ہمیں خبر دی ہے احمد بن محمد مالینی نے ان کو احمد بن محمد نے ان کو احمد بن محمد یعقوب بغدادی نے انہوں نے سنا ابو بکر محمد بن منذر تمیمی سے انہوں نے سہل بن عبد اللہ سے وہ کہتے ہیں۔ (۲)\nکوئی شخص علم سے بڑھ کر کوئی شخص دوسری افضل شئی عطا نہیں کیا گیا جس کے ساتھ رشد و ہدایت حاصل کی جائے اللہ تعالیٰ کی طرف محتاج ہونے کے اعتبار سے۔\n(۱۸۲۱) أخرجه السلمى (ص ۵۸) من طريق الخلدى عن أبى عثمان البلدى. به.\n(۱) في الهامش: سقط من أصل السماع ما بين العلامتين.\n(۱۸۲۲) أخرجه السلمى (ص ۲۸۵) عن أبى بكر الرازى. به.\n(۲) في الهامش ما نصه: سقط من أصل السماع."],[1784,"§علم بالعمل کسر نفسی کو پیدا کرتا ہے\nہمیں خبر دی ہے ابو علی روزباری نے ان کو ابو بکر محمد بن مہرویہ رازی نے ان کو محمد بن ہاشم حرماح نے طوس سے ان کو محمد بن اسلم نے ان کو احمد بن یسع نے ان کو جعفر بن سلیمان نے ان کو مالک بن دینار نے وہ فرماتے ہیں جب بندہ علم کو طلب کرتا ہے کہ اس پر عمل کرے اس کا علم اس کو توڑ دیتا ہے (یعنی کسر نفس اور عاجزی سکھا دیتا ہے) اور جب کوئی شخص علم طلب کرے غیر عمل کے لئے علم اس کے تکبر کو بڑھا دیتا ہے۔"],[1785,"ہمیں خبر دی ہے ابو القاسم مجالد بجلی نے کوفہ میں ان کو ابو الحسین مسلم بن محمد بن احمد بن مسلم تمیمی نے ان کو حضرمی نے ان کو سعید بن عمر اشعثی نے ان کو جعفر بن سلیمان نے وہ کہتے ہیں کہ میں نے مالک بن دینار سے سنا وہ فرماتے تھے کہ قلب جب تک محفوظ نہ ہو ایسے ہے جیسے گھر میں جب رہائش نہ ہو تو ویران ہو جاتا ہے۔"],[1786,"اور فرمایا کہ جب بندہ علم کو طلب کرتا ہے تا کہ اس کے پر عمل کرے تو علم اس کو توڑ دیتا ہے اور جب بے عملی کے لئے اس کو طلب کرتا ہے تو وہ علم فخر و غرور میں اضافہ کرتا ہے۔"],[1787,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو العباس اصم نے ان کو عباس دوری نے ان کو یحییٰ بن معین نے ان کو جریر نے ان کو فضیل بن غزوان نے وہ کہتے ہیں کہ علی بن حسین نے کہا جو شخص ایک بار ہنستا ہے تو وہ علم کی کلی کرتا ہے۔"],[1788,"ہمیں خبر دی ہے محمد بن حسین نے انہوں نے سنا علی حشاد اصالح سے اس نے سنا عبد اللہ رازی نے ان سے سوال کیا گیا یا میں نے سوال کیا ان سے کہ کیا بات ہے لوگ اپنے اپنے عیبوں کو پہچانتے ہیں اور عیبوں میں جو قباحت ہے اس کو بھی وہ جانتے ہیں مگر اس کے باوجود وہ ان عیبوں کو چھوڑتے ہیں اور نہ ہی راہ صواب کی طرف رجوع کرتے ہیں۔\nانہوں نے فرمایا۔ اس لئے کہ وہ علم کے ساتھ فخر و غرور میں مبتلا ہیں اور علم کو استعمال کرنے میں مصروف نہیں ہیں۔ ظاہر کے آداب میں مشغول ہیں، اور باطن کے سنوارنے کو چھوڑ چکے ہیں لہذا اللہ تعالیٰ نے ان کے دلوں کو راہ صواب سے اندھا کر دیا ہے اور ان کے اعضاء کو عبادات میں لگا رکھا ہے۔"],[1789,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے ان کو عبد اللہ بن عثمان بن جعفر نے ان کو احمد بن عبد اللہ بن سلیمان نے ان کو یوسف بن موسیٰ نے ان کو وکا بن خثیق نے وہ کہتے ہیں کہ۔\nانہوں نے سنا ابراہیم بکا رحمۃ اللہ علیہ سے کہتے تھے کہ انہوں نے سنا ہے حضرت معروف کرخی سے وہ کہتے تھے۔ جب اللہ تعالیٰ کسی بندے کے ساتھ خیر چاہتے ہیں اس پر عمل کا دروازہ کھول دیتے ہیں اور اس پر جدل اور جھگڑے کا دروازہ بند کر دیتے ہیں۔ اور جس وقت کسی بندے کے ساتھ شر کا اور برائی کا ارادہ کر لیتے ہیں تو اس پر عمل کا دروازہ بند کر دیتے ہیں اور اس پر جھگڑے کا دروازہ کھول دیتے ہیں۔"],[1790,"§ابو بکر وراق کہتے ہیں\nمیں نے سنا سلمی سے انہوں نے سنا ابو بکر رازی سے انہوں نے سنا۔ غیلان سمرقندی سے انہوں نے سنا ابو بکر وراق سے وہ کہتے\n(۱۸۳۰) أخرجه أبو نعيم (۱۳۳/۳، ۱۳۴) من طريق جرير. به.\n(۱) في الأصل (عبيد الله)\n(۱۸۳۲) أخرجه السلمى (ص ۸۷) بنفس الإسناد.\nتھے۔ کہ جو شخص علم میں سے علم کلام پر اکتفاء کرتا ہے زہد اور تقویٰ کے بغیر تو وہ بے دین ہو جاتا ہے اور جو شخص زہد پر اکتفاء کرتا ہے علم فقہ اور کلام کے بغیر تو وہ بدعتی بن جاتا ہے اور جو شخص فقہ پر اکتفاء کرتا ہے زہد اور پرہیزگاری اختیار نہیں کرتا تو وہ فسق میں مبتلا ہو جاتا ہے اور جو شخص تمام علوم مذکور میں مہارت حاصل کرتا ہے وہ چھٹکارا پا لیتا ہے۔"],[1791,"§فقیہ کی پہچان\nہمیں خبر دی ہے ابو عبد اللہ حافظ نے ان کو ابو العباس نیساپوری نے ان کو عبد اللہ بن علی غزال نے ان کو علی بن حسن نے ان کو ابو حمزہ نے ہشام بن حسان سے وہ کہتے ہیں کہ ایک آدمی حضرت حسن کے پاس سے گزرے لوگوں نے کہا کہ یہ فقیہ ہے چنانچہ ان سے پوچھا کہ تم جانتے ہو کہ فقیہ کون ہوتا ہے فقیہ وہ ہوتا ہے جو اپنے دین کا عالم ہوتا ہے اپنی دنیا سے بے غرض ہوتا ہے اپنے رب کی عبادت پر پکا ہوتا ہے۔"],[1792,"ہمیں خبر دی ابو عبد اللہ نے ان کو ابو عمرو بن سماک نے ان کو حسن بن عمرو نے انہوں نے سنا بشر بن حارث سے انہوں نے کہا کہ محمد بن نضر حارثی نے کہا۔ اب اہل علم میں سے کب ہوں گے جبکہ آپ کا رجوع آخرت کی طرف ہو جائے حالانکہ آپ کام دنیا میں کر رہے ہوں۔"],[1793,"اپنی اسناد کے ساتھ انہوں نے کہا کہ میں نے بشر سے سنا وہ کہتے تھے کہ عالم پکڑ کیا ہے؟\nفرمایا اس کا دنیا سے محبت کرنا جو بھر جائے اور اس کے دل کو بند کر دے۔"],[1794,"ہمیں خبر دی ابو عبد اللہ حافظ نے ان کو ابو العباس صفار نے ان کو عبد اللہ بن علی غزال نے ان کو علی بن حسن بن شقیق نے ان کو عبد اللہ بن مبارک ان کو مالک بن دینار نے انہوں نے پوچھا حسن سے کہ عالم کی پکڑ اور سزا کیا ہے؟\nانہوں نے جواب دیا۔ قلب کی موت۔ میں نے پوچھا کہ قلب کی موت کیا ہوتی ہے؟ فرمایا کہ آخرت کے عمل کے بدلے میں دنیا کو طلب کرنا۔"],[1795,"ہمیں خبر دی ہے ابو عبد اللہ حافظ نے اور محمد بن موسیٰ نے دونوں کو ابو العباس اصم نے ان کو عباس بن ولید بن مزید نے ان کو ان کے والد نے ان کو اوزاعی نے انہوں نے سنا بلال بن سعد سے وہ کہتے تھے۔ کہ تمہارے زاہد تارک الدنیا دنیا میں رغبت کرنے لگے ہیں تمہارے عالم جاہل ہیں اور تمہارے جاہل مغرور ہیں۔ (یا جاہل دھوکہ خوردہ ہیں)"],[1796,"§علم کو دنیا کے لئے حاصل کرنا رسوائی ہے\nہمیں حدیث بیان کی ہے عبد الملک بن ابی عثمان زاہد نیان کو علی بن یوسف نصیبی نے مکہ میں ان کو عبد اللہ بن محمد مفسر نے ان کو محمد بن حامد نے ان کو محمد بن مثنیٰ نے وہ کہتے ہیں کہ میں نے سنا بشر بن حارث سے کہتے تھے کسی شخص کے لئے یہ مناسب نہیں ہے کہ کہیں کسی ایسی حاجت کے موقع پر حوائج دنیا میں سے کسی حدیث کا ذکر کرے جس کی طرف قریب ہونے کا ارادہ کرے۔ اور دنیا کے ذکر کے کسی موقع پر علم کا ذکر و بیان نہ کرے۔ میں نے کئی مشائخ کو دیکھا ہے جنہوں نے علم حاصل کیا دنیا کے لئے تو وہ رسوا ہو گئے۔ کچھ اور مشائخ نے علم حاصل کیا اور انہوں نے اس کو برمحل استعمال کیا اور اس کو اس کا مقام دیا اور اس پر عمل کیا اور اس کو قائم کیا وہی لوگ بچ گئے اور انہیں اللہ نے علم سے نفع بھی دیا۔\n(۱۸۳۳) أخرجه السلمى (ص ۲۲۴) بنفس الإسناد.\n(۱۸۳۸) أخرجه أبو نعيم في الحلية (۲۲۵/۵) من طريق عباس بن الوليد. به.\n(۱۸۳۹) أخرجه أبو نعيم في الحلية (۳۴۹/۸) من طريق محمد بن المثنى. به."],[1797,"ہمیں خبر دی ہے ابو عبد الرحمن سلمی نے کہتے ہیں میں نے سنا ابو بکر رازی سے کہتے ہیں کہ میں نے سنا محمد بن اشعث بیکندی سے وہ کہتے ہیں کہ۔\nجو شخص زہد کے بارے میں کلام کرے اور لوگوں کو وعظ کرے اور اس کے بعد خود اسی شئی کی رغبت کرے جو چیز ان لوگوں کی پسندیدہ ہے اللہ تعالیٰ اس کی دل سے آخرت کی محبت اٹھا لیتے ہیں۔"],[1798,"§مالک بن دینار کہتے ہیں\nہمیں خبر دی ہے فقیہ ابو اسحاق ابراہیم بن محمد بن ابراہیم طوسی نے ان کو فقیہ ابو الولید حسان بن محمد نے وہ کہتے ہیں میں نے سنا محمد بن اسحاق سے وہ کہتے ہیں کہ ہمیں حدیث بیان کی ہے عبد اللہ بن حکم بن ابو زیاد قطرانی نے ان کو سیار نے ان کو جعفر بن سلیمان انہوں نے سنا مالک بن دینار سے وہ کہتے تھے۔ میں نے توراۃ میں پڑھا تھا کہ عالم جب اپنے علم پر عمل نہ کرے اس کی وعظ و نصیحت دلوں سے ایسے مٹ جاتی ہے جیسے صاف پتھر کے اوپر سے قطر زائل ہو جاتا ہے۔\nسلف کے کلام اور ہمارے کلام میں فرق کیوں ہے؟"],[1799,"میں نے سنا ابو عبد الرحمن سلمی سے انہوں نے سنا محمد بن احمد فراء سے وہ کہتے ہیں۔ حمدون دھوبی سے کہا گیا کیا بات ہے کہ سلف کا کلام ہمارے کلام سے زیادہ نفع مند ہے انہوں نے کہا۔ اس لئے کہ وہ کلام کرتے تھے اسلام کی عزت اور غلبے کے لئے اور نفوس کی نجات کے لئے اور رحمن کی رضا کے لئے۔ اور ہم کلام کرتے ہیں عزت نفس کے لئے طلب دنیا کے لئے اور مخلوق کی بات کرتے ہیں۔"],[1800,"§تین قسم کے فتنے\nمیں نے سنا ابو عبد الرحمن سے وہ کہتے ہیں کہ میں نے سنا ابو نصر عبد اللہ بن علی سے انہوں نے سنا داتی سے وہ کہتے ہیں میں نے سنا ابو بکر فرغانی سے کہتے تھے حکایت کرتے تھے سہل بن عبد اللہ سے وہ کہتے ہیں فتنے تین قسم ہیں عام فتنے یعنی علم کو ضائع کرنا اور خاص فتنہ یعنی رخصتوں سے اور تاویلات سے کام لینا۔ اور اہل معرفت کا فتنہ ان کو کوئی حق لازم ہو پھر اس کو وہ مؤخر کر دیں دوسرے وقت کی طرف۔"]])